  Sentence[343] = "貪財的背棄耶和華，";
  Sentence[344] = "並且輕慢他。";
  Sentence[345] = "惡人面帶驕傲，";
  Sentence[346] = "說：";
  Sentence[347] = "耶和華必不追究；";
  Sentence[348] = "他一切所想的都以為沒有神。";
  Sentence[349] = "凡他所做的，";
  Sentence[350] = "時常穩固；";
  Sentence[351] = "你的審判超過他的眼界。";
  Sentence[352] = "至於他一切的敵人，";
  Sentence[353] = "他都向他們噴氣。";
  Sentence[354] = "他心裡說：";
  Sentence[355] = "我必不動搖，";
  Sentence[356] = "世世代代不遭災難。";
  Sentence[357] = "他滿口是咒罵、";
  Sentence[358] = "詭詐、";
  Sentence[359] = "欺壓，";
  Sentence[360] = "舌底是毒害、";
  Sentence[361] = "奸惡。";
  Sentence[362] = "他在村莊埋伏等候；";
  Sentence[363] = "他在隱密處殺害無辜的人。";
  Sentence[364] = "他的眼睛窺探無倚無靠的人；";
  Sentence[365] = "他埋伏在暗地，";
  Sentence[366] = "如獅子蹲在洞中。";
  Sentence[367] = "他埋伏，";
  Sentence[368] = "要擄去困苦人；";
  Sentence[369] = "他拉網，";
  Sentence[370] = "就把困苦人擄去。";
  Sentence[371] = "他屈身蹲伏，";
  Sentence[372] = "無倚無靠的人就倒在他爪牙之下。";
  Sentence[373] = "他心裡說：";
  Sentence[374] = "神竟忘記了；";
  Sentence[375] = "他掩面永不觀看。";
  Sentence[376] = "耶和華啊，";
  Sentence[377] = "求你起來！";
  Sentence[378] = "神啊，";
  Sentence[379] = "求你舉手，";
  Sentence[380] = "不要忘記困苦人！";
  Sentence[381] = "惡人為何輕慢神，";
  Sentence[382] = "心裡說：";
  Sentence[383] = "你必不追究？";
  Sentence[384] = "其實你已經觀看；";
  Sentence[385] = "因為奸惡毒害，";
  Sentence[386] = "你都看見了，";
  Sentence[387] = "為要以手施行報應。";
  Sentence[388] = "無倚無靠的人把自己交託你；";
  Sentence[389] = "你向來是幫助孤兒的。";
  Sentence[390] = "願你打斷惡人的膀臂；";
  Sentence[391] = "至於壞人，";
  Sentence[392] = "願你追究他的惡，";
  Sentence[393] = "直到淨盡。";
  Sentence[394] = "耶和華永永遠遠為王；";
  Sentence[395] = "外邦人從他的地已經滅絕了。";
  Sentence[396] = "耶和華啊，";
  Sentence[397] = "謙卑人的心願，";
  Sentence[398] = "你早已知道。";
  Sentence[399] = "你必預備他們的心，";
  Sentence[400] = "也必側耳聽他們的祈求，";
  Sentence[401] = "為要給孤兒和受欺壓的人伸冤，";
  Sentence[402] = "使強橫的人不再威嚇他們。";
  Sentence[403] = "詩篇十一篇";
  Sentence[404] = "我是投靠耶和華；";
  Sentence[405] = "你們怎麼對我說：";
  Sentence[406] = "你當像鳥飛往你的山去。";
  Sentence[407] = "看哪，";
  Sentence[408] = "惡人彎弓，";
  Sentence[409] = "把箭搭在弦上，";
  Sentence[410] = "要在暗中射那心裡正直的人。";
  Sentence[411] = "根基若毀壞，";
  Sentence[412] = "義人還能做什麼呢？";
  Sentence[413] = "耶和華在他的聖殿裡；";
  Sentence[414] = "耶和華的寶座在天上；";
  Sentence[415] = "他的慧眼察看世人。";
  Sentence[416] = "耶和華試驗義人；";
  Sentence[417] = "惟有惡人和喜愛強暴的人，";
  Sentence[418] = "他心裡恨惡。";
  Sentence[419] = "他要向惡人密布網羅；";
  Sentence[420] = "有烈火、";
  Sentence[421] = "硫磺、";
  Sentence[422] = "熱風，";
  Sentence[423] = "作他們杯中的分。";
  Sentence[424] = "因為耶和華是公義的，";
  Sentence[425] = "他喜愛公義；";
  Sentence[426] = "正直人必得見他的面。";
  Sentence[427] = "詩篇十二篇";
  Sentence[428] = "耶和華啊，";
  Sentence[429] = "求你幫助，";
  Sentence[430] = "因虔誠人斷絕了；";
  Sentence[431] = "世人中間的忠信人沒有了。";
  Sentence[432] = "人人向鄰舍說謊；";
  Sentence[433] = "他們說話，";
  Sentence[434] = "是嘴唇油滑，";
  Sentence[435] = "心口不一。";
  Sentence[436] = "凡油滑的嘴唇和誇大的舌頭，";
  Sentence[437] = "耶和華必要剪除。";
  Sentence[438] = "他們曾說：";
  Sentence[439] = "我們必能以舌頭得勝；";
  Sentence[440] = "我們的嘴唇是我們自己的，";
  Sentence[441] = "誰能作我們的主呢？";
  Sentence[442] = "耶和華說：";
  Sentence[443] = "因為困苦人的冤屈和貧窮人的歎息，";
  Sentence[444] = "我現在要起來，";
  Sentence[445] = "把他安置在他所切慕的穩妥之地。";
  Sentence[446] = "耶和華的言語是純淨的言語，";
  Sentence[447] = "如同銀子在泥爐中煉過七次。";
  Sentence[448] = "耶和華啊，";
  Sentence[449] = "你必保護他們；";
  Sentence[450] = "你必保佑他們永遠脫離這世代的人。";
  Sentence[451] = "下流人在世人中升高，";
  Sentence[452] = "就有惡人到處遊行。";
  Sentence[453] = "詩篇十三篇";
  Sentence[454] = "耶和華啊，";
  Sentence[455] = "你忘記我要到幾時呢？";
  Sentence[456] = "要到永遠嗎？";
  Sentence[457] = "你掩面不顧我要到幾時呢？";
  Sentence[458] = "我心裡籌算，";
  Sentence[459] = "終日愁苦，";
  Sentence[460] = "要到幾時呢？";
  Sentence[461] = "我的仇敵升高壓制我，";
  Sentence[462] = "要到幾時呢？";
  Sentence[463] = "耶和華－";
  Sentence[464] = "我的神啊，";
  Sentence[465] = "求你看顧我，";
  Sentence[466] = "應允我！";
  Sentence[467] = "使我眼目光明，";
  Sentence[468] = "免得我沉睡至死；";
  Sentence[469] = "免得我的仇敵說：";
  Sentence[470] = "我勝了他；";
  Sentence[471] = "免得我的敵人在我搖動的時候喜樂。";
  Sentence[472] = "但我倚靠你的慈愛；";
  Sentence[473] = "我的心因你的救恩快樂。";
  Sentence[474] = "我要向耶和華歌唱，";
  Sentence[475] = "因他用厚恩待我。";
  Sentence[476] = "詩篇十四篇";
  Sentence[477] = "愚頑人心裡說：";
  Sentence[478] = "沒有神。";
  Sentence[479] = "他們都是邪惡，";
  Sentence[480] = "行了可憎惡的事；";
  Sentence[481] = "沒有一個人行善。";
  Sentence[482] = "耶和華從天上垂看世人，";
  Sentence[483] = "要看有明白的沒有，";
  Sentence[484] = "有尋求神的沒有。";
  Sentence[485] = "他們都偏離正路，";
  Sentence[486] = "一同變為污穢；";
  Sentence[487] = "並沒有行善的，";
  Sentence[488] = "連一個也沒有。";
  Sentence[489] = "作孽的都沒有知識嗎？";
  Sentence[490] = "他們吞吃我的百姓，";
  Sentence[491] = "如同吃飯一樣，";
  Sentence[492] = "並不求告耶和華。";
  Sentence[493] = "他們在那裡大大地害怕，";
  Sentence[494] = "因為神在義人的族類中。";
  Sentence[495] = "你們叫困苦人的謀算變為羞辱；";
  Sentence[496] = "然而耶和華是他的避難所。";
  Sentence[497] = "但願以色列的救恩從錫安而出。";
  Sentence[498] = "耶和華救回他被擄的子民那時，";
  Sentence[499] = "雅各要快樂，";
  Sentence[500] = "以色列要歡喜。";
  Sentence[501] = "詩篇十五篇";
  Sentence[502] = "耶和華啊，";
  Sentence[503] = "誰能寄居你的帳幕？";
  Sentence[504] = "誰能住在你的聖山？";
  Sentence[505] = "就是行為正直、";
  Sentence[506] = "做事公義、";
  Sentence[507] = "心裡說實話的人。";
  Sentence[508] = "他不以舌頭讒謗人，";
  Sentence[509] = "不惡待朋友，";
  Sentence[510] = "也不隨夥毀謗鄰里。";
  Sentence[511] = "他眼中藐視匪類，";
  Sentence[512] = "卻尊重那敬畏耶和華的人。";
  Sentence[513] = "他發了誓，";
  Sentence[514] = "雖然自己吃虧也不更改。";
  Sentence[515] = "他不放債取利，";
  Sentence[516] = "不受賄賂以害無辜。";
  Sentence[517] = "行這些事的人必永不動搖。";
  Sentence[518] = "詩篇十六篇";
  Sentence[519] = "神啊，";
  Sentence[520] = "求你保佑我，";
  Sentence[521] = "因為我投靠你。";
  Sentence[522] = "我的心哪，";
  Sentence[523] = "你曾對耶和華說：";
  Sentence[524] = "你是我的主；";
  Sentence[525] = "我的好處不在你以外。";
  Sentence[526] = "論到世上的聖民，";
  Sentence[527] = "他們又美又善，";
  Sentence[528] = "是我最喜悅的。";
  Sentence[529] = "以別神代替耶和華的，";
  Sentence[530] = "他們的愁苦必加增；";
  Sentence[531] = "他們所澆奠的血我不獻上；";
  Sentence[532] = "我嘴唇也不提別神的名號。";
  Sentence[533] = "耶和華是我的產業，";
  Sentence[534] = "是我杯中的分；";
  Sentence[535] = "我所得的，";
  Sentence[536] = "你為我持守。";
  Sentence[537] = "用繩量給我的地界，";
  Sentence[538] = "坐落在佳美之處；";
  Sentence[539] = "我的產業實在美好。";
  Sentence[540] = "我必稱頌那指教我的耶和華；";
  Sentence[541] = "我的心腸在夜間也警戒我。";
  Sentence[542] = "我將耶和華常擺在我面前，";
  Sentence[543] = "因他在我右邊，";
  Sentence[544] = "我便不致搖動。";
  Sentence[545] = "因此，";
  Sentence[546] = "我的心歡喜，";
  Sentence[547] = "我的靈快樂；";
  Sentence[548] = "我的肉身也要安然居住。";
  Sentence[549] = "因為你必不將我的靈魂撇在陰間，";
  Sentence[550] = "也不叫你的聖者見朽壞。";
  Sentence[551] = "你必將生命的道路指示我。";
  Sentence[552] = "在你面前有滿足的喜樂；";
  Sentence[553] = "在你右手中有永遠的福樂。";
  Sentence[554] = "詩篇十七篇";
  Sentence[555] = "耶和華啊，";
  Sentence[556] = "求你聽聞公義，";
  Sentence[557] = "側耳聽我的呼籲！";
  Sentence[558] = "求你留心聽我這不出於詭詐嘴唇的祈禱！";
  Sentence[559] = "願我的判語從你面前發出；";
  Sentence[560] = "願你的眼睛觀看公正。";
  Sentence[561] = "你已經試驗我的心；";
  Sentence[562] = "你在夜間鑒察我；";
  Sentence[563] = "你熬煉我，";
  Sentence[564] = "卻找不著什麼；";
  Sentence[565] = "我立志叫我口中沒有過失。";
  Sentence[566] = "論到人的行為，";
  Sentence[567] = "我藉著你嘴唇的言語自己謹守，";
  Sentence[568] = "不行強暴人的道路。";
  Sentence[569] = "我的腳踏定了你的路徑；";
  Sentence[570] = "我的兩腳未曾滑跌。";
  Sentence[571] = "神啊，";
  Sentence[572] = "我曾求告你，";
  Sentence[573] = "因為你必應允我；";
  Sentence[574] = "求你向我側耳，";
  Sentence[575] = "聽我的言語。";
  Sentence[576] = "求你顯出你奇妙的慈愛來；";
  Sentence[577] = "你是那用右手拯救投靠你的脫離起來攻擊他們的人。";
  Sentence[578] = "求你保護我，";
  Sentence[579] = "如同保護眼中的瞳人；";
  Sentence[580] = "將我隱藏在你翅膀的蔭下，";
  Sentence[581] = "使我脫離那欺壓我的惡人，";
  Sentence[582] = "就是圍困我要害我命的仇敵。";
  Sentence[583] = "他們的心被脂油包裹；";
  Sentence[584] = "他們用口說驕傲的話。";
  Sentence[585] = "他們圍困了我們的腳步；";
  Sentence[586] = "他們瞪著眼，";
  Sentence[587] = "要把我們推倒在地。";
  Sentence[588] = "他像獅子急要抓食，";
  Sentence[589] = "又像少壯獅子蹲伏在暗處。";
  Sentence[590] = "耶和華啊，";
  Sentence[591] = "求你起來，";
  Sentence[592] = "前去迎敵，";
  Sentence[593] = "將他打倒！";
  Sentence[594] = "用你的刀救護我命脫離惡人。";
  Sentence[595] = "耶和華啊，";
  Sentence[596] = "求你用手救我脫離世人，";
  Sentence[597] = "脫離那只在今生有福分的世人！";
  Sentence[598] = "你把你的財寶充滿他們的肚腹；";
  Sentence[599] = "他們因有兒女就心滿意足，";
  Sentence[600] = "將其餘的財物留給他們的嬰孩。";
  Sentence[601] = "至於我，";
  Sentence[602] = "我必在義中見你的面；";
  Sentence[603] = "我醒了的時候，";
  Sentence[604] = "得見你的形像就心滿意足了。";
  Sentence[605] = "詩篇十八篇";
  Sentence[606] = "耶和華，";
  Sentence[607] = "我的力量啊，";
  Sentence[608] = "我愛你！";
  Sentence[609] = "耶和華是我的巖石，";
  Sentence[610] = "我的山寨，";
  Sentence[611] = "我的救主，";
  Sentence[612] = "我的神，";
  Sentence[613] = "我的磐石，";
  Sentence[614] = "我所投靠的。";
  Sentence[615] = "他是我的盾牌，";
  Sentence[616] = "是拯救我的角，";
  Sentence[617] = "是我的高臺。";
  Sentence[618] = "我要求告當讚美的耶和華；";
  Sentence[619] = "這樣我必從仇敵手中被救出來。";
  Sentence[620] = "曾有死亡的繩索纏繞我，";
  Sentence[621] = "匪類的急流使我驚懼，";
  Sentence[622] = "陰間的繩索纏繞我，";
  Sentence[623] = "死亡的網羅臨到我。";
  Sentence[624] = "我在急難中求告耶和華，";
  Sentence[625] = "向我的神呼求。";
  Sentence[626] = "他從殿中聽了我的聲音；";
  Sentence[627] = "我在他面前的呼求入了他的耳中。";
  Sentence[628] = "那時，";
  Sentence[629] = "因他發怒，";
  Sentence[630] = "地就搖撼戰抖；";
  Sentence[631] = "山的根基也震動搖撼。";
  Sentence[632] = "從他鼻孔冒煙上騰；";
  Sentence[633] = "從他口中發火焚燒，";
  Sentence[634] = "連炭也著了。";
  Sentence[635] = "他又使天下垂，";
  Sentence[636] = "親自降臨，";
  Sentence[637] = "有黑雲在他腳下。";
  Sentence[638] = "他坐著基路伯飛行；";
  Sentence[639] = "他藉著風的翅膀快飛。";
  Sentence[640] = "他以黑暗為藏身之處，";
  Sentence[641] = "以水的黑暗、";
  Sentence[642] = "天空的厚雲為他四圍的行宮。";
  Sentence[643] = "因他面前的光輝，";
  Sentence[644] = "他的厚雲行過便有冰雹火炭。";
  Sentence[645] = "耶和華也在天上打雷；";
  Sentence[646] = "至高者發出聲音便有冰雹火炭。";
  Sentence[647] = "他射出箭來，";
  Sentence[648] = "使仇敵四散；";
  Sentence[649] = "多多發出閃電，";
  Sentence[650] = "使他們擾亂。";
  Sentence[651] = "耶和華啊，";
  Sentence[652] = "你的斥責一發，";
  Sentence[653] = "你鼻孔的氣一出，";
  Sentence[654] = "海底就出現，";
  Sentence[655] = "大地的根基也顯露。";
  Sentence[656] = "他從高天伸手抓住我，";
  Sentence[657] = "把我從大水中拉上來。";
  Sentence[658] = "他救我脫離我的勁敵和那些恨我的人，";
  Sentence[659] = "因為他們比我強盛。";
  Sentence[660] = "我遭遇災難的日子，";
  Sentence[661] = "他們來攻擊我；";
  Sentence[662] = "但耶和華是我的倚靠。";
  Sentence[663] = "他又領我到寬闊之處；";
  Sentence[664] = "他救拔我，";
  Sentence[665] = "因他喜悅我。";
  Sentence[666] = "耶和華按著我的公義報答我，";
  Sentence[667] = "按著我手中的清潔賞賜我。";
  Sentence[668] = "因為我遵守了耶和華的道，";
  Sentence[669] = "未曾作惡離開我的神。";
  Sentence[670] = "他的一切典章常在我面前；";
  Sentence[671] = "他的律例我也未曾丟棄。";
  Sentence[672] = "我在他面前作了完全人；";
  Sentence[673] = "我也保守自己遠離我的罪孽。";
  Sentence[674] = "所以，";
  Sentence[675] = "耶和華按我的公義，";
  Sentence[676] = "按我在他眼前手中的清潔償還我。";
  Sentence[677] = "慈愛的人，";
  Sentence[678] = "你以慈愛待他；";
  Sentence[679] = "完全的人，";
  Sentence[680] = "你以完全待他。";
  Sentence[681] = "清潔的人，";
  Sentence[682] = "你以清潔待他；";
  Sentence[683] = "乖僻的人，";
  Sentence[684] = "你以彎曲待他。";
  Sentence[685] = "困苦的百姓，";
  Sentence[686] = "你必拯救；";
  Sentence[687] = "高傲的眼目，";
  Sentence[688] = "你必使他降卑。";
  Sentence[689] = "你必點著我的燈；";
  Sentence[690] = "耶和華－";
  Sentence[691] = "我的神必照明我的黑暗。";
  Sentence[692] = "我藉著你衝入敵軍，";
  Sentence[693] = "藉著我的神跳過牆垣。";
  Sentence[694] = "至於神，";
  Sentence[695] = "他的道是完全的；";
  Sentence[696] = "耶和華的話是煉淨的。";
  Sentence[697] = "凡投靠他的，";
  Sentence[698] = "他便作他們的盾牌。";
  Sentence[699] = "除了耶和華，";
  Sentence[700] = "誰是神呢？";
  Sentence[701] = "除了我們的神，";
  Sentence[702] = "誰是磐石呢？";
  Sentence[703] = "惟有那以力量束我的腰、";
  Sentence[704] = "使我行為完全的，";
  Sentence[705] = "他是神。";
  Sentence[706] = "他使我的腳快如母鹿的蹄，";
  Sentence[707] = "又使我在高處安穩。";
  Sentence[708] = "他教導我的手能以爭戰，";
  Sentence[709] = "甚至我的膀臂能開銅弓。";
  Sentence[710] = "你把你的救恩給我作盾牌；";
  Sentence[711] = "你的右手扶持我；";
  Sentence[712] = "你的溫和使我為大。";
  Sentence[713] = "你使我腳下的地步寬闊；";
  Sentence[714] = "我的腳未曾滑跌。";
  Sentence[715] = "我要追趕我的仇敵，";
  Sentence[716] = "並要追上他們；";
  Sentence[717] = "不將他們滅絕，";
  Sentence[718] = "我總不歸回。";
  Sentence[719] = "我要打傷他們，";
  Sentence[720] = "使他們不能起來；";
  Sentence[721] = "他們必倒在我的腳下。";
  Sentence[722] = "因為你曾以力量束我的腰，";
  Sentence[723] = "使我能爭戰；";
  Sentence[724] = "你也使那起來攻擊我的都服在我以下。";
  Sentence[725] = "你又使我的仇敵在我面前轉背逃跑，";
  Sentence[726] = "叫我能以剪除那恨我的人。";
  Sentence[727] = "他們呼求，";
  Sentence[728] = "卻無人拯救；";
  Sentence[729] = "就是呼求耶和華，";
  Sentence[730] = "他也不應允。";
  Sentence[731] = "我搗碎他們，";
  Sentence[732] = "如同風前的灰塵，";
  Sentence[733] = "倒出他們，";
  Sentence[734] = "如同街上的泥土。";
  Sentence[735] = "你救我脫離百姓的爭競，";
  Sentence[736] = "立我作列國的元首；";
  Sentence[737] = "我素不認識的民必事奉我。";
  Sentence[738] = "他們一聽見我的名聲就必順從我；";
  Sentence[739] = "外邦人要投降我。";
  Sentence[740] = "外邦人要衰殘，";
  Sentence[741] = "戰戰兢兢地出他們的營寨。";
  Sentence[742] = "耶和華是活神。";
  Sentence[743] = "願我的磐石被人稱頌；";
  Sentence[744] = "願救我的神被人尊崇。";
  Sentence[745] = "這位神，";
  Sentence[746] = "就是那為我伸冤、";
  Sentence[747] = "使眾民服在我以下的。";
  Sentence[748] = "你救我脫離仇敵，";
  Sentence[749] = "又把我舉起，";
  Sentence[750] = "高過那些起來攻擊我的；";
  Sentence[751] = "你救我脫離強暴的人。";
  Sentence[752] = "耶和華啊，";
  Sentence[753] = "因此我要在外邦中稱謝你，";
  Sentence[754] = "歌頌你的名。";
  Sentence[755] = "耶和華賜極大的救恩給他所立的王，";
  Sentence[756] = "施慈愛給他的受膏者，";
  Sentence[757] = "就是給大衛和他的後裔，";
  Sentence[758] = "直到永遠。";
  Sentence[759] = "詩篇十九篇";
  Sentence[760] = "諸天述說神的榮耀；";
  Sentence[761] = "穹蒼傳揚他的手段。";
  Sentence[762] = "這日到那日發出言語；";
  Sentence[763] = "這夜到那夜傳出知識。";
  Sentence[764] = "無言無語，";
  Sentence[765] = "也無聲音可聽。";
  Sentence[766] = "他的量帶通遍天下，";
  Sentence[767] = "他的言語傳到地極。";
  Sentence[768] = "神在其間為太陽安設帳幕；";
  Sentence[769] = "太陽如同新郎出洞房，";
  Sentence[770] = "又如勇士歡然奔路。";
  Sentence[771] = "他從天這邊出來，";
  Sentence[772] = "繞到天那邊，";
  Sentence[773] = "沒有一物被隱藏不得他的熱氣。";
  Sentence[774] = "耶和華的律法全備，";
  Sentence[775] = "能甦醒人心；";
  Sentence[776] = "耶和華的法度確定，";
  Sentence[777] = "能使愚人有智慧。";
  Sentence[778] = "耶和華的訓詞正直，";
  Sentence[779] = "能快活人的心；";
  Sentence[780] = "耶和華的命令清潔，";
  Sentence[781] = "能明亮人的眼目。";
  Sentence[782] = "耶和華的道理潔淨，";
  Sentence[783] = "存到永遠；";
  Sentence[784] = "耶和華的典章真實，";
  Sentence[785] = "全然公義－";
  Sentence[786] = "都比金子可羨慕，";
  Sentence[787] = "且比極多的精金可羨慕；";
  Sentence[788] = "比蜜甘甜，";
  Sentence[789] = "且比蜂房下滴的蜜甘甜。";
  Sentence[790] = "況且你的僕人因此受警戒，";
  Sentence[791] = "守著這些便有大賞。";
  Sentence[792] = "誰能知道自己的錯失呢？";
  Sentence[793] = "願你赦免我隱而未現的過錯。";
  Sentence[794] = "求你攔阻僕人不犯任意妄為的罪，";
  Sentence[795] = "不容這罪轄制我，";
  Sentence[796] = "我便完全，";
  Sentence[797] = "免犯大罪。";
  Sentence[798] = "耶和華－";
  Sentence[799] = "我的磐石，";
  Sentence[800] = "我的救贖主啊，";
  Sentence[801] = "願我口中的言語、";
  Sentence[802] = "心裡的意念在你面前蒙悅納。";
  Sentence[803] = "詩篇二十篇";
  Sentence[804] = "願耶和華在你遭難的日子應允你；";
  Sentence[805] = "願名為雅各神的高舉你。";
  Sentence[806] = "願他從聖所救助你，";
  Sentence[807] = "從錫安堅固你，";
  Sentence[808] = "記念你的一切供獻，";
  Sentence[809] = "悅納你的燔祭，";
  Sentence[810] = "將你心所願的賜給你，";
  Sentence[811] = "成就你的一切籌算。";
  Sentence[812] = "我們要因你的救恩誇勝，";
  Sentence[813] = "要奉我們神的名豎立旌旗。";
  Sentence[814] = "願耶和華成就你一切所求的！";
  Sentence[815] = "現在我知道耶和華救護他的受膏者，";
  Sentence[816] = "必從他的聖天上應允他，";
  Sentence[817] = "用右手的能力救護他。";
  Sentence[818] = "有人靠車，";
  Sentence[819] = "有人靠馬，";
  Sentence[820] = "但我們要提到耶和華－";
  Sentence[821] = "我們神的名。";
  Sentence[822] = "他們都屈身仆倒，";
  Sentence[823] = "我們卻起來，";
  Sentence[824] = "立得正直。";
  Sentence[825] = "求耶和華施行拯救；";
  Sentence[826] = "我們呼求的時候，";
  Sentence[827] = "願王應允我們！";
  Sentence[828] = "詩篇廿一篇";
  Sentence[829] = "耶和華啊，";
  Sentence[830] = "王必因你的能力歡喜；";
  Sentence[831] = "因你的救恩，";
  Sentence[832] = "他的快樂何其大！";
  Sentence[833] = "他心裡所願的，";
  Sentence[834] = "你已經賜給他；";
  Sentence[835] = "他嘴唇所求的，";
  Sentence[836] = "你未嘗不應允。";
  Sentence[837] = "你以美福迎接他，";
  Sentence[838] = "把精金的冠冕戴在他頭上。";
  Sentence[839] = "他向你求壽，";
  Sentence[840] = "你便賜給他，";
  Sentence[841] = "就是日子長久，";
  Sentence[842] = "直到永遠。";
  Sentence[843] = "他因你的救恩大有榮耀；";
  Sentence[844] = "你又將尊榮威嚴加在他身上。";
  Sentence[845] = "你使他有洪福，";
  Sentence[846] = "直到永遠，";
  Sentence[847] = "又使他在你面前歡喜快樂。";
  Sentence[848] = "王倚靠耶和華，";
  Sentence[849] = "因至高者的慈愛必不搖動。";
  Sentence[850] = "你的手要搜出你的一切仇敵；";
  Sentence[851] = "你的右手要搜出那些恨你的人。";
  Sentence[852] = "你發怒的時候，";
  Sentence[853] = "要使他們如在炎熱的火爐中。";
  Sentence[854] = "耶和華要在他的震怒中吞滅他們；";
  Sentence[855] = "那火要把他們燒盡了。";
  Sentence[856] = "你必從世上滅絕他們的子孫，";
  Sentence[857] = "從人間滅絕他們的後裔。";
  Sentence[858] = "因為他們有意加害於你；";
  Sentence[859] = "他們想出計謀，";
  Sentence[860] = "卻不能做成。";
  Sentence[861] = "你必使他們轉背逃跑，";
  Sentence[862] = "向他們的臉搭箭在弦。";
  Sentence[863] = "耶和華啊，";
  Sentence[864] = "願你因自己的能力顯為至高！";
  Sentence[865] = "這樣，";
  Sentence[866] = "我們就唱詩，";
  Sentence[867] = "歌頌你的大能。";
  Sentence[868] = "詩篇廿二篇";
  Sentence[869] = "我的神，";
  Sentence[870] = "我的神！";
  Sentence[871] = "為什麼離棄我？";
  Sentence[872] = "為什麼遠離不救我？";
  Sentence[873] = "不聽我唉哼的言語？";
  Sentence[874] = "我的神啊，";
  Sentence[875] = "我白日呼求，";
  Sentence[876] = "你不應允，";
  Sentence[877] = "夜間呼求，";
  Sentence[878] = "並不住聲。";
  Sentence[879] = "但你是聖潔的，";
  Sentence[880] = "是用以色列的讚美為寶座的。";
  Sentence[881] = "我們的祖宗倚靠你；";
  Sentence[882] = "他們倚靠你，";
  Sentence[883] = "你便解救他們。";
  Sentence[884] = "他們哀求你，";
  Sentence[885] = "便蒙解救；";
  Sentence[886] = "他們倚靠你，";
  Sentence[887] = "就不羞愧。";
  Sentence[888] = "但我是蟲，";
  Sentence[889] = "不是人，";
  Sentence[890] = "被眾人羞辱，";
  Sentence[891] = "被百姓藐視。";
  Sentence[892] = "凡看見我的都嗤笑我；";
  Sentence[893] = "他們撇嘴搖頭，";
  Sentence[894] = "說：";
  Sentence[895] = "他把自己交託耶和華，";
  Sentence[896] = "耶和華可以救他吧！";
  Sentence[897] = "耶和華既喜悅他，";
  Sentence[898] = "可以搭救他吧！";
  Sentence[899] = "但你是叫我出母腹的；";
  Sentence[900] = "我在母懷裡，";
  Sentence[901] = "你就使我有倚靠的心。";
  Sentence[902] = "我自出母胎就被交在你手裡；";
  Sentence[903] = "從我母親生我，";
  Sentence[904] = "你就是我的神。";
  Sentence[905] = "求你不要遠離我！";
  Sentence[906] = "因為急難臨近了，";
  Sentence[907] = "沒有人幫助我。";
  Sentence[908] = "有許多公牛圍繞我，";
  Sentence[909] = "巴珊大力的公牛四面困住我。";
  Sentence[910] = "他們向我張口，";
  Sentence[911] = "好像抓撕吼叫的獅子。";
  Sentence[912] = "我如水被倒出來；";
  Sentence[913] = "我的骨頭都脫了節；";
  Sentence[914] = "我心在我裡面如蠟鎔化。";
  Sentence[915] = "我的精力枯乾，";
  Sentence[916] = "如同瓦片；";
  Sentence[917] = "我的舌頭貼在我牙床上。";
  Sentence[918] = "你將我安置在死地的塵土中。";
  Sentence[919] = "犬類圍著我，";
  Sentence[920] = "惡黨環繞我；";
  Sentence[921] = "他們扎了我的手，";
  Sentence[922] = "我的腳。";
  Sentence[923] = "我的骨頭，";
  Sentence[924] = "我都能數過；";
  Sentence[925] = "他們瞪著眼看我。";
  Sentence[926] = "他們分我的外衣，";
  Sentence[927] = "為我的裡衣拈鬮。";
  Sentence[928] = "耶和華啊，";
  Sentence[929] = "求你不要遠離我！";
  Sentence[930] = "我的救主啊，";
  Sentence[931] = "求你快來幫助我！";
  Sentence[932] = "求你救我的靈魂脫離刀劍，";
  Sentence[933] = "救我的生命脫離犬類，";
  Sentence[934] = "救我脫離獅子的口；";
  Sentence[935] = "你已經應允我，";
  Sentence[936] = "使我脫離野牛的角。";
  Sentence[937] = "我要將你的名傳與我的弟兄，";
  Sentence[938] = "在會中我要讚美你。";
  Sentence[939] = "你們敬畏耶和華的人要讚美他！";
  Sentence[940] = "雅各的後裔都要榮耀他！";
  Sentence[941] = "以色列的後裔都要懼怕他！";
  Sentence[942] = "因為他沒有藐視憎惡受苦的人，";
  Sentence[943] = "也沒有向他掩面；";
  Sentence[944] = "那受苦之人呼籲的時候，";
  Sentence[945] = "他就垂聽。";
  Sentence[946] = "我在大會中讚美你的話是從你而來的；";
  Sentence[947] = "我要在敬畏耶和華的人面前還我的願。";
  Sentence[948] = "謙卑的人必吃得飽足；";
  Sentence[949] = "尋求耶和華的人必讚美他。";
  Sentence[950] = "願你們的心永遠活著！";
  Sentence[951] = "地的四極都要想念耶和華，";
  Sentence[952] = "並且歸順他；";
  Sentence[953] = "列國的萬族都要在你面前敬拜。";
  Sentence[954] = "因為國權是耶和華的；";
  Sentence[955] = "他是管理萬國的。";
  Sentence[956] = "地上一切豐肥的人必吃喝而敬拜；";
  Sentence[957] = "凡下到塵土中－";
  Sentence[958] = "不能存活自己性命的人－";
  Sentence[959] = "都要在他面前下拜。";
  Sentence[960] = "他必有後裔事奉他；";
  Sentence[961] = "主所行的事必傳與後代。";
  Sentence[962] = "他們必來把他的公義傳給將要生的民，";
  Sentence[963] = "言明這事是他所行的。";
  Sentence[964] = "詩篇廿三篇";
  Sentence[965] = "耶和華是我的牧者，";
  Sentence[966] = "我必不致缺乏。";
  Sentence[967] = "他使我躺臥在青草地上，";
  Sentence[968] = "領我在可安歇的水邊。";
  Sentence[969] = "他使我的靈魂甦醒，";
  Sentence[970] = "為自己的名引導我走義路。";
  Sentence[971] = "我雖然行過死蔭的幽谷，";
  Sentence[972] = "也不怕遭害，";
  Sentence[973] = "因為你與我同在；";
  Sentence[974] = "你的杖，";
  Sentence[975] = "你的竿，";
  Sentence[976] = "都安慰我。";
  Sentence[977] = "在我敵人面前，";
  Sentence[978] = "你為我擺設筵席；";
  Sentence[979] = "你用油膏了我的頭，";
  Sentence[980] = "使我的福杯滿溢。";
  Sentence[981] = "我一生一世必有恩惠慈愛隨著我；";
  Sentence[982] = "我且要住在耶和華的殿中，";
  Sentence[983] = "直到永遠。";
  Sentence[984] = "詩篇廿四篇";
  Sentence[985] = "地和其中所充滿的，";
  Sentence[986] = "世界和住在其間的，";
  Sentence[987] = "都屬耶和華。";
  Sentence[988] = "他把地建立在海上，";
  Sentence[989] = "安定在大水之上。";
  Sentence[990] = "誰能登耶和華的山？";
  Sentence[991] = "誰能站在他的聖所？";
  Sentence[992] = "就是手潔心清、";
  Sentence[993] = "不向虛妄、";
  Sentence[994] = "起誓不懷詭詐的人。";
  Sentence[995] = "他必蒙耶和華賜福，";
  Sentence[996] = "又蒙救他的神使他成義。";
  Sentence[997] = "這是尋求耶和華的族類，";
  Sentence[998] = "是尋求你面的雅各。";
  Sentence[999] = "眾城門哪，";
  Sentence[1000] = "你們要擡起頭來！";
  Sentence[1001] = "永久的門戶，";
  Sentence[1002] = "你們要被舉起！";
  Sentence[1003] = "那榮耀的王將要進來！";
  Sentence[1004] = "榮耀的王是誰呢？";
  Sentence[1005] = "就是有力有能的耶和華，";
  Sentence[1006] = "在戰場上有能的耶和華！";
  Sentence[1007] = "眾城門哪，";
  Sentence[1008] = "你們要擡起頭來！";
  Sentence[1009] = "永久的門戶，";
  Sentence[1010] = "你們要把頭擡起！";
  Sentence[1011] = "那榮耀的王將要進來！";
  Sentence[1012] = "榮耀的王是誰呢？";
  Sentence[1013] = "萬軍之耶和華，";
  Sentence[1014] = "他是榮耀的王！";
  Sentence[1015] = "詩篇廿五篇";
  Sentence[1016] = "耶和華啊，";
  Sentence[1017] = "我的心仰望你。";
  Sentence[1018] = "我的神啊，";
  Sentence[1019] = "我素來倚靠你；";
  Sentence[1020] = "求你不要叫我羞愧，";
  Sentence[1021] = "不要叫我的仇敵向我誇勝。";
  Sentence[1022] = "凡等候你的必不羞愧；";
  Sentence[1023] = "惟有那無故行奸詐的必要羞愧。";
  Sentence[1024] = "耶和華啊，";
  Sentence[1025] = "求你將你的道指示我，";
  Sentence[1026] = "將你的路教訓我！";
  Sentence[1027] = "求你以你的真理引導我，";
  Sentence[1028] = "教訓我，";
  Sentence[1029] = "因為你是救我的神。";
  Sentence[1030] = "我終日等候你。";
  Sentence[1031] = "耶和華啊，";
  Sentence[1032] = "求你記念你的憐憫和慈愛，";
  Sentence[1033] = "因為這是亙古以來所常有的。";
  Sentence[1034] = "求你不要記念我幼年的罪愆和我的過犯；";
  Sentence[1035] = "耶和華啊，";
  Sentence[1036] = "求你因你的恩惠，";
  Sentence[1037] = "按你的慈愛記念我。";
  Sentence[1038] = "耶和華是良善正直的，";
  Sentence[1039] = "所以他必指示罪人走正路。";
  Sentence[1040] = "他必按公平引領謙卑人，";
  Sentence[1041] = "將他的道教訓他們。";
  Sentence[1042] = "凡遵守他的約和他法度的人，";
  Sentence[1043] = "耶和華都以慈愛誠實待他。";
  Sentence[1044] = "耶和華啊，";
  Sentence[1045] = "求你因你的名赦免我的罪，";
  Sentence[1046] = "因為我的罪重大。";
  Sentence[1047] = "誰敬畏耶和華，";
  Sentence[1048] = "耶和華必指示他當選擇的道路。";
  Sentence[1049] = "他必安然居住；";
  Sentence[1050] = "他的後裔必承受地土。";
  Sentence[1051] = "耶和華與敬畏他的人親密；";
  Sentence[1052] = "他必將自己的約指示他們。";
  Sentence[1053] = "我的眼目時常仰望耶和華，";
  Sentence[1054] = "因為他必將我的腳從網裡拉出來。";
  Sentence[1055] = "求你轉向我，";
  Sentence[1056] = "憐恤我，";
  Sentence[1057] = "因為我是孤獨困苦。";
  Sentence[1058] = "我心裡的愁苦甚多，";
  Sentence[1059] = "求你救我脫離我的禍患。";
  Sentence[1060] = "求你看顧我的困苦，";
  Sentence[1061] = "我的艱難，";
  Sentence[1062] = "赦免我一切的罪。";
  Sentence[1063] = "求你察看我的仇敵，";
  Sentence[1064] = "因為他們人多，";
  Sentence[1065] = "並且痛痛地恨我。";
  Sentence[1066] = "求你保護我的性命，";
  Sentence[1067] = "搭救我，";
  Sentence[1068] = "使我不致羞愧，";
  Sentence[1069] = "因為我投靠你。";
  Sentence[1070] = "願純全、";
  Sentence[1071] = "正直保守我，";
  Sentence[1072] = "因為我等候你。";
  Sentence[1073] = "神啊，";
  Sentence[1074] = "求你救贖以色列脫離他一切的愁苦。";
  Sentence[1075] = "詩篇廿六篇";
  Sentence[1076] = "耶和華啊，";
  Sentence[1077] = "求你為我伸冤，";
  Sentence[1078] = "因我向來行事純全；";
  Sentence[1079] = "我又倚靠耶和華，";
  Sentence[1080] = "並不搖動。";
  Sentence[1081] = "耶和華啊，";
  Sentence[1082] = "求你察看我，";
  Sentence[1083] = "試驗我，";
  Sentence[1084] = "熬煉我的肺腑心腸。";
  Sentence[1085] = "因為你的慈愛常在我眼前，";
  Sentence[1086] = "我也按你的真理而行。";
  Sentence[1087] = "我沒有和虛謊人同坐，";
  Sentence[1088] = "也不與瞞哄人的同群。";
  Sentence[1089] = "我恨惡惡人的會，";
  Sentence[1090] = "必不與惡人同坐。";
  Sentence[1091] = "耶和華啊，";
  Sentence[1092] = "我要洗手表明無辜，";
  Sentence[1093] = "才環繞你的祭壇；";
  Sentence[1094] = "我好發稱謝的聲音，";
  Sentence[1095] = "也要述說你一切奇妙的作為。";
  Sentence[1096] = "耶和華啊，";
  Sentence[1097] = "我喜愛你所住的殿和你顯榮耀的居所。";
  Sentence[1098] = "不要把我的靈魂和罪人一同除掉；";
  Sentence[1099] = "不要把我的性命和流人血的一同除掉。";
  Sentence[1100] = "他們的手中有奸惡，";
  Sentence[1101] = "右手滿有賄賂。";
  Sentence[1102] = "至於我，";
  Sentence[1103] = "卻要行事純全；";
  Sentence[1104] = "求你救贖我，";
  Sentence[1105] = "憐恤我！";
  Sentence[1106] = "我的腳站在平坦地方；";
  Sentence[1107] = "在眾會中我要稱頌耶和華！";
  Sentence[1108] = "詩篇廿七篇";
  Sentence[1109] = "耶和華是我的亮光，";
  Sentence[1110] = "是我的拯救，";
  Sentence[1111] = "我還怕誰呢？";
  Sentence[1112] = "耶和華是我性命的保障，";
  Sentence[1113] = "我還懼誰呢？";
  Sentence[1114] = "那作惡的就是我的仇敵，";
  Sentence[1115] = "前來吃我肉的時候就絆跌仆倒。";
  Sentence[1116] = "雖有軍兵安營攻擊我，";
  Sentence[1117] = "我的心也不害怕；";
  Sentence[1118] = "雖然興起刀兵攻擊我，";
  Sentence[1119] = "我必仍舊安穩。";
  Sentence[1120] = "有一件事，";
  Sentence[1121] = "我曾求耶和華，";
  Sentence[1122] = "我仍要尋求：";
  Sentence[1123] = "就是一生一世住在耶和華的殿中，";
  Sentence[1124] = "瞻仰他的榮美，";
  Sentence[1125] = "在他的殿裡求問。";
  Sentence[1126] = "因為我遭遇患難，";
  Sentence[1127] = "他必暗暗地保守我；";
  Sentence[1128] = "在他亭子裡，";
  Sentence[1129] = "把我藏在他帳幕的隱密處，";
  Sentence[1130] = "將我高舉在磐石上。";
  Sentence[1131] = "現在我得以昂首，";
  Sentence[1132] = "高過四面的仇敵。";
  Sentence[1133] = "我要在他的帳幕裡歡然獻祭；";
  Sentence[1134] = "我要唱詩歌頌耶和華。";
  Sentence[1135] = "耶和華啊，";
  Sentence[1136] = "我用聲音呼籲的時候，";
  Sentence[1137] = "求你垂聽；";
  Sentence[1138] = "並求你憐恤我，";
  Sentence[1139] = "應允我。";
  Sentence[1140] = "你說：";
  Sentence[1141] = "你們當尋求我的面。";
  Sentence[1142] = "那時我心向你說：";
  Sentence[1143] = "耶和華啊，";
  Sentence[1144] = "你的面我正要尋求。";
  Sentence[1145] = "不要向我掩面。";
  Sentence[1146] = "不要發怒趕逐僕人，";
  Sentence[1147] = "你向來是幫助我的。";
  Sentence[1148] = "救我的神啊，";
  Sentence[1149] = "不要丟掉我，";
  Sentence[1150] = "也不要離棄我。";
  Sentence[1151] = "我父母離棄我，";
  Sentence[1152] = "耶和華必收留我。";
  Sentence[1153] = "耶和華啊，";
  Sentence[1154] = "求你將你的道指教我，";
  Sentence[1155] = "因我仇敵的緣故引導我走平坦的路。";
  Sentence[1156] = "求你不要把我交給敵人，";
  Sentence[1157] = "遂其所願；";
  Sentence[1158] = "因為妄作見證的和口吐凶言的，";
  Sentence[1159] = "起來攻擊我。";
  Sentence[1160] = "我若不信在活人之地得見耶和華的恩惠，";
  Sentence[1161] = "就早已喪膽了。";
  Sentence[1162] = "要等候耶和華！";
  Sentence[1163] = "當壯膽，";
  Sentence[1164] = "堅固你的心！";
  Sentence[1165] = "我再說，";
  Sentence[1166] = "要等候耶和華！";
  Sentence[1167] = "詩篇廿八篇";
  Sentence[1168] = "耶和華啊，";
  Sentence[1169] = "我要求告你！";
  Sentence[1170] = "我的磐石啊，";
  Sentence[1171] = "不要向我緘默！";
  Sentence[1172] = "倘若你向我閉口，";
  Sentence[1173] = "我就如將死的人一樣。";
  Sentence[1174] = "我呼求你，";
  Sentence[1175] = "向你至聖所舉手的時候，";
  Sentence[1176] = "求你垂聽我懇求的聲音！";
  Sentence[1177] = "不要把我和惡人並作孽的一同除掉；";
  Sentence[1178] = "他們與鄰舍說和平話，";
  Sentence[1179] = "心裡卻是奸惡。";
  Sentence[1180] = "願你按著他們所做的，";
  Sentence[1181] = "並他們所行的惡事待他們。";
  Sentence[1182] = "願你照著他們手所做的待他們，";
  Sentence[1183] = "將他們所應得的報應加給他們。";
  Sentence[1184] = "他們既然不留心耶和華所行的和他手所做的，";
  Sentence[1185] = "他就必毀壞他們，";
  Sentence[1186] = "不建立他們。";
  Sentence[1187] = "耶和華是應當稱頌的，";
  Sentence[1188] = "因為他聽了我懇求的聲音。";
  Sentence[1189] = "耶和華是我的力量，";
  Sentence[1190] = "是我的盾牌；";
  Sentence[1191] = "我心裡倚靠他就得幫助。";
  Sentence[1192] = "所以我心中歡樂，";
  Sentence[1193] = "我必用詩歌頌讚他。";
  Sentence[1194] = "耶和華是他百姓的力量，";
  Sentence[1195] = "又是他受膏者得救的保障。";
  Sentence[1196] = "求你拯救你的百姓，";
  Sentence[1197] = "賜福給你的產業，";
  Sentence[1198] = "牧養他們，";
  Sentence[1199] = "扶持他們，";
  Sentence[1200] = "直到永遠。";
  Sentence[1201] = "詩篇廿九篇";
  Sentence[1202] = "神的眾子啊，";
  Sentence[1203] = "你們要將榮耀、";
  Sentence[1204] = "能力歸給耶和華，";
  Sentence[1205] = "歸給耶和華！";
  Sentence[1206] = "要將耶和華的名所當得的榮耀歸給他，";
  Sentence[1207] = "以聖潔的妝飾敬拜耶和華。";
  Sentence[1208] = "耶和華的聲音發在水上；";
  Sentence[1209] = "榮耀的神打雷，";
  Sentence[1210] = "耶和華打雷在大水之上。";
  Sentence[1211] = "耶和華的聲音大有能力；";
  Sentence[1212] = "耶和華的聲音滿有威嚴。";
  Sentence[1213] = "耶和華的聲音震破香柏樹；";
  Sentence[1214] = "耶和華震碎利巴嫩的香柏樹。";
  Sentence[1215] = "他也使之跳躍如牛犢，";
  Sentence[1216] = "使利巴嫩和西連跳躍如野牛犢。";
  Sentence[1217] = "耶和華的聲音使火焰分岔。";
  Sentence[1218] = "耶和華的聲音震動曠野；";
  Sentence[1219] = "耶和華震動加低斯的曠野。";
  Sentence[1220] = "耶和華的聲音驚動母鹿落胎，";
  Sentence[1221] = "樹木也脫落淨光。";
  Sentence[1222] = "凡在他殿中的，";
  Sentence[1223] = "都稱說他的榮耀。";
  Sentence[1224] = "洪水泛濫之時，";
  Sentence[1225] = "耶和華坐著為王；";
  Sentence[1226] = "耶和華坐著為王，";
  Sentence[1227] = "直到永遠。";
  Sentence[1228] = "耶和華必賜力量給他的百姓；";
  Sentence[1229] = "耶和華必賜平安的福給他的百姓。";
  Sentence[1230] = "詩篇三十篇";
  Sentence[1231] = "耶和華啊，";
  Sentence[1232] = "我要尊崇你，";
  Sentence[1233] = "因為你曾提拔我，";
  Sentence[1234] = "不叫仇敵向我誇耀。";
  Sentence[1235] = "耶和華－";
  Sentence[1236] = "我的神啊，";
  Sentence[1237] = "我曾呼求你，";
  Sentence[1238] = "你醫治了我。";
  Sentence[1239] = "耶和華啊，";
  Sentence[1240] = "你曾把我的靈魂從陰間救上來，";
  Sentence[1241] = "使我存活，";
  Sentence[1242] = "不至於下坑。";
  Sentence[1243] = "耶和華的聖民哪，";
  Sentence[1244] = "你們要歌頌他，";
  Sentence[1245] = "稱讚他可記念的聖名。";
  Sentence[1246] = "因為，";
  Sentence[1247] = "他的怒氣不過是轉眼之間；";
  Sentence[1248] = "他的恩典乃是一生之久。";
  Sentence[1249] = "一宿雖然有哭泣，";
  Sentence[1250] = "早晨便必歡呼。";
  Sentence[1251] = "至於我，";
  Sentence[1252] = "我凡事平順便說：";
  Sentence[1253] = "我永不動搖。";
  Sentence[1254] = "耶和華啊，";
  Sentence[1255] = "你曾施恩，";
  Sentence[1256] = "叫我的江山穩固；";
  Sentence[1257] = "你掩了面，";
  Sentence[1258] = "我就驚惶。";
  Sentence[1259] = "耶和華啊，";
  Sentence[1260] = "我曾求告你；";
  Sentence[1261] = "我向耶和華懇求，";
  Sentence[1262] = "說：";
  Sentence[1263] = "我被害流血，";
  Sentence[1264] = "下到坑中，";
  Sentence[1265] = "有什麼益處呢？";
  Sentence[1266] = "塵土豈能稱讚你，";
  Sentence[1267] = "傳說你的誠實嗎？";
  Sentence[1268] = "耶和華啊，";
  Sentence[1269] = "求你應允我，";
  Sentence[1270] = "憐恤我！";
  Sentence[1271] = "耶和華啊，";
  Sentence[1272] = "求你幫助我！";
  Sentence[1273] = "你已將我的哀哭變為跳舞，";
  Sentence[1274] = "將我的麻衣脫去，";
  Sentence[1275] = "給我披上喜樂，";
  Sentence[1276] = "好叫我的靈歌頌你，";
  Sentence[1277] = "並不住聲。";
  Sentence[1278] = "耶和華－";
  Sentence[1279] = "我的神啊，";
  Sentence[1280] = "我要稱謝你，";
  Sentence[1281] = "直到永遠！";
  Sentence[1282] = "詩篇卅一篇";
  Sentence[1283] = "耶和華啊，";
  Sentence[1284] = "我投靠你；";
  Sentence[1285] = "求你使我永不羞愧；";
  Sentence[1286] = "憑你的公義搭救我！";
  Sentence[1287] = "求你側耳而聽，";
  Sentence[1288] = "快快救我！";
  Sentence[1289] = "作我堅固的磐石，";
  Sentence[1290] = "拯救我的保障！";
  Sentence[1291] = "因為你是我的巖石，";
  Sentence[1292] = "我的山寨；";
  Sentence[1293] = "所以，";
  Sentence[1294] = "求你為你名的緣故引導我，";
  Sentence[1295] = "指點我。";
  Sentence[1296] = "求你救我脫離人為我暗設的網羅，";
  Sentence[1297] = "因為你是我的保障。";
  Sentence[1298] = "我將我的靈魂交在你手裡；";
  Sentence[1299] = "耶和華誠實的神啊，";
  Sentence[1300] = "你救贖了我。";
  Sentence[1301] = "我恨惡那信奉虛無之神的人；";
  Sentence[1302] = "我卻倚靠耶和華。";
  Sentence[1303] = "我要為你的慈愛高興歡喜；";
  Sentence[1304] = "因為你見過我的困苦，";
  Sentence[1305] = "知道我心中的艱難。";
  Sentence[1306] = "你未曾把我交在仇敵手裡；";
  Sentence[1307] = "你使我的腳站在寬闊之處。";
  Sentence[1308] = "耶和華啊，";
  Sentence[1309] = "求你憐恤我，";
  Sentence[1310] = "因為我在急難之中；";
  Sentence[1311] = "我的眼睛因憂愁而乾癟，";
  Sentence[1312] = "連我的身心也不安舒。";
  Sentence[1313] = "我的生命為愁苦所消耗；";
  Sentence[1314] = "我的年歲為歎息所曠廢。";
  Sentence[1315] = "我的力量因我的罪孽衰敗；";
  Sentence[1316] = "我的骨頭也枯乾。";
  Sentence[1317] = "我因一切敵人成了羞辱，";
  Sentence[1318] = "在我的鄰舍跟前更甚；";
  Sentence[1319] = "那認識我的都懼怕我，";
  Sentence[1320] = "在外頭看見我的都躲避我。";
  Sentence[1321] = "我被人忘記，";
  Sentence[1322] = "如同死人，";
  Sentence[1323] = "無人記念；";
  Sentence[1324] = "我好像破碎的器皿。";
  Sentence[1325] = "我聽見了許多人的讒謗，";
  Sentence[1326] = "四圍都是驚嚇；";
  Sentence[1327] = "他們一同商議攻擊我的時候，";
  Sentence[1328] = "就圖謀要害我的性命。";
  Sentence[1329] = "耶和華啊，";
  Sentence[1330] = "我仍舊倚靠你；";
  Sentence[1331] = "我說：";
  Sentence[1332] = "你是我的神。";
  Sentence[1333] = "我終身的事在你手中；";
  Sentence[1334] = "求你救我脫離仇敵的手和那些逼迫我的人。";
  Sentence[1335] = "求你使你的臉光照僕人，";
  Sentence[1336] = "憑你的慈愛拯救我。";
  Sentence[1337] = "耶和華啊，";
  Sentence[1338] = "求你叫我不致羞愧，";
  Sentence[1339] = "因為我曾呼籲你；";
  Sentence[1340] = "求你使惡人羞愧，";
  Sentence[1341] = "使他們在陰間緘默無聲。";
  Sentence[1342] = "那撒謊的人逞驕傲輕慢，";
  Sentence[1343] = "出狂妄的話攻擊義人；";
  Sentence[1344] = "願他的嘴啞而無言。";
  Sentence[1345] = "敬畏你、";
  Sentence[1346] = "投靠你的人，";
  Sentence[1347] = "你為他們所積存的，";
  Sentence[1348] = "在世人面前所施行的恩惠是何等大呢！";
  Sentence[1349] = "你必把他們藏在你面前的隱密處，";
  Sentence[1350] = "免得遇見人的計謀；";
  Sentence[1351] = "你必暗暗地保守他們在亭子裡，";
  Sentence[1352] = "免受口舌的爭鬧。";
  Sentence[1353] = "耶和華是應當稱頌的，";
  Sentence[1354] = "因為他在堅固城裡向我施展奇妙的慈愛。";
  Sentence[1355] = "至於我，";
  Sentence[1356] = "我曾急促地說：";
  Sentence[1357] = "我從你眼前被隔絕。";
  Sentence[1358] = "然而，";
  Sentence[1359] = "我呼求你的時候，";
  Sentence[1360] = "你仍聽我懇求的聲音。";
  Sentence[1361] = "耶和華的聖民哪，";
  Sentence[1362] = "你們都要愛他！";
  Sentence[1363] = "耶和華保護誠實人，";
  Sentence[1364] = "足足報應行事驕傲的人。";
  Sentence[1365] = "凡仰望耶和華的人，";
  Sentence[1366] = "你們都要壯膽，";
  Sentence[1367] = "堅固你們的心！";
  Sentence[1368] = "詩篇卅二篇";
  Sentence[1369] = "得赦免其過、";
  Sentence[1370] = "遮蓋其罪的，";
  Sentence[1371] = "這人是有福的！";
  Sentence[1372] = "凡心裡沒有詭詐、";
  Sentence[1373] = "耶和華不算為有罪的，";
  Sentence[1374] = "這人是有福的！";
  Sentence[1375] = "我閉口不認罪的時候，";
  Sentence[1376] = "因終日唉哼而骨頭枯乾。";
  Sentence[1377] = "黑夜白日，";
  Sentence[1378] = "你的手在我身上沉重；";
  Sentence[1379] = "我的精液耗盡，";
  Sentence[1380] = "如同夏天的乾旱。";
  Sentence[1381] = "我向你陳明我的罪，";
  Sentence[1382] = "不隱瞞我的惡。";
  Sentence[1383] = "我說：";
  Sentence[1384] = "我要向耶和華承認我的過犯，";
  Sentence[1385] = "你就赦免我的罪惡。";
  Sentence[1386] = "為此，";
  Sentence[1387] = "凡虔誠人都當趁你可尋找的時候禱告你；";
  Sentence[1388] = "大水泛溢的時候，";
  Sentence[1389] = "必不能到他那裡。";
  Sentence[1390] = "你是我藏身之處；";
  Sentence[1391] = "你必保佑我脫離苦難，";
  Sentence[1392] = "以得救的樂歌四面環繞我。";
  Sentence[1393] = "我要教導你，";
  Sentence[1394] = "指示你當行的路；";
  Sentence[1395] = "我要定睛在你身上勸戒你。";
  Sentence[1396] = "你不可像那無知的騾馬，";
  Sentence[1397] = "必用嚼環轡頭勒住他；";
  Sentence[1398] = "不然，";
  Sentence[1399] = "就不能馴服。";
  Sentence[1400] = "惡人必多受苦楚；";
  Sentence[1401] = "惟獨倚靠耶和華的必有慈愛四面環繞他。";
  Sentence[1402] = "你們義人應當靠耶和華歡喜快樂；";
  Sentence[1403] = "你們心裡正直的人都當歡呼。";
  Sentence[1404] = "詩篇卅三篇";
  Sentence[1405] = "義人哪，";
  Sentence[1406] = "你們應當靠耶和華歡樂；";
  Sentence[1407] = "正直人的讚美是合宜的。";
  Sentence[1408] = "你們應當彈琴稱謝耶和華，";
  Sentence[1409] = "用十弦瑟歌頌他。";
  Sentence[1410] = "應當向他唱新歌，";
  Sentence[1411] = "彈得巧妙，";
  Sentence[1412] = "聲音洪亮。";
  Sentence[1413] = "因為耶和華的言語正直；";
  Sentence[1414] = "凡他所做的盡都誠實。";
  Sentence[1415] = "他喜愛仁義公平；";
  Sentence[1416] = "遍地滿了耶和華的慈愛。";
  Sentence[1417] = "諸天藉耶和華的命而造；";
  Sentence[1418] = "萬象藉他口中的氣而成。";
  Sentence[1419] = "他聚集海水如壘，";
  Sentence[1420] = "收藏深洋在庫房。";
  Sentence[1421] = "願全地都敬畏耶和華！";
  Sentence[1422] = "願世上的居民都懼怕他！";
  Sentence[1423] = "因為他說有，";
  Sentence[1424] = "就有，";
  Sentence[1425] = "命立，";
  Sentence[1426] = "就立。";
  Sentence[1427] = "耶和華使列國的籌算歸於無有，";
  Sentence[1428] = "使眾民的思念無有功效。";
  Sentence[1429] = "耶和華的籌算永遠立定；";
  Sentence[1430] = "他心中的思念萬代常存。";
  Sentence[1431] = "以耶和華為神的，";
  Sentence[1432] = "那國是有福的！";
  Sentence[1433] = "他所揀選為自己產業的，";
  Sentence[1434] = "那民是有福的！";
  Sentence[1435] = "耶和華從天上觀看；";
  Sentence[1436] = "他看見一切的世人。";
  Sentence[1437] = "從他的居所往外察看地上一切的居民－";
  Sentence[1438] = "他是那造成他們眾人心的，";
  Sentence[1439] = "留意他們一切作為的。";
  Sentence[1440] = "君王不能因兵多得勝；";
  Sentence[1441] = "勇士不能因力大得救。";
  Sentence[1442] = "靠馬得救是枉然的；";
  Sentence[1443] = "馬也不能因力大救人。";
  Sentence[1444] = "耶和華的眼目看顧敬畏他的人和仰望他慈愛的人，";
  Sentence[1445] = "要救他們的命脫離死亡，";
  Sentence[1446] = "並使他們在饑荒中存活。";
  Sentence[1447] = "我們的心向來等候耶和華；";
  Sentence[1448] = "他是我們的幫助，";
  Sentence[1449] = "我們的盾牌。";
  Sentence[1450] = "我們的心必靠他歡喜，";
  Sentence[1451] = "因為我們向來倚靠他的聖名。";
  Sentence[1452] = "耶和華啊，";
  Sentence[1453] = "求你照著我們所仰望你的，";
  Sentence[1454] = "向我們施行慈愛！";
  Sentence[1455] = "詩篇卅四篇";
  Sentence[1456] = "我要時時稱頌耶和華；";
  Sentence[1457] = "讚美他的話必常在我口中。";
  Sentence[1458] = "我的心必因耶和華誇耀；";
  Sentence[1459] = "謙卑人聽見就要喜樂。";
  Sentence[1460] = "你們和我當稱耶和華為大，";
  Sentence[1461] = "一同高舉他的名。";
  Sentence[1462] = "我曾尋求耶和華，";
  Sentence[1463] = "他就應允我，";
  Sentence[1464] = "救我脫離了一切的恐懼。";
  Sentence[1465] = "凡仰望他的，";
  Sentence[1466] = "便有光榮；";
  Sentence[1467] = "他們的臉必不蒙羞。";
  Sentence[1468] = "我這困苦人呼求，";
  Sentence[1469] = "耶和華便垂聽，";
  Sentence[1470] = "救我脫離一切患難。";
  Sentence[1471] = "耶和華的使者在敬畏他的人四圍安營，";
  Sentence[1472] = "搭救他們。";
  Sentence[1473] = "你們要嘗嘗主恩的滋味，";
  Sentence[1474] = "便知道他是美善；";
  Sentence[1475] = "投靠他的人有福了！";
  Sentence[1476] = "耶和華的聖民哪，";
  Sentence[1477] = "你們當敬畏他，";
  Sentence[1478] = "因敬畏他的一無所缺。";
  Sentence[1479] = "少壯獅子還缺食忍餓，";
  Sentence[1480] = "但尋求耶和華的什麼好處都不缺。";
  Sentence[1481] = "眾弟子啊，";
  Sentence[1482] = "你們當來聽我的話！";
  Sentence[1483] = "我要將敬畏耶和華的道教訓你們。";
  Sentence[1484] = "有何人喜好存活，";
  Sentence[1485] = "愛慕長壽，";
  Sentence[1486] = "得享美福，";
  Sentence[1487] = "就要禁止舌頭不出惡言，";
  Sentence[1488] = "嘴唇不說詭詐的話。";
  Sentence[1489] = "要離惡行善，";
  Sentence[1490] = "尋求和睦，";
  Sentence[1491] = "一心追趕。";
  Sentence[1492] = "耶和華的眼目看顧義人；";
  Sentence[1493] = "他的耳朵聽他們的呼求。";
  Sentence[1494] = "耶和華向行惡的人變臉，";
  Sentence[1495] = "要從世上除滅他們的名號。";
  Sentence[1496] = "義人呼求，";
  Sentence[1497] = "耶和華聽見了，";
  Sentence[1498] = "便救他們脫離一切患難。";
  Sentence[1499] = "耶和華靠近傷心的人，";
  Sentence[1500] = "拯救靈性痛悔的人。";
  Sentence[1501] = "義人多有苦難，";
  Sentence[1502] = "但耶和華救他脫離這一切，";
  Sentence[1503] = "又保全他一身的骨頭，";
  Sentence[1504] = "連一根也不折斷。";
  Sentence[1505] = "惡必害死惡人；";
  Sentence[1506] = "恨惡義人的，";
  Sentence[1507] = "必被定罪。";
  Sentence[1508] = "耶和華救贖他僕人的靈魂；";
  Sentence[1509] = "凡投靠他的，";
  Sentence[1510] = "必不致定罪。";
  Sentence[1511] = "詩篇卅五篇";
  Sentence[1512] = "耶和華啊，";
  Sentence[1513] = "與我相爭的，";
  Sentence[1514] = "求你與他們相爭！";
  Sentence[1515] = "與我相戰的，";
  Sentence[1516] = "求你與他們相戰！";
  Sentence[1517] = "拿著大小的盾牌，";
  Sentence[1518] = "起來幫助我。";
  Sentence[1519] = "抽出槍來，";
  Sentence[1520] = "擋住那追趕我的；";
  Sentence[1521] = "求你對我的靈魂說：";
  Sentence[1522] = "我是拯救你的。";
  Sentence[1523] = "願那尋索我命的，";
  Sentence[1524] = "蒙羞受辱！";
  Sentence[1525] = "願那謀害我的，";
  Sentence[1526] = "退後羞愧！";
  Sentence[1527] = "願他們像風前的糠，";
  Sentence[1528] = "有耶和華的使者趕逐他們。";
  Sentence[1529] = "願他們的道路又暗又滑，";
  Sentence[1530] = "有耶和華的使者追趕他們。";
  Sentence[1531] = "因他們無故地為我暗設網羅，";
  Sentence[1532] = "無故地挖坑，";
  Sentence[1533] = "要害我的性命。";
  Sentence[1534] = "願災禍忽然臨到他身上！";
  Sentence[1535] = "願他暗設的網纏住自己！";
  Sentence[1536] = "願他落在其中遭災禍！";
  Sentence[1537] = "我的心必靠耶和華快樂，";
  Sentence[1538] = "靠他的救恩高興。";
  Sentence[1539] = "我的骨頭都要說：";
  Sentence[1540] = "耶和華啊，";
  Sentence[1541] = "誰能像你救護困苦人脫離那比他強壯的，";
  Sentence[1542] = "救護困苦窮乏人脫離那搶奪他的？";
  Sentence[1543] = "凶惡的見證人起來，";
  Sentence[1544] = "盤問我所不知道的事。";
  Sentence[1545] = "他們向我以惡報善，";
  Sentence[1546] = "使我的靈魂孤苦。";
  Sentence[1547] = "至於我，";
  Sentence[1548] = "當他們有病的時候，";
  Sentence[1549] = "我便穿麻衣，";
  Sentence[1550] = "禁食，";
  Sentence[1551] = "刻苦己心；";
  Sentence[1552] = "我所求的都歸到自己的懷中。";
  Sentence[1553] = "我這樣行，";
  Sentence[1554] = "好像他是我的朋友，";
  Sentence[1555] = "我的弟兄；";
  Sentence[1556] = "我屈身悲哀，";
  Sentence[1557] = "如同人為母親哀痛。";
  Sentence[1558] = "我在患難中，";
  Sentence[1559] = "他們卻歡喜，";
  Sentence[1560] = "大家聚集。";
  Sentence[1561] = "我所不認識的那些下流人聚集攻擊我；";
  Sentence[1562] = "他們不住地把我撕裂。";
  Sentence[1563] = "他們如同席上好嬉笑的狂妄人向我咬牙。";
  Sentence[1564] = "主啊，";
  Sentence[1565] = "你看著不理要到幾時呢？";
  Sentence[1566] = "求你救我的靈魂脫離他們的殘害！";
  Sentence[1567] = "救我的生命脫離少壯獅子！";
  Sentence[1568] = "我在大會中要稱謝你，";
  Sentence[1569] = "在眾民中要讚美你。";
  Sentence[1570] = "求你不容那無理與我為仇的向我誇耀！";
  Sentence[1571] = "不容那無故恨我的向我擠眼！";
  Sentence[1572] = "因為他們不說和平話，";
  Sentence[1573] = "倒想出詭詐的言語害地上的安靜人。";
  Sentence[1574] = "他們大大張口攻擊我，";
  Sentence[1575] = "說：";
  Sentence[1576] = "阿哈，";
  Sentence[1577] = "阿哈，";
  Sentence[1578] = "我們的眼已經看見了！";
  Sentence[1579] = "耶和華啊，";
  Sentence[1580] = "你已經看見了，";
  Sentence[1581] = "求你不要閉口！";
  Sentence[1582] = "主啊，";
  Sentence[1583] = "求你不要遠離我！";
  Sentence[1584] = "我的神我的主啊，";
  Sentence[1585] = "求你奮興醒起，";
  Sentence[1586] = "判清我的事，";
  Sentence[1587] = "伸明我的冤！";
  Sentence[1588] = "耶和華－";
  Sentence[1589] = "我的神啊，";
  Sentence[1590] = "求你按你的公義判斷我，";
  Sentence[1591] = "不容他們向我誇耀！";
  Sentence[1592] = "不容他們心裡說：";
  Sentence[1593] = "阿哈，";
  Sentence[1594] = "遂我們的心願了！";
  Sentence[1595] = "不容他們說：";
  Sentence[1596] = "我們已經把他吞了！";
  Sentence[1597] = "願那喜歡我遭難的一同抱愧蒙羞！";
  Sentence[1598] = "願那向我妄自尊大的披慚愧，";
  Sentence[1599] = "蒙羞辱！";
  Sentence[1600] = "願那喜悅我冤屈得伸的歡呼快樂；";
  Sentence[1601] = "願他們常說：";
  Sentence[1602] = "當尊耶和華為大！";
  Sentence[1603] = "耶和華喜悅他的僕人平安。";
  Sentence[1604] = "我的舌頭要終日論說你的公義，";
  Sentence[1605] = "時常讚美你。";
  Sentence[1606] = "詩篇卅六篇";
  Sentence[1607] = "惡人的罪過在他心裡說：";
  Sentence[1608] = "我眼中不怕神！";
  Sentence[1609] = "他自誇自媚，";
  Sentence[1610] = "以為他的罪孽終不顯露，";
  Sentence[1611] = "不被恨惡。";
  Sentence[1612] = "他口中的言語盡是罪孽詭詐；";
  Sentence[1613] = "他與智慧善行已經斷絕。";
  Sentence[1614] = "他在床上圖謀罪孽，";
  Sentence[1615] = "定意行不善的道，";
  Sentence[1616] = "不憎惡惡事。";
  Sentence[1617] = "耶和華啊，";
  Sentence[1618] = "你的慈愛上及諸天；";
  Sentence[1619] = "你的信實達到穹蒼。";
  Sentence[1620] = "你的公義好像高山；";
  Sentence[1621] = "你的判斷如同深淵。";
  Sentence[1622] = "耶和華啊，";
  Sentence[1623] = "人民、";
  Sentence[1624] = "牲畜，";
  Sentence[1625] = "你都救護。";
  Sentence[1626] = "神啊，";
  Sentence[1627] = "你的慈愛何其寶貴！";
  Sentence[1628] = "世人投靠在你翅膀的蔭下。";
  Sentence[1629] = "他們必因你殿裡的肥甘得以飽足；";
  Sentence[1630] = "你也必叫他們喝你樂河的水。";
  Sentence[1631] = "因為，";
  Sentence[1632] = "在你那裡有生命的源頭；";
  Sentence[1633] = "在你的光中，";
  Sentence[1634] = "我們必得見光。";
  Sentence[1635] = "願你常施慈愛給認識你的人，";
  Sentence[1636] = "常以公義待心裡正直的人。";
  Sentence[1637] = "不容驕傲人的腳踐踏我；";
  Sentence[1638] = "不容凶惡人的手趕逐我。";
  Sentence[1639] = "在那裡，";
  Sentence[1640] = "作孽的人已經仆倒；";
  Sentence[1641] = "他們被推倒，";
  Sentence[1642] = "不能再起來。";
  Sentence[1643] = "詩篇卅七篇";
  Sentence[1644] = "不要為作惡的心懷不平，";
  Sentence[1645] = "也不要向那行不義的生出嫉妒。";
  Sentence[1646] = "因為他們如草快被割下，";
  Sentence[1647] = "又如青菜快要枯乾。";
  Sentence[1648] = "你當倚靠耶和華而行善，";
  Sentence[1649] = "住在地上，";
  Sentence[1650] = "以他的信實為糧；";
  Sentence[1651] = "又要以耶和華為樂，";
  Sentence[1652] = "他就將你心裡所求的賜給你。";
  Sentence[1653] = "當將你的事交託耶和華，";
  Sentence[1654] = "並倚靠他，";
  Sentence[1655] = "他就必成全。";
  Sentence[1656] = "他要使你的公義如光發出，";
  Sentence[1657] = "使你的公平明如正午。";
  Sentence[1658] = "你當默然倚靠耶和華，";
  Sentence[1659] = "耐性等候他；";
  Sentence[1660] = "不要因那道路通達的和那惡謀成就的心懷不平。";
  Sentence[1661] = "當止住怒氣，";
  Sentence[1662] = "離棄忿怒；";
  Sentence[1663] = "不要心懷不平，";
  Sentence[1664] = "以致作惡。";
  Sentence[1665] = "因為作惡的必被剪除；";
  Sentence[1666] = "惟有等候耶和華的必承受地土。";
  Sentence[1667] = "還有片時，";
  Sentence[1668] = "惡人要歸於無有；";
  Sentence[1669] = "你就是細察他的住處也要歸於無有。";
  Sentence[1670] = "但謙卑人必承受地土，";
  Sentence[1671] = "以豐盛的平安為樂。";
  Sentence[1672] = "惡人設謀害義人，";
  Sentence[1673] = "又向他咬牙。";
  Sentence[1674] = "主要笑他，";
  Sentence[1675] = "因見他受罰的日子將要來到。";
  Sentence[1676] = "惡人已經弓上弦，";
  Sentence[1677] = "刀出鞘，";
  Sentence[1678] = "要打倒困苦窮乏的人，";
  Sentence[1679] = "要殺害行動正直的人。";
  Sentence[1680] = "他們的刀必刺入自己的心；";
  Sentence[1681] = "他們的弓必被折斷。";
  Sentence[1682] = "一個義人所有的雖少，";
  Sentence[1683] = "強過許多惡人的富餘。";
  Sentence[1684] = "因為惡人的膀臂必被折斷；";
  Sentence[1685] = "但耶和華是扶持義人。";
  Sentence[1686] = "耶和華知道完全人的日子；";
  Sentence[1687] = "他們的產業要存到永遠。";
  Sentence[1688] = "他們在急難的時候不致羞愧，";
  Sentence[1689] = "在饑荒的日子必得飽足。";
  Sentence[1690] = "惡人卻要滅亡。";
  Sentence[1691] = "耶和華的仇敵要像羊羔的脂油；";
  Sentence[1692] = "他們要消滅，";
  Sentence[1693] = "要如煙消滅。";
  Sentence[1694] = "惡人借貸而不償還；";
  Sentence[1695] = "義人卻恩待人，";
  Sentence[1696] = "並且施捨。";
  Sentence[1697] = "蒙耶和華賜福的必承受地土；";
  Sentence[1698] = "被他咒詛的必被剪除。";
  Sentence[1699] = "義人的腳步被耶和華立定；";
  Sentence[1700] = "他的道路，";
  Sentence[1701] = "耶和華也喜愛。";
  Sentence[1702] = "他雖失腳也不致全身仆倒，";
  Sentence[1703] = "因為耶和華用手攙扶他。";
  Sentence[1704] = "我從前年幼，";
  Sentence[1705] = "現在年老，";
  Sentence[1706] = "卻未見過義人被棄，";
  Sentence[1707] = "也未見過他的後裔討飯。";
  Sentence[1708] = "他終日恩待人，";
  Sentence[1709] = "借給人；";
  Sentence[1710] = "他的後裔也蒙福！";
  Sentence[1711] = "你當離惡行善，";
  Sentence[1712] = "就可永遠安居。";
  Sentence[1713] = "因為，";
  Sentence[1714] = "耶和華喜愛公平，";
  Sentence[1715] = "不撇棄他的聖民；";
  Sentence[1716] = "他們永蒙保佑，";
  Sentence[1717] = "但惡人的後裔必被剪除。";
  Sentence[1718] = "義人必承受地土，";
  Sentence[1719] = "永居其上。";
  Sentence[1720] = "義人的口談論智慧；";
  Sentence[1721] = "他的舌頭講說公平。";
  Sentence[1722] = "神的律法在他心裡；";
  Sentence[1723] = "他的腳總不滑跌。";
  Sentence[1724] = "惡人窺探義人，";
  Sentence[1725] = "想要殺他。";
  Sentence[1726] = "耶和華必不撇他在惡人手中；";
  Sentence[1727] = "當審判的時候，";
  Sentence[1728] = "也不定他的罪。";
  Sentence[1729] = "你當等候耶和華，";
  Sentence[1730] = "遵守他的道，";
  Sentence[1731] = "他就擡舉你，";
  Sentence[1732] = "使你承受地土；";
  Sentence[1733] = "惡人被剪除的時候，";
  Sentence[1734] = "你必看見。";
  Sentence[1735] = "我見過惡人大有勢力，";
  Sentence[1736] = "好像一根青翠樹在本土生發。";
  Sentence[1737] = "有人從那裡經過，";
  Sentence[1738] = "不料，";
  Sentence[1739] = "他沒有了；";
  Sentence[1740] = "我也尋找他，";
  Sentence[1741] = "卻尋不著。";
  Sentence[1742] = "你要細察那完全人，";
  Sentence[1743] = "觀看那正直人，";
  Sentence[1744] = "因為和平人有好結局。";
  Sentence[1745] = "至於犯法的人，";
  Sentence[1746] = "必一同滅絕；";
  Sentence[1747] = "惡人終必剪除。";
  Sentence[1748] = "但義人得救是由於耶和華；";
  Sentence[1749] = "他在患難時作他們的營寨。";
  Sentence[1750] = "耶和華幫助他們，";
  Sentence[1751] = "解救他們；";
  Sentence[1752] = "他解救他們脫離惡人，";
  Sentence[1753] = "把他們救出來，";
  Sentence[1754] = "因為他們投靠他。";
  Sentence[1755] = "詩篇卅八篇";
  Sentence[1756] = "耶和華啊，";
  Sentence[1757] = "求你不要在怒中責備我，";
  Sentence[1758] = "不要在烈怒中懲罰我！";
  Sentence[1759] = "因為，";
  Sentence[1760] = "你的箭射入我身；";
  Sentence[1761] = "你的手壓住我。";
  Sentence[1762] = "因你的惱怒，";
  Sentence[1763] = "我的肉無一完全；";
  Sentence[1764] = "因我的罪過，";
  Sentence[1765] = "我的骨頭也不安寧。";
  Sentence[1766] = "我的罪孽高過我的頭，";
  Sentence[1767] = "如同重擔叫我擔當不起。";
  Sentence[1768] = "因我的愚昧，";
  Sentence[1769] = "我的傷發臭流膿。";
  Sentence[1770] = "我疼痛，";
  Sentence[1771] = "大大拳曲，";
  Sentence[1772] = "終日哀痛。";
  Sentence[1773] = "我滿腰是火；";
  Sentence[1774] = "我的肉無一完全。";
  Sentence[1775] = "我被壓傷，";
  Sentence[1776] = "身體疲倦；";
  Sentence[1777] = "因心裡不安，";
  Sentence[1778] = "我就唉哼。";
  Sentence[1779] = "主啊，";
  Sentence[1780] = "我的心願都在你面前；";
  Sentence[1781] = "我的歎息不向你隱瞞。";
  Sentence[1782] = "我心跳動，";
  Sentence[1783] = "我力衰微，";
  Sentence[1784] = "連我眼中的光也沒有了。";
  Sentence[1785] = "我的良朋密友因我的災病都躲在旁邊站著；";
  Sentence[1786] = "我的親戚本家也遠遠地站立。";
  Sentence[1787] = "那尋索我命的設下網羅；";
  Sentence[1788] = "那想要害我的口出惡言，";
  Sentence[1789] = "終日思想詭計。";
  Sentence[1790] = "但我如聾子不聽，";
  Sentence[1791] = "像啞巴不開口。";
  Sentence[1792] = "我如不聽見的人，";
  Sentence[1793] = "口中沒有回話。";
  Sentence[1794] = "耶和華啊，";
  Sentence[1795] = "我仰望你！";
  Sentence[1796] = "主－";
  Sentence[1797] = "我的神啊，";
  Sentence[1798] = "你必應允我！";
  Sentence[1799] = "我曾說：";
  Sentence[1800] = "恐怕他們向我誇耀；";
  Sentence[1801] = "我失腳的時候，";
  Sentence[1802] = "他們向我誇大。";
  Sentence[1803] = "我幾乎跌倒；";
  Sentence[1804] = "我的痛苦常在我面前。";
  Sentence[1805] = "我要承認我的罪孽；";
  Sentence[1806] = "我要因我的罪憂愁。";
  Sentence[1807] = "但我的仇敵又活潑又強壯，";
  Sentence[1808] = "無理恨我的增多了。";
  Sentence[1809] = "以惡報善的與我作對，";
  Sentence[1810] = "因我是追求良善。";
  Sentence[1811] = "耶和華啊，";
  Sentence[1812] = "求你不要撇棄我！";
  Sentence[1813] = "我的神啊，";
  Sentence[1814] = "求你不要遠離我！";
  Sentence[1815] = "拯救我的主啊，";
  Sentence[1816] = "求你快快幫助我！";
  Sentence[1817] = "詩篇卅九篇";
  Sentence[1818] = "我曾說：";
  Sentence[1819] = "我要謹慎我的言行，";
  Sentence[1820] = "免得我舌頭犯罪；";
  Sentence[1821] = "惡人在我面前的時候，";
  Sentence[1822] = "我要用嚼環勒住我的口。";
  Sentence[1823] = "我默然無聲，";
  Sentence[1824] = "連好話也不出口；";
  Sentence[1825] = "我的愁苦就發動了，";
  Sentence[1826] = "我的心在我裡面發熱。";
  Sentence[1827] = "我默想的時候，";
  Sentence[1828] = "火就燒起，";
  Sentence[1829] = "我便用舌頭說話。";
  Sentence[1830] = "耶和華啊，";
  Sentence[1831] = "求你叫我曉得我身之終！";
  Sentence[1832] = "我的壽數幾何？";
  Sentence[1833] = "叫我知道我的生命不長！";
  Sentence[1834] = "你使我的年日窄如手掌；";
  Sentence[1835] = "我一生的年數，";
  Sentence[1836] = "在你面前如同無有。";
  Sentence[1837] = "各人最穩妥的時候，";
  Sentence[1838] = "真是全然虛幻。";
  Sentence[1839] = "世人行動實係幻影。";
  Sentence[1840] = "他們忙亂，";
  Sentence[1841] = "真是枉然；";
  Sentence[1842] = "積蓄財寶，";
  Sentence[1843] = "不知將來有誰收取。";
  Sentence[1844] = "主啊，";
  Sentence[1845] = "如今我等什麼呢？";
  Sentence[1846] = "我的指望在乎你！";
  Sentence[1847] = "求你救我脫離一切的過犯，";
  Sentence[1848] = "不要使我受愚頑人的羞辱。";
  Sentence[1849] = "因我所遭遇的是出於你，";
  Sentence[1850] = "我就默然不語。";
  Sentence[1851] = "求你把你的責罰從我身上免去；";
  Sentence[1852] = "因你手的責打，";
  Sentence[1853] = "我便消滅。";
  Sentence[1854] = "你因人的罪惡懲罰他的時候，";
  Sentence[1855] = "叫他的笑容消滅，";
  Sentence[1856] = "如衣被蟲所咬。";
  Sentence[1857] = "世人真是虛幻！";
  Sentence[1858] = "耶和華啊，";
  Sentence[1859] = "求你聽我的禱告，";
  Sentence[1860] = "留心聽我的呼求！";
  Sentence[1861] = "我流淚，";
  Sentence[1862] = "求你不要靜默無聲！";
  Sentence[1863] = "因為我在你面前是客旅，";
  Sentence[1864] = "是寄居的，";
  Sentence[1865] = "像我列祖一般。";
  Sentence[1866] = "求你寬容我，";
  Sentence[1867] = "使我在去而不返之先可以力量復原。";
  Sentence[1868] = "詩篇四十篇";
  Sentence[1869] = "我曾耐性等候耶和華；";
  Sentence[1870] = "他垂聽我的呼求。";
  Sentence[1871] = "他從禍坑裡，";
  Sentence[1872] = "從淤泥中，";
  Sentence[1873] = "把我拉上來，";
  Sentence[1874] = "使我的腳立在磐石上，";
  Sentence[1875] = "使我腳步穩當。";
  Sentence[1876] = "他使我口唱新歌，";
  Sentence[1877] = "就是讚美我們神的話。";
  Sentence[1878] = "許多人必看見而懼怕，";
  Sentence[1879] = "並要倚靠耶和華。";
  Sentence[1880] = "那倚靠耶和華、";
  Sentence[1881] = "不理會狂傲和偏向虛假之輩的，";
  Sentence[1882] = "這人便為有福！";
  Sentence[1883] = "耶和華－";
  Sentence[1884] = "我的神啊，";
  Sentence[1885] = "你所行的奇事，";
  Sentence[1886] = "並你向我們所懷的意念甚多，";
  Sentence[1887] = "不能向你陳明。";
  Sentence[1888] = "若要陳明，";
  Sentence[1889] = "其事不可勝數。";
  Sentence[1890] = "祭物和禮物，";
  Sentence[1891] = "你不喜悅；";
  Sentence[1892] = "你已經開通我的耳朵。";
  Sentence[1893] = "燔祭和贖罪祭非你所要。";
  Sentence[1894] = "那時我說：";
  Sentence[1895] = "看哪，";
  Sentence[1896] = "我來了！";
  Sentence[1897] = "我的事在經卷上已經記載了。";
  Sentence[1898] = "我的神啊，";
  Sentence[1899] = "我樂意照你的旨意行；";
  Sentence[1900] = "你的律法在我心裡。";
  Sentence[1901] = "我在大會中宣傳公義的佳音；";
  Sentence[1902] = "我必不止住我的嘴唇。";
  Sentence[1903] = "耶和華啊，";
  Sentence[1904] = "這是你所知道的。";
  Sentence[1905] = "我未曾把你的公義藏在心裡；";
  Sentence[1906] = "我已陳明你的信實和你的救恩；";
  Sentence[1907] = "我在大會中未曾隱瞞你的慈愛和誠實。";
  Sentence[1908] = "耶和華啊，";
  Sentence[1909] = "求你不要向我止住你的慈悲！";
  Sentence[1910] = "願你的慈愛和誠實常常保佑我！";
  Sentence[1911] = "因有無數的禍患圍困我，";
  Sentence[1912] = "我的罪孽追上了我，";
  Sentence[1913] = "使我不能昂首；";
  Sentence[1914] = "這罪孽比我的頭髮還多，";
  Sentence[1915] = "我就心寒膽戰。";
  Sentence[1916] = "耶和華啊，";
  Sentence[1917] = "求你開恩搭救我！";
  Sentence[1918] = "耶和華啊，";
  Sentence[1919] = "求你速速幫助我！";
  Sentence[1920] = "願那些尋找我、";
  Sentence[1921] = "要滅我命的，";
  Sentence[1922] = "一同抱愧蒙羞！";
  Sentence[1923] = "願那些喜悅我受害的，";
  Sentence[1924] = "退後受辱！";
  Sentence[1925] = "願那些對我說阿哈、";
  Sentence[1926] = "阿哈的，";
  Sentence[1927] = "因羞愧而敗亡！";
  Sentence[1928] = "願一切尋求你的，";
  Sentence[1929] = "因你高興歡喜！";
  Sentence[1930] = "願那些喜愛你救恩的，";
  Sentence[1931] = "常說：";
  Sentence[1932] = "當尊耶和華為大！";
  Sentence[1933] = "但我是困苦窮乏的，";
  Sentence[1934] = "主仍顧念我；";
  Sentence[1935] = "你是幫助我的，";
  Sentence[1936] = "搭救我的。";
  Sentence[1937] = "神啊，";
  Sentence[1938] = "求你不要耽延！";
  Sentence[1939] = "詩篇卌一篇";
  Sentence[1940] = "眷顧貧窮的有福了！";
  Sentence[1941] = "他遭難的日子，";
  Sentence[1942] = "耶和華必搭救他。";
  Sentence[1943] = "耶和華必保全他，";
  Sentence[1944] = "使他存活；";
  Sentence[1945] = "他必在地上享福。";
  Sentence[1946] = "求你不要把他交給仇敵，";
  Sentence[1947] = "遂其所願。";
  Sentence[1948] = "他病重在榻，";
  Sentence[1949] = "耶和華必扶持他；";
  Sentence[1950] = "他在病中，";
  Sentence[1951] = "你必給他鋪床。";
  Sentence[1952] = "我曾說：";
  Sentence[1953] = "耶和華啊，";
  Sentence[1954] = "求你憐恤我，";
  Sentence[1955] = "醫治我！";
  Sentence[1956] = "因為我得罪了你。";
  Sentence[1957] = "我的仇敵用惡言議論我說：";
  Sentence[1958] = "他幾時死，";
  Sentence[1959] = "他的名才滅亡呢？";
  Sentence[1960] = "他來看我就說假話；";
  Sentence[1961] = "他心存奸惡，";
  Sentence[1962] = "走到外邊才說出來。";
  Sentence[1963] = "一切恨我的，";
  Sentence[1964] = "都交頭接耳地議論我；";
  Sentence[1965] = "他們設計要害我。";
  Sentence[1966] = "他們說：";
  Sentence[1967] = "有怪病貼在他身上；";
  Sentence[1968] = "他已躺臥，";
  Sentence[1969] = "必不能再起來。";
  Sentence[1970] = "連我知己的朋友，";
  Sentence[1971] = "我所倚靠、";
  Sentence[1972] = "吃過我飯的也用腳踢我。";
  Sentence[1973] = "耶和華啊，";
  Sentence[1974] = "求你憐恤我，";
  Sentence[1975] = "使我起來，";
  Sentence[1976] = "好報復他們！";
  Sentence[1977] = "因我的仇敵不得向我誇勝，";
  Sentence[1978] = "我從此便知道你喜愛我。";
  Sentence[1979] = "你因我純正就扶持我，";
  Sentence[1980] = "使我永遠站在你的面前。";
  Sentence[1981] = "耶和華－";
  Sentence[1982] = "以色列的神是應當稱頌的，";
  Sentence[1983] = "從亙古直到永遠。";
  Sentence[1984] = "阿們！";
  Sentence[1985] = "阿們！";
  Sentence[1986] = "詩篇卌二篇";
  Sentence[1987] = "神啊，";
  Sentence[1988] = "我的心切慕你，";
  Sentence[1989] = "如鹿切慕溪水。";
  Sentence[1990] = "我的心渴想神，";
  Sentence[1991] = "就是永生神；";
  Sentence[1992] = "我幾時得朝見神呢？";
  Sentence[1993] = "我晝夜以眼淚當飲食；";
  Sentence[1994] = "人不住地對我說：";
  Sentence[1995] = "你的神在哪裡呢？";
  Sentence[1996] = "我從前與眾人同往，";
  Sentence[1997] = "用歡呼稱讚的聲音領他們到神的殿裡，";
  Sentence[1998] = "大家守節。";
  Sentence[1999] = "我追想這些事，";
  Sentence[2000] = "我的心極其悲傷。";
  Sentence[2001] = "我的心哪，";
  Sentence[2002] = "你為何憂悶？";
  Sentence[2003] = "為何在我裡面煩躁？";
  Sentence[2004] = "應當仰望神，";
  Sentence[2005] = "因他笑臉幫助我；";
  Sentence[2006] = "我還要稱讚他。";
  Sentence[2007] = "我的神啊，";
  Sentence[2008] = "我的心在我裡面憂悶，";
  Sentence[2009] = "所以我從約但地，";
  Sentence[2010] = "從黑門嶺，";
  Sentence[2011] = "從米薩山記念你。";
  Sentence[2012] = "你的瀑布發聲，";
  Sentence[2013] = "深淵就與深淵響應；";
  Sentence[2014] = "你的波浪洪濤漫過我身。";
  Sentence[2015] = "白晝，";
  Sentence[2016] = "耶和華必向我施慈愛；";
  Sentence[2017] = "黑夜，";
  Sentence[2018] = "我要歌頌禱告賜我生命的神。";
  Sentence[2019] = "我要對神－";
  Sentence[2020] = "我的磐石說：";
  Sentence[2021] = "你為何忘記我呢？";
  Sentence[2022] = "我為何因仇敵的欺壓時常哀痛呢？";
  Sentence[2023] = "我的敵人辱罵我，";
  Sentence[2024] = "好像打碎我的骨頭，";
  Sentence[2025] = "不住地對我說：";
  Sentence[2026] = "你的神在哪裡呢？";
  Sentence[2027] = "我的心哪，";
  Sentence[2028] = "你為何憂悶？";
  Sentence[2029] = "為何在我裡面煩躁？";
  Sentence[2030] = "應當仰望神，";
  Sentence[2031] = "因我還要稱讚他。";
  Sentence[2032] = "他是我臉上的光榮，";
  Sentence[2033] = "是我的神。";
  Sentence[2034] = "詩篇卌三篇";
  Sentence[2035] = "神啊，";
  Sentence[2036] = "求你伸我的冤，";
  Sentence[2037] = "向不虔誠的國為我辨屈；";
  Sentence[2038] = "求你救我脫離詭詐不義的人。";
  Sentence[2039] = "因為你是賜我力量的神，";
  Sentence[2040] = "為何丟棄我呢？";
  Sentence[2041] = "我為何因仇敵的欺壓時常哀痛呢？";
  Sentence[2042] = "求你發出你的亮光和真實，";
  Sentence[2043] = "好引導我，";
  Sentence[2044] = "帶我到你的聖山，";
  Sentence[2045] = "到你的居所！";
  Sentence[2046] = "我就走到神的祭壇，";
  Sentence[2047] = "到我最喜樂的神那裡。";
  Sentence[2048] = "神啊，";
  Sentence[2049] = "我的神，";
  Sentence[2050] = "我要彈琴稱讚你！";
  Sentence[2051] = "我的心哪，";
  Sentence[2052] = "你為何憂悶？";
  Sentence[2053] = "為何在我裡面煩躁？";
  Sentence[2054] = "應當仰望神，";
  Sentence[2055] = "因我還要稱讚他。";
  Sentence[2056] = "他是我臉上的光榮，";
  Sentence[2057] = "是我的神。";
  Sentence[2058] = "詩篇卌四篇";
  Sentence[2059] = "神啊，";
  Sentence[2060] = "你在古時，";
  Sentence[2061] = "我們列祖的日子所行的事，";
  Sentence[2062] = "我們親耳聽見了；";
  Sentence[2063] = "我們的列祖也給我們述說過。";
  Sentence[2064] = "你曾用手趕出外邦人，";
  Sentence[2065] = "卻栽培了我們列祖；";
  Sentence[2066] = "你苦待列邦，";
  Sentence[2067] = "卻叫我們列祖發達。";
  Sentence[2068] = "因為他們不是靠自己的刀劍得地土，";
  Sentence[2069] = "也不是靠自己的膀臂得勝，";
  Sentence[2070] = "乃是靠你的右手、";
  Sentence[2071] = "你的膀臂，";
  Sentence[2072] = "和你臉上的亮光，";
  Sentence[2073] = "因為你喜悅他們。";
  Sentence[2074] = "神啊，";
  Sentence[2075] = "你是我的王；";
  Sentence[2076] = "求你出令使雅各得勝。";
  Sentence[2077] = "我們靠你要推倒我們的敵人，";
  Sentence[2078] = "靠你的名要踐踏那起來攻擊我們的人。";
  Sentence[2079] = "因為，";
  Sentence[2080] = "我必不靠我的弓；";
  Sentence[2081] = "我的刀也不能使我得勝。";
  Sentence[2082] = "惟你救了我們脫離敵人，";
  Sentence[2083] = "使恨我們的人羞愧。";
  Sentence[2084] = "我們終日因神誇耀，";
  Sentence[2085] = "還要永遠稱謝你的名。";
  Sentence[2086] = "但如今你丟棄了我們，";
  Sentence[2087] = "使我們受辱，";
  Sentence[2088] = "不和我們的軍兵同去。";
  Sentence[2089] = "你使我們向敵人轉身退後；";
  Sentence[2090] = "那恨我們的人任意搶奪。";
  Sentence[2091] = "你使我們當作快要被吃的羊，";
  Sentence[2092] = "把我們分散在列邦中。";
  Sentence[2093] = "你賣了你的子民也不賺利，";
  Sentence[2094] = "所得的價值並不加添你的資財。";
  Sentence[2095] = "你使我們受鄰國的羞辱，";
  Sentence[2096] = "被四圍的人嗤笑譏刺。";
  Sentence[2097] = "你使我們在列邦中作了笑談，";
  Sentence[2098] = "使眾民向我們搖頭。";
  Sentence[2099] = "我的凌辱終日在我面前，";
  Sentence[2100] = "我臉上的羞愧將我遮蔽，";
  Sentence[2101] = "都因那辱罵毀謗人的聲音，";
  Sentence[2102] = "又因仇敵和報仇人的緣故。";
  Sentence[2103] = "這都臨到我們身上，";
  Sentence[2104] = "我們卻沒有忘記你，";
  Sentence[2105] = "也沒有違背你的約。";
  Sentence[2106] = "我們的心沒有退後；";
  Sentence[2107] = "我們的腳也沒有偏離你的路。";
  Sentence[2108] = "你在野狗之處壓傷我們，";
  Sentence[2109] = "用死蔭遮蔽我們。";
  Sentence[2110] = "倘若我們忘了神的名，";
  Sentence[2111] = "或向別神舉手，";
  Sentence[2112] = "神豈不鑒察這事嗎？";
  Sentence[2113] = "因為他曉得人心裡的隱祕。";
  Sentence[2114] = "我們為你的緣故終日被殺；";
  Sentence[2115] = "人看我們如將宰的羊。";
  Sentence[2116] = "主啊，";
  Sentence[2117] = "求你睡醒，";
  Sentence[2118] = "為何儘睡呢？";
  Sentence[2119] = "求你興起，";
  Sentence[2120] = "不要永遠丟棄我們！";
  Sentence[2121] = "你為何掩面，";
  Sentence[2122] = "不顧我們所遭的苦難和所受的欺壓？";
  Sentence[2123] = "我們的性命伏於塵土；";
  Sentence[2124] = "我們的肚腹緊貼地面。";
  Sentence[2125] = "求你起來幫助我們！";
  Sentence[2126] = "憑你的慈愛救贖我們！";
  Sentence[2127] = "詩篇卌五篇";
  Sentence[2128] = "我心裡湧出美辭；";
  Sentence[2129] = "我論到我為王做的事，";
  Sentence[2130] = "我的舌頭是快手筆。";
  Sentence[2131] = "你比世人更美；";
  Sentence[2132] = "在你嘴裡滿有恩惠；";
  Sentence[2133] = "所以神賜福給你，";
  Sentence[2134] = "直到永遠。";
  Sentence[2135] = "大能者啊，";
  Sentence[2136] = "願你腰間佩刀，";
  Sentence[2137] = "大有榮耀和威嚴！";
  Sentence[2138] = "為真理、";
  Sentence[2139] = "謙卑、";
  Sentence[2140] = "公義赫然坐車前往，";
  Sentence[2141] = "無不得勝；";
  Sentence[2142] = "你的右手必顯明可畏的事。";
  Sentence[2143] = "你的箭鋒快，";
  Sentence[2144] = "射中王敵之心；";
  Sentence[2145] = "萬民仆倒在你以下。";
  Sentence[2146] = "神啊，";
  Sentence[2147] = "你的寶座是永永遠遠的；";
  Sentence[2148] = "你的國權是正直的。";
  Sentence[2149] = "你喜愛公義，";
  Sentence[2150] = "恨惡罪惡；";
  Sentence[2151] = "所以神－";
  Sentence[2152] = "就是你的神－";
  Sentence[2153] = "用喜樂油膏你，";
  Sentence[2154] = "勝過膏你的同伴。";
  Sentence[2155] = "你的衣服都有沒藥、";
  Sentence[2156] = "沉香、";
  Sentence[2157] = "肉桂的香氣；";
  Sentence[2158] = "象牙宮中有絲弦樂器的聲音使你歡喜。";
  Sentence[2159] = "有君王的女兒在你尊貴婦女之中；";
  Sentence[2160] = "王后佩戴俄斐金飾站在你右邊。";
  Sentence[2161] = "女子啊，";
  Sentence[2162] = "你要聽，";
  Sentence[2163] = "要想，";
  Sentence[2164] = "要側耳而聽！";
  Sentence[2165] = "不要記念你的民和你的父家，";
  Sentence[2166] = "王就羨慕你的美貌；";
  Sentence[2167] = "因為他是你的主，";
  Sentence[2168] = "你當敬拜他。";
  Sentence[2169] = "推羅的民必來送禮；";
  Sentence[2170] = "民中的富足人也必向你求恩。";
  Sentence[2171] = "王女在宮裡極其榮華；";
  Sentence[2172] = "他的衣服是用金線繡的。";
  Sentence[2173] = "他要穿錦繡的衣服，";
  Sentence[2174] = "被引到王前；";
  Sentence[2175] = "隨從他的陪伴童女也要被帶到你面前。";
  Sentence[2176] = "他們要歡喜快樂被引導；";
  Sentence[2177] = "他們要進入王宮。";
  Sentence[2178] = "你的子孫要接續你的列祖；";
  Sentence[2179] = "你要立他們在全地作王。";
  Sentence[2180] = "我必叫你的名被萬代記念，";
  Sentence[2181] = "所以萬民要永永遠遠稱謝你。";
  Sentence[2182] = "詩篇卌六篇";
  Sentence[2183] = "神是我們的避難所，";
  Sentence[2184] = "是我們的力量，";
  Sentence[2185] = "是我們在患難中隨時的幫助。";
  Sentence[2186] = "所以，";
  Sentence[2187] = "地雖改變，";
  Sentence[2188] = "山雖搖動到海心，";
  Sentence[2189] = "其中的水雖匉訇翻騰，";
  Sentence[2190] = "山雖因海漲而戰抖，";
  Sentence[2191] = "我們也不害怕。";
  Sentence[2192] = "有一道河，";
  Sentence[2193] = "這河的分汊使神的城歡喜；";
  Sentence[2194] = "這城就是至高者居住的聖所。";
  Sentence[2195] = "神在其中，";
  Sentence[2196] = "城必不動搖；";
  Sentence[2197] = "到天一亮，";
  Sentence[2198] = "神必幫助這城。";
  Sentence[2199] = "外邦喧嚷，";
  Sentence[2200] = "列國動搖；";
  Sentence[2201] = "神發聲，";
  Sentence[2202] = "地便鎔化。";
  Sentence[2203] = "萬軍之耶和華與我們同在；";
  Sentence[2204] = "雅各的神是我們的避難所！";
  Sentence[2205] = "你們來看耶和華的作為，";
  Sentence[2206] = "看他使地怎樣荒涼。";
  Sentence[2207] = "他止息刀兵，";
  Sentence[2208] = "直到地極；";
  Sentence[2209] = "他折弓、";
  Sentence[2210] = "斷槍，";
  Sentence[2211] = "把戰車焚燒在火中。";
  Sentence[2212] = "你們要休息，";
  Sentence[2213] = "要知道我是神！";
  Sentence[2214] = "我必在外邦中被尊崇，";
  Sentence[2215] = "在遍地上也被尊崇。";
  Sentence[2216] = "萬軍之耶和華與我們同在；";
  Sentence[2217] = "雅各的神是我們的避難所！";
  Sentence[2218] = "詩篇卌七篇";
  Sentence[2219] = "萬民哪，";
  Sentence[2220] = "你們都要拍掌！";
  Sentence[2221] = "要用誇勝的聲音向神呼喊！";
  Sentence[2222] = "因為耶和華至高者是可畏的；";
  Sentence[2223] = "他是治理全地的大君王。";
  Sentence[2224] = "他叫萬民服在我們以下，";
  Sentence[2225] = "又叫列邦服在我們腳下。";
  Sentence[2226] = "他為我們選擇產業，";
  Sentence[2227] = "就是他所愛之雅各的榮耀。";
  Sentence[2228] = "神上升，";
  Sentence[2229] = "有喊聲相送；";
  Sentence[2230] = "耶和華上升，";
  Sentence[2231] = "有角聲相送。";
  Sentence[2232] = "你們要向神歌頌，";
  Sentence[2233] = "歌頌！";
  Sentence[2234] = "向我們王歌頌，";
  Sentence[2235] = "歌頌！";
  Sentence[2236] = "因為神是全地的王；";
  Sentence[2237] = "你們要用悟性歌頌。";
  Sentence[2238] = "神作王治理萬國；";
  Sentence[2239] = "神坐在他的聖寶座上。";
  Sentence[2240] = "列邦的君王聚集要作亞伯拉罕之神的民。";
  Sentence[2241] = "因為世界的盾牌是屬神的；";
  Sentence[2242] = "他為至高！";
  Sentence[2243] = "詩篇卌八篇";
  Sentence[2244] = "耶和華本為大！";
  Sentence[2245] = "在我們神的城中，";
  Sentence[2246] = "在他的聖山上，";
  Sentence[2247] = "該受大讚美。";
  Sentence[2248] = "錫安山－";
  Sentence[2249] = "大君王的城，";
  Sentence[2250] = "在北面居高華美，";
  Sentence[2251] = "為全地所喜悅。";
  Sentence[2252] = "神在其宮中，";
  Sentence[2253] = "自顯為避難所。";
  Sentence[2254] = "看哪，";
  Sentence[2255] = "眾王會合，";
  Sentence[2256] = "一同經過。";
  Sentence[2257] = "他們見了這城就驚奇喪膽，";
  Sentence[2258] = "急忙逃跑。";
  Sentence[2259] = "他們在那裡被戰兢疼痛抓住，";
  Sentence[2260] = "好像產難的婦人一樣。";
  Sentence[2261] = "神啊，";
  Sentence[2262] = "你用東風打破他施的船隻。";
  Sentence[2263] = "我們在萬軍之耶和華的城中－";
  Sentence[2264] = "就是我們神的城中－";
  Sentence[2265] = "所看見的，";
  Sentence[2266] = "正如我們所聽見的。";
  Sentence[2267] = "神必堅立這城，";
  Sentence[2268] = "直到永遠。";
  Sentence[2269] = "神啊，";
  Sentence[2270] = "我們在你的殿中想念你的慈愛。";
  Sentence[2271] = "神啊，";
  Sentence[2272] = "你受的讚美正與你的名相稱，";
  Sentence[2273] = "直到地極！";
  Sentence[2274] = "你的右手滿了公義。";
  Sentence[2275] = "因你的判斷，";
  Sentence[2276] = "錫安山應當歡喜，";
  Sentence[2277] = "猶大的城邑應當快樂。";
  Sentence[2278] = "你們當周遊錫安，";
  Sentence[2279] = "四圍旋繞，";
  Sentence[2280] = "數點城樓，";
  Sentence[2281] = "細看他的外郭，";
  Sentence[2282] = "察看他的宮殿，";
  Sentence[2283] = "為要傳說到後代。";
  Sentence[2284] = "因為這神永永遠遠為我們的神；";
  Sentence[2285] = "他必作我們引路的，";
  Sentence[2286] = "直到死時。";
  Sentence[2287] = "詩篇卌九篇";
  Sentence[2288] = "萬民哪，";
  Sentence[2289] = "你們都當聽這話！";
  Sentence[2290] = "世上一切的居民，";
  Sentence[2291] = "無論上流下流，";
  Sentence[2292] = "富足貧窮，";
  Sentence[2293] = "都當留心聽！";
  Sentence[2294] = "我口要說智慧的言語；";
  Sentence[2295] = "我心要想通達的道理。";
  Sentence[2296] = "我要側耳聽比喻，";
  Sentence[2297] = "用琴解謎語。";
  Sentence[2298] = "在患難的日子，";
  Sentence[2299] = "奸惡隨我腳跟，";
  Sentence[2300] = "四面環繞我，";
  Sentence[2301] = "我何必懼怕？";
  Sentence[2302] = "那些倚仗財貨自誇錢財多的人，";
  Sentence[2303] = "一個也無法贖自己的弟兄，";
  Sentence[2304] = "也不能替他將贖價給神，";
  Sentence[2305] = "叫他長遠活著，";
  Sentence[2306] = "不見朽壞；";
  Sentence[2307] = "因為贖他生命的價值極貴，";
  Sentence[2308] = "只可永遠罷休。";
  Sentence[2309] = "他必見智慧人死，";
  Sentence[2310] = "又見愚頑人和畜類人一同滅亡，";
  Sentence[2311] = "將他們的財貨留給別人。";
  Sentence[2312] = "他們心裡思想：";
  Sentence[2313] = "他們的家室必永存，";
  Sentence[2314] = "住宅必留到萬代；";
  Sentence[2315] = "他們以自己的名稱自己的地。";
  Sentence[2316] = "但人居尊貴中不能長久，";
  Sentence[2317] = "如同死亡的畜類一樣。";
  Sentence[2318] = "他們行的這道本為自己的愚昧；";
  Sentence[2319] = "但他們以後的人還佩服他們的話語。";
  Sentence[2320] = "他們如同羊群派定下陰間；";
  Sentence[2321] = "死亡必作他們的牧者。";
  Sentence[2322] = "到了早晨，";
  Sentence[2323] = "正直人必管轄他們；";
  Sentence[2324] = "他們的美容必被陰間所滅，";
  Sentence[2325] = "以致無處可存。";
  Sentence[2326] = "只是神必救贖我的靈魂脫離陰間的權柄，";
  Sentence[2327] = "因他必收納我。";
  Sentence[2328] = "見人發財、";
  Sentence[2329] = "家室增榮的時候，";
  Sentence[2330] = "你不要懼怕；";
  Sentence[2331] = "因為，";
  Sentence[2332] = "他死的時候什麼也不能帶去；";
  Sentence[2333] = "他的榮耀不能隨他下去。";
  Sentence[2334] = "他活著的時候，";
  Sentence[2335] = "雖然自誇為有福；";
  Sentence[2336] = "他仍必歸到他歷代的祖宗那裡，";
  Sentence[2337] = "永不見光。";
  Sentence[2338] = "人在尊貴中而不醒悟，";
  Sentence[2339] = "就如死亡的畜類一樣。";
  Sentence[2340] = "詩篇五十篇";
  Sentence[2341] = "大能者神－";
  Sentence[2342] = "耶和華已經發言招呼天下，";
  Sentence[2343] = "從日出之地到日落之處。";
  Sentence[2344] = "從全美的錫安中，";
  Sentence[2345] = "神已經發光了。";
  Sentence[2346] = "我們的神要來，";
  Sentence[2347] = "決不閉口。";
  Sentence[2348] = "有烈火在他面前吞滅；";
  Sentence[2349] = "有暴風在他四圍大颳。";
  Sentence[2350] = "他招呼上天下地，";
  Sentence[2351] = "為要審判他的民，";
  Sentence[2352] = "說：";
  Sentence[2353] = "招聚我的聖民到我這裡來，";
  Sentence[2354] = "就是那些用祭物與我立約的人。";
  Sentence[2355] = "諸天必表明他的公義，";
  Sentence[2356] = "因為神是施行審判的。";
  Sentence[2357] = "我的民哪，";
  Sentence[2358] = "你們當聽我的話！";
  Sentence[2359] = "以色列啊，";
  Sentence[2360] = "我要勸戒你；";
  Sentence[2361] = "我是神，";
  Sentence[2362] = "是你的神！";
  Sentence[2363] = "我並不因你的祭物責備你；";
  Sentence[2364] = "你的燔祭常在我面前。";
  Sentence[2365] = "我不從你家中取公牛，";
  Sentence[2366] = "也不從你圈內取山羊；";
  Sentence[2367] = "因為，";
  Sentence[2368] = "樹林中的百獸是我的，";
  Sentence[2369] = "千山上的牲畜也是我的。";
  Sentence[2370] = "山中的飛鳥，";
  Sentence[2371] = "我都知道；";
  Sentence[2372] = "野地的走獸也都屬我。";
  Sentence[2373] = "我若是飢餓，";
  Sentence[2374] = "我不用告訴你，";
  Sentence[2375] = "因為世界和其中所充滿的都是我的。";
  Sentence[2376] = "我豈吃公牛的肉呢？";
  Sentence[2377] = "我豈喝山羊的血呢？";
  Sentence[2378] = "你們要以感謝為祭獻與神，";
  Sentence[2379] = "又要向至高者還你的願，";
  Sentence[2380] = "並要在患難之日求告我；";
  Sentence[2381] = "我必搭救你，";
  Sentence[2382] = "你也要榮耀我。";
  Sentence[2383] = "但神對惡人說：";
  Sentence[2384] = "你怎敢傳說我的律例，";
  Sentence[2385] = "口中提到我的約呢？";
  Sentence[2386] = "其實你恨惡管教，";
  Sentence[2387] = "將我的言語丟在背後。";
  Sentence[2388] = "你見了盜賊就樂意與他同夥，";
  Sentence[2389] = "又與行姦淫的人一同有分。";
  Sentence[2390] = "你口任說惡言；";
  Sentence[2391] = "你舌編造詭詐。";
  Sentence[2392] = "你坐著毀謗你的兄弟，";
  Sentence[2393] = "讒毀你親母的兒子。";
  Sentence[2394] = "你行了這些事，";
  Sentence[2395] = "我還閉口不言，";
  Sentence[2396] = "你想我恰和你一樣；";
  Sentence[2397] = "其實我要責備你，";
  Sentence[2398] = "將這些事擺在你眼前。";
  Sentence[2399] = "你們忘記神的，";
  Sentence[2400] = "要思想這事，";
  Sentence[2401] = "免得我把你們撕碎，";
  Sentence[2402] = "無人搭救。";
  Sentence[2403] = "凡以感謝獻上為祭的便是榮耀我；";
  Sentence[2404] = "那按正路而行的，";
  Sentence[2405] = "我必使他得著我的救恩。";
  Sentence[2406] = "詩篇五十一篇";
  Sentence[2407] = "神啊，";
  Sentence[2408] = "求你按你的慈愛憐恤我！";
  Sentence[2409] = "按你豐盛的慈悲塗抹我的過犯！";
  Sentence[2410] = "求你將我的罪孽洗除淨盡，";
  Sentence[2411] = "並潔除我的罪！";
  Sentence[2412] = "因為，";
  Sentence[2413] = "我知道我的過犯；";
  Sentence[2414] = "我的罪常在我面前。";
  Sentence[2415] = "我向你犯罪，";
  Sentence[2416] = "惟獨得罪了你；";
  Sentence[2417] = "在你眼前行了這惡，";
  Sentence[2418] = "以致你責備我的時候顯為公義，";
  Sentence[2419] = "判斷我的時候顯為清正。";
  Sentence[2420] = "我是在罪孽裡生的，";
  Sentence[2421] = "在我母親懷胎的時候就有了罪。";
  Sentence[2422] = "你所喜愛的是內裡誠實；";
  Sentence[2423] = "你在我隱密處，";
  Sentence[2424] = "必使我得智慧。";
  Sentence[2425] = "求你用牛膝草潔淨我，";
  Sentence[2426] = "我就乾淨；";
  Sentence[2427] = "求你洗滌我，";
  Sentence[2428] = "我就比雪更白。";
  Sentence[2429] = "求你使我得聽歡喜快樂的聲音，";
  Sentence[2430] = "使你所壓傷的骨頭可以踴躍。";
  Sentence[2431] = "求你掩面不看我的罪，";
  Sentence[2432] = "塗抹我一切的罪孽。";
  Sentence[2433] = "神啊，";
  Sentence[2434] = "求你為我造清潔的心，";
  Sentence[2435] = "使我裡面重新有正直的靈。";
  Sentence[2436] = "不要丟棄我，";
  Sentence[2437] = "使我離開你的面；";
  Sentence[2438] = "不要從我收回你的聖靈。";
  Sentence[2439] = "求你使我仍得救恩之樂，";
  Sentence[2440] = "賜我樂意的靈扶持我，";
  Sentence[2441] = "我就把你的道指教有過犯的人，";
  Sentence[2442] = "罪人必歸順你。";
  Sentence[2443] = "神啊，";
  Sentence[2444] = "你是拯救我的神；";
  Sentence[2445] = "求你救我脫離流人血的罪！";
  Sentence[2446] = "我的舌頭就高聲歌唱你的公義。";
  Sentence[2447] = "主啊，";
  Sentence[2448] = "求你使我嘴唇張開，";
  Sentence[2449] = "我的口便傳揚讚美你的話！";
  Sentence[2450] = "你本不喜愛祭物，";
  Sentence[2451] = "若喜愛，";
  Sentence[2452] = "我就獻上；";
  Sentence[2453] = "燔祭，";
  Sentence[2454] = "你也不喜悅。";
  Sentence[2455] = "神所要的祭就是憂傷的靈；";
  Sentence[2456] = "神啊，";
  Sentence[2457] = "憂傷痛悔的心，";
  Sentence[2458] = "你必不輕看。";
  Sentence[2459] = "求你隨你的美意善待錫安，";
  Sentence[2460] = "建造耶路撒冷的城牆。";
  Sentence[2461] = "那時，";
  Sentence[2462] = "你必喜愛公義的祭和燔祭並全牲的燔祭；";
  Sentence[2463] = "那時，";
  Sentence[2464] = "人必將公牛獻在你壇上。";
  Sentence[2465] = "詩篇五十二篇";
  Sentence[2466] = "勇士啊，";
  Sentence[2467] = "你為何以作惡自誇？";
  Sentence[2468] = "神的慈愛是常存的。";
  Sentence[2469] = "你的舌頭邪惡詭詐，";
  Sentence[2470] = "好像剃頭刀，";
  Sentence[2471] = "快利傷人。";
  Sentence[2472] = "你愛惡勝似愛善，";
  Sentence[2473] = "又愛說謊，";
  Sentence[2474] = "不愛說公義。";
  Sentence[2475] = "詭詐的舌頭啊，";
  Sentence[2476] = "你愛說一切毀滅的話！";
  Sentence[2477] = "神也要毀滅你，";
  Sentence[2478] = "直到永遠；";
  Sentence[2479] = "他要把你拿去，";
  Sentence[2480] = "從你的帳棚中抽出，";
  Sentence[2481] = "從活人之地將你拔出。";
  Sentence[2482] = "義人要看見而懼怕，";
  Sentence[2483] = "並要笑他，";
  Sentence[2484] = "說：";
  Sentence[2485] = "看哪，";
  Sentence[2486] = "這就是那不以神為他力量的人，";
  Sentence[2487] = "只倚仗他豐富的財物，";
  Sentence[2488] = "在邪惡上堅立自己。";
  Sentence[2489] = "至於我，";
  Sentence[2490] = "就像神殿中的青橄欖樹；";
  Sentence[2491] = "我永永遠遠倚靠神的慈愛。";
  Sentence[2492] = "我要稱謝你，";
  Sentence[2493] = "直到永遠，";
  Sentence[2494] = "因為你行了這事。";
  Sentence[2495] = "我也要在你聖民面前仰望你的名；";
  Sentence[2496] = "這名本為美好。";
  Sentence[2497] = "詩篇五十三篇";
  Sentence[2498] = "愚頑人心裡說：";
  Sentence[2499] = "沒有神。";
  Sentence[2500] = "他們都是邪惡，";
  Sentence[2501] = "行了可憎惡的罪孽；";
  Sentence[2502] = "沒有一個人行善。";
  Sentence[2503] = "神從天上垂看世人，";
  Sentence[2504] = "要看有明白的沒有？";
  Sentence[2505] = "有尋求他的沒有？";
  Sentence[2506] = "他們各人都退後，";
  Sentence[2507] = "一同變為污穢；";
  Sentence[2508] = "並沒有行善的，";
  Sentence[2509] = "連一個也沒有。";
  Sentence[2510] = "作孽的沒有知識嗎？";
  Sentence[2511] = "他們吞吃我的百姓如同吃飯一樣，";
  Sentence[2512] = "並不求告神。";
  Sentence[2513] = "他們在無可懼怕之處就大大害怕，";
  Sentence[2514] = "因為神把那安營攻擊你之人的骨頭散開了。";
  Sentence[2515] = "你使他們蒙羞，";
  Sentence[2516] = "因為神棄絕了他們。";
  Sentence[2517] = "但願以色列的救恩從錫安而出。";
  Sentence[2518] = "神救回他被擄的子民那時，";
  Sentence[2519] = "雅各要快樂，";
  Sentence[2520] = "以色列要歡喜。";
  Sentence[2521] = "詩篇五十四篇";
  Sentence[2522] = "神啊，";
  Sentence[2523] = "求你以你的名救我，";
  Sentence[2524] = "憑你的大能為我伸冤。";
  Sentence[2525] = "神啊，";
  Sentence[2526] = "求你聽我的禱告，";
  Sentence[2527] = "留心聽我口中的言語。";
  Sentence[2528] = "因為，";
  Sentence[2529] = "外人起來攻擊我，";
  Sentence[2530] = "強暴人尋索我的命；";
  Sentence[2531] = "他們眼中沒有神。";
  Sentence[2532] = "神是幫助我的，";
  Sentence[2533] = "是扶持我命的。";
  Sentence[2534] = "他要報應我仇敵所行的惡；";
  Sentence[2535] = "求你憑你的誠實滅絕他們。";
  Sentence[2536] = "我要把甘心祭獻給你。";
  Sentence[2537] = "耶和華啊，";
  Sentence[2538] = "我要稱讚你的名；";
  Sentence[2539] = "這名本為美好。";
  Sentence[2540] = "他從一切的急難中把我救出來；";
  Sentence[2541] = "我的眼睛也看見了我仇敵遭報。";
  Sentence[2542] = "詩篇五十五篇";
  Sentence[2543] = "神啊，";
  Sentence[2544] = "求你留心聽我的禱告，";
  Sentence[2545] = "不要隱藏不聽我的懇求！";
  Sentence[2546] = "求你側耳聽我，";
  Sentence[2547] = "應允我。";
  Sentence[2548] = "我哀歎不安，";
  Sentence[2549] = "發聲唉哼，";
  Sentence[2550] = "都因仇敵的聲音，";
  Sentence[2551] = "惡人的欺壓；";
  Sentence[2552] = "因為他們將罪孽加在我身上，";
  Sentence[2553] = "發怒氣逼迫我。";
  Sentence[2554] = "我心在我裡面甚是疼痛；";
  Sentence[2555] = "死的驚惶臨到我身。";
  Sentence[2556] = "恐懼戰兢歸到我身；";
  Sentence[2557] = "驚恐漫過了我。";
  Sentence[2558] = "我說：";
  Sentence[2559] = "但願我有翅膀像鴿子，";
  Sentence[2560] = "我就飛去，";
  Sentence[2561] = "得享安息。";
  Sentence[2562] = "我必遠遊，";
  Sentence[2563] = "宿在曠野。";
  Sentence[2564] = "我必速速逃到避所，";
  Sentence[2565] = "脫離狂風暴雨。";
  Sentence[2566] = "主啊，";
  Sentence[2567] = "求你吞滅他們，";
  Sentence[2568] = "變亂他們的舌頭！";
  Sentence[2569] = "因為我在城中見了強暴爭競的事。";
  Sentence[2570] = "他們在城牆上晝夜繞行；";
  Sentence[2571] = "在城內也有罪孽和奸惡。";
  Sentence[2572] = "邪惡在其中；";
  Sentence[2573] = "欺壓和詭詐不離街市。";
  Sentence[2574] = "原來不是仇敵辱罵我，";
  Sentence[2575] = "若是仇敵，";
  Sentence[2576] = "還可忍耐；";
  Sentence[2577] = "也不是恨我的人向我狂大，";
  Sentence[2578] = "若是恨我的人就必躲避他。";
  Sentence[2579] = "不料是你；";
  Sentence[2580] = "你原與我平等，";
  Sentence[2581] = "是我的同伴，";
  Sentence[2582] = "是我知己的朋友！";
  Sentence[2583] = "我們素常彼此談論，";
  Sentence[2584] = "以為甘甜；";
  Sentence[2585] = "我們與群眾在神的殿中同行。";
  Sentence[2586] = "願死亡忽然臨到他們！";
  Sentence[2587] = "願他們活活地下入陰間！";
  Sentence[2588] = "因為他們的住處，";
  Sentence[2589] = "他們的心中，";
  Sentence[2590] = "都是邪惡。";
  Sentence[2591] = "至於我，";
  Sentence[2592] = "我要求告神；";
  Sentence[2593] = "耶和華必拯救我。";
  Sentence[2594] = "我要晚上、";
  Sentence[2595] = "早晨、";
  Sentence[2596] = "晌午哀聲悲歎；";
  Sentence[2597] = "他也必聽我的聲音。";
  Sentence[2598] = "他救贖我命脫離攻擊我的人，";
  Sentence[2599] = "使我得享平安，";
  Sentence[2600] = "因為與我相爭的人甚多。";
  Sentence[2601] = "那沒有更變、";
  Sentence[2602] = "不敬畏神的人，";
  Sentence[2603] = "從太古常存的神必聽見而苦待他。";
  Sentence[2604] = "他背了約，";
  Sentence[2605] = "伸手攻擊與他和好的人。";
  Sentence[2606] = "他的口如奶油光滑，";
  Sentence[2607] = "他的心卻懷著爭戰；";
  Sentence[2608] = "他的話比油柔和，";
  Sentence[2609] = "其實是拔出來的刀。";
  Sentence[2610] = "你要把你的重擔卸給耶和華，";
  Sentence[2611] = "他必撫養你；";
  Sentence[2612] = "他永不叫義人動搖。";
  Sentence[2613] = "神啊，";
  Sentence[2614] = "你必使惡人下入滅亡的坑；";
  Sentence[2615] = "流人血、";
  Sentence[2616] = "行詭詐的人必活不到半世，";
  Sentence[2617] = "但我要倚靠你。";
  Sentence[2618] = "詩篇五十六篇";
  Sentence[2619] = "神啊，";
  Sentence[2620] = "求你憐憫我，";
  Sentence[2621] = "因為人要把我吞了，";
  Sentence[2622] = "終日攻擊欺壓我。";
  Sentence[2623] = "我的仇敵終日要把我吞了，";
  Sentence[2624] = "因逞驕傲攻擊我的人甚多。";
  Sentence[2625] = "我懼怕的時候要倚靠你。";
  Sentence[2626] = "我倚靠神，";
  Sentence[2627] = "我要讚美他的話；";
  Sentence[2628] = "我倚靠神，";
  Sentence[2629] = "必不懼怕。";
  Sentence[2630] = "血氣之輩能把我怎麼樣呢？";
  Sentence[2631] = "他們終日顛倒我的話；";
  Sentence[2632] = "他們一切的心思都是要害我。";
  Sentence[2633] = "他們聚集，";
  Sentence[2634] = "埋伏窺探我的腳蹤，";
  Sentence[2635] = "等候要害我的命。";
  Sentence[2636] = "他們豈能因罪孽逃脫嗎？";
  Sentence[2637] = "神啊，";
  Sentence[2638] = "求你在怒中使眾民墮落！";
  Sentence[2639] = "我幾次流離，";
  Sentence[2640] = "你都記數；";
  Sentence[2641] = "求你把我眼淚裝在你的皮袋裡。";
  Sentence[2642] = "這不都記在你冊子上嗎？";
  Sentence[2643] = "我呼求的日子，";
  Sentence[2644] = "我的仇敵都要轉身退後。";
  Sentence[2645] = "神幫助我，";
  Sentence[2646] = "這是我所知道的。";
  Sentence[2647] = "我倚靠神，";
  Sentence[2648] = "我要讚美他的話；";
  Sentence[2649] = "我倚靠耶和華，";
  Sentence[2650] = "我要讚美他的話。";
  Sentence[2651] = "我倚靠神，";
  Sentence[2652] = "必不懼怕。";
  Sentence[2653] = "人能把我怎麼樣呢？";
  Sentence[2654] = "神啊，";
  Sentence[2655] = "我向你所許的願在我身上；";
  Sentence[2656] = "我要將感謝祭獻給你。";
  Sentence[2657] = "因為你救我的命脫離死亡。";
  Sentence[2658] = "你豈不是救護我的腳不跌倒、";
  Sentence[2659] = "使我在生命光中行在神面前嗎？";
  Sentence[2660] = "詩篇五十七篇";
  Sentence[2661] = "神啊，";
  Sentence[2662] = "求你憐憫我，";
  Sentence[2663] = "憐憫我！";
  Sentence[2664] = "因為我的心投靠你。";
  Sentence[2665] = "我要投靠在你翅膀的蔭下，";
  Sentence[2666] = "等到災害過去。";
  Sentence[2667] = "我要求告至高的神，";
  Sentence[2668] = "就是為我成全諸事的神。";
  Sentence[2669] = "那要吞我的人辱罵我的時候，";
  Sentence[2670] = "神從天上必施恩救我，";
  Sentence[2671] = "也必向我發出慈愛和誠實。";
  Sentence[2672] = "我的性命在獅子中間；";
  Sentence[2673] = "我躺臥在性如烈火的世人當中。";
  Sentence[2674] = "他們的牙齒是槍、";
  Sentence[2675] = "箭；";
  Sentence[2676] = "他們的舌頭是快刀。";
  Sentence[2677] = "神啊，";
  Sentence[2678] = "願你崇高過於諸天！";
  Sentence[2679] = "願你的榮耀高過全地！";
  Sentence[2680] = "他們為我的腳設下網羅，";
  Sentence[2681] = "壓制我的心；";
  Sentence[2682] = "他們在我面前挖了坑，";
  Sentence[2683] = "自己反掉在其中。";
  Sentence[2684] = "神啊，";
  Sentence[2685] = "我心堅定，";
  Sentence[2686] = "我心堅定；";
  Sentence[2687] = "我要唱詩，";
  Sentence[2688] = "我要歌頌！";
  Sentence[2689] = "我的靈啊，";
  Sentence[2690] = "你當醒起！";
  Sentence[2691] = "琴瑟啊，";
  Sentence[2692] = "你們當醒起！";
  Sentence[2693] = "我自己要極早醒起！";
  Sentence[2694] = "主啊，";
  Sentence[2695] = "我要在萬民中稱謝你，";
  Sentence[2696] = "在列邦中歌頌你！";
  Sentence[2697] = "因為，";
  Sentence[2698] = "你的慈愛高及諸天；";
  Sentence[2699] = "你的誠實達到穹蒼。";
  Sentence[2700] = "神啊，";
  Sentence[2701] = "願你崇高過於諸天！";
  Sentence[2702] = "願你的榮耀高過全地！";
  Sentence[2703] = "詩篇五十八篇";
  Sentence[2704] = "世人哪，";
  Sentence[2705] = "你們默然不語，";
  Sentence[2706] = "真合公義嗎？";
  Sentence[2707] = "施行審判，";
  Sentence[2708] = "豈按正直嗎？";
  Sentence[2709] = "不然！";
  Sentence[2710] = "你們是心中作惡；";
  Sentence[2711] = "你們在地上秤出你們手所行的強暴。";
  Sentence[2712] = "惡人一出母胎就與神疏遠，";
  Sentence[2713] = "一離母腹便走錯路，";
  Sentence[2714] = "說謊話。";
  Sentence[2715] = "他們的毒氣好像蛇的毒氣；";
  Sentence[2716] = "他們好像塞耳的聾虺，";
  Sentence[2717] = "不聽行法術的聲音，";
  Sentence[2718] = "雖用極靈的咒語也是不聽。";
  Sentence[2719] = "神啊，";
  Sentence[2720] = "求你敲碎他們口中的牙！";
  Sentence[2721] = "耶和華啊，";
  Sentence[2722] = "求你敲掉少壯獅子的大牙！";
  Sentence[2723] = "願他們消滅，";
  Sentence[2724] = "如急流的水一般；";
  Sentence[2725] = "他們瞅準射箭的時候，";
  Sentence[2726] = "願箭頭彷彿砍斷。";
  Sentence[2727] = "願他們像蝸牛消化過去，";
  Sentence[2728] = "又像婦人墜落未見天日的胎。";
  Sentence[2729] = "你們用荊棘燒火，";
  Sentence[2730] = "鍋還未熱，";
  Sentence[2731] = "他要用旋風把青的和燒著的一齊颳去。";
  Sentence[2732] = "義人見仇敵遭報就歡喜，";
  Sentence[2733] = "要在惡人的血中洗腳。";
  Sentence[2734] = "因此，";
  Sentence[2735] = "人必說：";
  Sentence[2736] = "義人誠然有善報；";
  Sentence[2737] = "在地上果有施行判斷的神！";
  Sentence[2738] = "詩篇五十九篇";
  Sentence[2739] = "我的神啊，";
  Sentence[2740] = "求你救我脫離仇敵，";
  Sentence[2741] = "把我安置在高處，";
  Sentence[2742] = "得脫那些起來攻擊我的人。";
  Sentence[2743] = "求你救我脫離作孽的人和喜愛流人血的人！";
  Sentence[2744] = "因為，";
  Sentence[2745] = "他們埋伏要害我的命；";
  Sentence[2746] = "有能力的人聚集來攻擊我。";
  Sentence[2747] = "耶和華啊，";
  Sentence[2748] = "這不是為我的過犯，";
  Sentence[2749] = "也不是為我的罪愆。";
  Sentence[2750] = "我雖然無過，";
  Sentence[2751] = "他們預備整齊，";
  Sentence[2752] = "跑來攻擊我。";
  Sentence[2753] = "求你興起鑒察，";
  Sentence[2754] = "幫助我！";
  Sentence[2755] = "萬軍之神－";
  Sentence[2756] = "耶和華以色列的神啊！";
  Sentence[2757] = "求你興起，";
  Sentence[2758] = "懲治萬邦！";
  Sentence[2759] = "不要憐憫行詭詐的惡人！";
  Sentence[2760] = "他們晚上轉回，";
  Sentence[2761] = "叫號如狗，";
  Sentence[2762] = "圍城繞行。";
  Sentence[2763] = "他們口中噴吐惡言，";
  Sentence[2764] = "嘴裡有刀；";
  Sentence[2765] = "他們說：";
  Sentence[2766] = "有誰聽見？";
  Sentence[2767] = "但你－";
  Sentence[2768] = "耶和華必笑話他們；";
  Sentence[2769] = "你要嗤笑萬邦。";
  Sentence[2770] = "我的力量啊，";
  Sentence[2771] = "我必仰望你，";
  Sentence[2772] = "因為神是我的高臺。";
  Sentence[2773] = "我的神要以慈愛迎接我；";
  Sentence[2774] = "神要叫我看見我仇敵遭報。";
  Sentence[2775] = "不要殺他們，";
  Sentence[2776] = "恐怕我的民忘記。";
  Sentence[2777] = "主啊，";
  Sentence[2778] = "你是我們的盾牌；";
  Sentence[2779] = "求你用你的能力使他們四散，";
  Sentence[2780] = "且降為卑。";
  Sentence[2781] = "因他們口中的罪和嘴裡的言語，";
  Sentence[2782] = "並咒罵虛謊的話，";
  Sentence[2783] = "願他們在驕傲之中被纏住了。";
  Sentence[2784] = "求你發怒，";
  Sentence[2785] = "使他們消滅，";
  Sentence[2786] = "以致歸於無有，";
  Sentence[2787] = "叫他們知道神在雅各中間掌權，";
  Sentence[2788] = "直到地極。";
  Sentence[2789] = "到了晚上，";
  Sentence[2790] = "任憑他們轉回；";
  Sentence[2791] = "任憑他們叫號如狗，";
  Sentence[2792] = "圍城繞行。";
  Sentence[2793] = "他們必走來走去，";
  Sentence[2794] = "尋找食物，";
  Sentence[2795] = "若不得飽就終夜在外。";
  Sentence[2796] = "但我要歌頌你的力量，";
  Sentence[2797] = "早晨要高唱你的慈愛；";
  Sentence[2798] = "因為你作過我的高臺，";
  Sentence[2799] = "在我急難的日子作過我的避難所。";
  Sentence[2800] = "我的力量啊，";
  Sentence[2801] = "我要歌頌你；";
  Sentence[2802] = "因為神是我的高臺，";
  Sentence[2803] = "是賜恩與我的神。";
  Sentence[2804] = "詩篇六十篇";
  Sentence[2805] = "神啊，";
  Sentence[2806] = "你丟棄了我們，";
  Sentence[2807] = "使我們破敗；";
  Sentence[2808] = "你向我們發怒，";
  Sentence[2809] = "求你使我們復興！";
  Sentence[2810] = "你使地震動，";
  Sentence[2811] = "而且崩裂；";
  Sentence[2812] = "求你將裂口醫好，";
  Sentence[2813] = "因為地搖動。";
  Sentence[2814] = "你叫你的民遇見艱難；";
  Sentence[2815] = "你叫我們喝那使人東倒西歪的酒。";
  Sentence[2816] = "你把旌旗賜給敬畏你的人，";
  Sentence[2817] = "可以為真理揚起來。";
  Sentence[2818] = "求你應允我們，";
  Sentence[2819] = "用右手拯救我們，";
  Sentence[2820] = "好叫你所親愛的人得救。";
  Sentence[2821] = "神已經指著他的聖潔說：";
  Sentence[2822] = "我要歡樂；";
  Sentence[2823] = "我要分開示劍，";
  Sentence[2824] = "丈量疏割谷。";
  Sentence[2825] = "基列是我的，";
  Sentence[2826] = "瑪拿西也是我的。";
  Sentence[2827] = "以法蓮是護衛我頭的；";
  Sentence[2828] = "猶大是我的杖。";
  Sentence[2829] = "摩押是我的沐浴盆；";
  Sentence[2830] = "我要向以東拋鞋。";
  Sentence[2831] = "非利士啊，";
  Sentence[2832] = "你還能因我歡呼嗎？";
  Sentence[2833] = "誰能領我進堅固城？";
  Sentence[2834] = "誰能引我到以東地？";
  Sentence[2835] = "神啊，";
  Sentence[2836] = "你不是丟棄了我們嗎？";
  Sentence[2837] = "神啊，";
  Sentence[2838] = "你不和我們的軍兵同去嗎？";
  Sentence[2839] = "求你幫助我們攻擊敵人，";
  Sentence[2840] = "因為人的幫助是枉然的。";
  Sentence[2841] = "我們倚靠神才得施展大能，";
  Sentence[2842] = "因為踐踏我們敵人的就是他。";
  Sentence[2843] = "詩篇六十一篇";
  Sentence[2844] = "神啊，";
  Sentence[2845] = "求你聽我的呼求，";
  Sentence[2846] = "側耳聽我的禱告！";
  Sentence[2847] = "我心裡發昏的時候，";
  Sentence[2848] = "我要從地極求告你。";
  Sentence[2849] = "求你領我到那比我更高的磐石！";
  Sentence[2850] = "因為你作過我的避難所，";
  Sentence[2851] = "作過我的堅固臺，";
  Sentence[2852] = "脫離仇敵。";
  Sentence[2853] = "我要永遠住在你的帳幕裡！";
  Sentence[2854] = "我要投靠在你翅膀下的隱密處！";
  Sentence[2855] = "神啊，";
  Sentence[2856] = "你原是聽了我所許的願；";
  Sentence[2857] = "你將產業賜給敬畏你名的人。";
  Sentence[2858] = "你要加添王的壽數；";
  Sentence[2859] = "他的年歲必存到世世。";
  Sentence[2860] = "他必永遠坐在神面前；";
  Sentence[2861] = "願你預備慈愛和誠實保佑他！";
  Sentence[2862] = "這樣，";
  Sentence[2863] = "我要歌頌你的名，";
  Sentence[2864] = "直到永遠，";
  Sentence[2865] = "好天天還我所許的願。";
  Sentence[2866] = "詩篇六十二篇";
  Sentence[2867] = "我的心默默無聲，";
  Sentence[2868] = "專等候神；";
  Sentence[2869] = "我的救恩是從他而來。";
  Sentence[2870] = "惟獨他是我的磐石，";
  Sentence[2871] = "我的拯救；";
  Sentence[2872] = "他是我的高臺，";
  Sentence[2873] = "我必不很動搖。";
  Sentence[2874] = "你們大家攻擊一人，";
  Sentence[2875] = "把他毀壞，";
  Sentence[2876] = "如同毀壞歪斜的牆、";
  Sentence[2877] = "將倒的壁，";
  Sentence[2878] = "要到幾時呢？";
  Sentence[2879] = "他們彼此商議，";
  Sentence[2880] = "專要從他的尊位上把他推下；";
  Sentence[2881] = "他們喜愛謊話，";
  Sentence[2882] = "口雖祝福，";
  Sentence[2883] = "心卻咒詛。";
  Sentence[2884] = "我的心哪，";
  Sentence[2885] = "你當默默無聲，";
  Sentence[2886] = "專等候神，";
  Sentence[2887] = "因為我的盼望是從他而來。";
  Sentence[2888] = "惟獨他是我的磐石，";
  Sentence[2889] = "我的拯救；";
  Sentence[2890] = "他是我的高臺，";
  Sentence[2891] = "我必不動搖。";
  Sentence[2892] = "我的拯救、";
  Sentence[2893] = "我的榮耀都在乎神；";
  Sentence[2894] = "我力量的磐石、";
  Sentence[2895] = "我的避難所都在乎神。";
  Sentence[2896] = "你們眾民當時時倚靠他，";
  Sentence[2897] = "在他面前傾心吐意；";
  Sentence[2898] = "神是我們的避難所。";
  Sentence[2899] = "下流人真是虛空；";
  Sentence[2900] = "上流人也是虛假；";
  Sentence[2901] = "放在天平裡就必浮起；";
  Sentence[2902] = "他們一共比空氣還輕。";
  Sentence[2903] = "不要仗勢欺人，";
  Sentence[2904] = "也不要因搶奪而驕傲；";
  Sentence[2905] = "若財寶加增，";
  Sentence[2906] = "不要放在心上。";
  Sentence[2907] = "神說了一次、";
  Sentence[2908] = "兩次，";
  Sentence[2909] = "我都聽見：";
  Sentence[2910] = "就是能力都屬乎神。";
  Sentence[2911] = "主啊，";
  Sentence[2912] = "慈愛也是屬乎你，";
  Sentence[2913] = "因為你照著各人所行的報應他。";
  Sentence[2914] = "詩篇六十三篇";
  Sentence[2915] = "神啊，";
  Sentence[2916] = "你是我的神，";
  Sentence[2917] = "我要切切地尋求你，";
  Sentence[2918] = "在乾旱疲乏無水之地，";
  Sentence[2919] = "我渴想你；";
  Sentence[2920] = "我的心切慕你。";
  Sentence[2921] = "我在聖所中曾如此瞻仰你，";
  Sentence[2922] = "為要見你的能力和你的榮耀。";
  Sentence[2923] = "因你的慈愛比生命更好，";
  Sentence[2924] = "我的嘴唇要頌讚你。";
  Sentence[2925] = "我還活的時候要這樣稱頌你；";
  Sentence[2926] = "我要奉你的名舉手。";
  Sentence[2927] = "我在床上記念你，";
  Sentence[2928] = "在夜更的時候思想你；";
  Sentence[2929] = "我的心就像飽足了骨髓肥油，";
  Sentence[2930] = "我也要以歡樂的嘴唇讚美你。";
  Sentence[2931] = "因為你曾幫助我，";
  Sentence[2932] = "我就在你翅膀的蔭下歡呼。";
  Sentence[2933] = "我心緊緊地跟隨你；";
  Sentence[2934] = "你的右手扶持我。";
  Sentence[2935] = "但那些尋索要滅我命的人必往地底下去；";
  Sentence[2936] = "他們必被刀劍所殺，";
  Sentence[2937] = "被野狗所吃。";
  Sentence[2938] = "但是王必因神歡喜。";
  Sentence[2939] = "凡指著他發誓的必要誇口，";
  Sentence[2940] = "因為說謊之人的口必被塞住。";
  Sentence[2941] = "詩篇六十四篇";
  Sentence[2942] = "神啊，";
  Sentence[2943] = "我哀歎的時候，";
  Sentence[2944] = "求你聽我的聲音！";
  Sentence[2945] = "求你保護我的性命，";
  Sentence[2946] = "不受仇敵的驚恐！";
  Sentence[2947] = "求你把我隱藏，";
  Sentence[2948] = "使我脫離作惡之人的暗謀和作孽之人的擾亂。";
  Sentence[2949] = "他們磨舌如刀，";
  Sentence[2950] = "發出苦毒的言語，";
  Sentence[2951] = "好像比準了的箭，";
  Sentence[2952] = "要在暗地射完全人；";
  Sentence[2953] = "他們忽然射他，";
  Sentence[2954] = "並不懼怕。";
  Sentence[2955] = "他們彼此勉勵設下惡計；";
  Sentence[2956] = "他們商量暗設網羅，";
  Sentence[2957] = "說：";
  Sentence[2958] = "誰能看見？";
  Sentence[2959] = "他們圖謀奸惡，";
  Sentence[2960] = "說：";
  Sentence[2961] = "我們是極力圖謀的。";
  Sentence[2962] = "他們各人的意念心思是深的。";
  Sentence[2963] = "但神要射他們；";
  Sentence[2964] = "他們忽然被箭射傷。";
  Sentence[2965] = "他們必然絆跌，";
  Sentence[2966] = "被自己的舌頭所害；";
  Sentence[2967] = "凡看見他們的必都搖頭。";
  Sentence[2968] = "眾人都要害怕，";
  Sentence[2969] = "要傳揚神的工作，";
  Sentence[2970] = "並且明白他的作為。";
  Sentence[2971] = "義人必因耶和華歡喜，";
  Sentence[2972] = "並要投靠他；";
  Sentence[2973] = "凡心裡正直的人都要誇口。";
  Sentence[2974] = "詩篇六十五篇";
  Sentence[2975] = "神啊，";
  Sentence[2976] = "錫安的人都等候讚美你；";
  Sentence[2977] = "所許的願也要向你償還。";
  Sentence[2978] = "聽禱告的主啊，";
  Sentence[2979] = "凡有血氣的都要來就你。";
  Sentence[2980] = "罪孽勝了我；";
  Sentence[2981] = "至於我們的過犯，";
  Sentence[2982] = "你都要赦免。";
  Sentence[2983] = "你所揀選、";
  Sentence[2984] = "使他親近你、";
  Sentence[2985] = "住在你院中的，";
  Sentence[2986] = "這人便為有福！";
  Sentence[2987] = "我們必因你居所、";
  Sentence[2988] = "你聖殿的美福知足了。";
  Sentence[2989] = "拯救我們的神啊，";
  Sentence[2990] = "你必以威嚴秉公義應允我們；";
  Sentence[2991] = "你本是一切地極和海上遠處的人所倚靠的。";
  Sentence[2992] = "他既以大能束腰，";
  Sentence[2993] = "就用力量安定諸山，";
  Sentence[2994] = "使諸海的響聲和其中波浪的響聲，";
  Sentence[2995] = "並萬民的喧嘩，";
  Sentence[2996] = "都平靜了。";
  Sentence[2997] = "住在地極的人因你的神蹟懼怕；";
  Sentence[2998] = "你使日出日落之地都歡呼。";
  Sentence[2999] = "你眷顧地，";
  Sentence[3000] = "降下透雨，";
  Sentence[3001] = "使地大得肥美。";
  Sentence[3002] = "神的河滿了水；";
  Sentence[3003] = "你這樣澆灌了地，";
  Sentence[3004] = "好為人預備五穀。";
  Sentence[3005] = "你澆透地的犁溝，";
  Sentence[3006] = "潤平犁脊，";
  Sentence[3007] = "降甘霖，";
  Sentence[3008] = "使地軟和；";
  Sentence[3009] = "其中發長的，";
  Sentence[3010] = "蒙你賜福。";
  Sentence[3011] = "你以恩典為年歲的冠冕；";
  Sentence[3012] = "你的路徑都滴下脂油，";
  Sentence[3013] = "滴在曠野的草場上。";
  Sentence[3014] = "小山以歡樂束腰；";
  Sentence[3015] = "草場以羊群為衣；";
  Sentence[3016] = "谷中也長滿了五穀。";
  Sentence[3017] = "這一切都歡呼歌唱。";
  Sentence[3018] = "詩篇六十六篇";
  Sentence[3019] = "全地都當向神歡呼！";
  Sentence[3020] = "歌頌他名的榮耀！";
  Sentence[3021] = "用讚美的言語將他的榮耀發明！";
  Sentence[3022] = "當對神說：";
  Sentence[3023] = "你的作為何等可畏！";
  Sentence[3024] = "因你的大能，";
  Sentence[3025] = "仇敵要投降你。";
  Sentence[3026] = "全地要敬拜你，";
  Sentence[3027] = "歌頌你，";
  Sentence[3028] = "要歌頌你的名。";
  Sentence[3029] = "你們來看神所行的，";
  Sentence[3030] = "他向世人所做之事是可畏的。";
  Sentence[3031] = "他將海變成乾地，";
  Sentence[3032] = "眾民步行過河；";
  Sentence[3033] = "我們在那裡因他歡喜。";
  Sentence[3034] = "他用權能治理萬民，";
  Sentence[3035] = "直到永遠。";
  Sentence[3036] = "他的眼睛鑒察列邦；";
  Sentence[3037] = "悖逆的人不可自高。";
  Sentence[3038] = "萬民哪，";
  Sentence[3039] = "你們當稱頌我們的神，";
  Sentence[3040] = "使人得聽讚美他的聲音。";
  Sentence[3041] = "他使我們的性命存活，";
  Sentence[3042] = "也不叫我們的腳搖動。";
  Sentence[3043] = "神啊，";
  Sentence[3044] = "你曾試驗我們，";
  Sentence[3045] = "熬煉我們，";
  Sentence[3046] = "如熬煉銀子一樣。";
  Sentence[3047] = "你使我們進入網羅，";
  Sentence[3048] = "把重擔放在我們的身上。";
  Sentence[3049] = "你使人坐車軋我們的頭；";
  Sentence[3050] = "我們經過水火，";
  Sentence[3051] = "你卻使我們到豐富之地。";
  Sentence[3052] = "我要用燔祭進你的殿，";
  Sentence[3053] = "向你還我的願，";
  Sentence[3054] = "就是在急難時我嘴唇所發的、";
  Sentence[3055] = "口中所許的。";
  Sentence[3056] = "我要把肥牛作燔祭，";
  Sentence[3057] = "將公羊的香祭獻給你，";
  Sentence[3058] = "又把公牛和山羊獻上。";
  Sentence[3059] = "凡敬畏神的人，";
  Sentence[3060] = "你們都來聽！";
  Sentence[3061] = "我要述說他為我所行的事。";
  Sentence[3062] = "我曾用口求告他；";
  Sentence[3063] = "我的舌頭也稱他為高。";
  Sentence[3064] = "我若心裡注重罪孽，";
  Sentence[3065] = "主必不聽。";
  Sentence[3066] = "但神實在聽見了；";
  Sentence[3067] = "他側耳聽了我禱告的聲音。";
  Sentence[3068] = "神是應當稱頌的！";
  Sentence[3069] = "他並沒有推卻我的禱告，";
  Sentence[3070] = "也沒有叫他的慈愛離開我。";
  Sentence[3071] = "詩篇六十七篇";
  Sentence[3072] = "願神憐憫我們，";
  Sentence[3073] = "賜福與我們，";
  Sentence[3074] = "用臉光照我們，";
  Sentence[3075] = "好叫世界得知你的道路，";
  Sentence[3076] = "萬國得知你的救恩。";
  Sentence[3077] = "神啊，";
  Sentence[3078] = "願列邦稱讚你！";
  Sentence[3079] = "願萬民都稱讚你！";
  Sentence[3080] = "願萬國都快樂歡呼；";
  Sentence[3081] = "因為你必按公正審判萬民，";
  Sentence[3082] = "引導世上的萬國。";
  Sentence[3083] = "神啊，";
  Sentence[3084] = "願列邦稱讚你！";
  Sentence[3085] = "願萬民都稱讚你！";
  Sentence[3086] = "地已經出了土產；";
  Sentence[3087] = "神－";
  Sentence[3088] = "就是我們的神要賜福與我們。";
  Sentence[3089] = "神要賜福與我們；";
  Sentence[3090] = "地的四極都要敬畏他！";
  Sentence[3091] = "詩篇六十八篇";
  Sentence[3092] = "願神興起，";
  Sentence[3093] = "使他的仇敵四散，";
  Sentence[3094] = "叫那恨他的人從他面前逃跑。";
  Sentence[3095] = "他們被驅逐，";
  Sentence[3096] = "如煙被風吹散；";
  Sentence[3097] = "惡人見神之面而消滅，";
  Sentence[3098] = "如蠟被火鎔化。";
  Sentence[3099] = "惟有義人必然歡喜，";
  Sentence[3100] = "在神面前高興快樂。";
  Sentence[3101] = "你們當向神唱詩，";
  Sentence[3102] = "歌頌他的名；";
  Sentence[3103] = "為那坐車行過曠野的修平大路。";
  Sentence[3104] = "他的名是耶和華，";
  Sentence[3105] = "要在他面前歡樂！";
  Sentence[3106] = "神在他的聖所作孤兒的父，";
  Sentence[3107] = "作寡婦的伸冤者。";
  Sentence[3108] = "神叫孤獨的有家，";
  Sentence[3109] = "使被囚的出來享福；";
  Sentence[3110] = "惟有悖逆的住在乾燥之地。";
  Sentence[3111] = "神啊，";
  Sentence[3112] = "你曾在你百姓前頭出來，";
  Sentence[3113] = "在曠野行走。";
  Sentence[3114] = "那時，";
  Sentence[3115] = "地見神的面而震動，";
  Sentence[3116] = "天也落雨；";
  Sentence[3117] = "西乃山見以色列神的面也震動。";
  Sentence[3118] = "神啊，";
  Sentence[3119] = "你降下大雨；";
  Sentence[3120] = "你產業以色列疲乏的時候，";
  Sentence[3121] = "你使他堅固。";
  Sentence[3122] = "你的會眾住在其中；";
  Sentence[3123] = "神啊，";
  Sentence[3124] = "你的恩惠是為困苦人預備的。";
  Sentence[3125] = "主發命令，";
  Sentence[3126] = "傳好信息的婦女成了大群。";
  Sentence[3127] = "統兵的君王逃跑了，";
  Sentence[3128] = "逃跑了；";
  Sentence[3129] = "在家等候的婦女分受所奪的。";
  Sentence[3130] = "你們安臥在羊圈的時候，";
  Sentence[3131] = "好像鴿子的翅膀鍍白銀，";
  Sentence[3132] = "翎毛鍍黃金一般。";
  Sentence[3133] = "全能者在境內趕散列王的時候，";
  Sentence[3134] = "勢如飄雪在撒們。";
  Sentence[3135] = "巴珊山是神的山；";
  Sentence[3136] = "巴珊山是多峯多嶺的山。";
  Sentence[3137] = "你們多峯多嶺的山哪，";
  Sentence[3138] = "為何斜看神所願居住的山？";
  Sentence[3139] = "耶和華必住這山，";
  Sentence[3140] = "直到永遠！";
  Sentence[3141] = "神的車輦累萬盈千；";
  Sentence[3142] = "主在其中，";
  Sentence[3143] = "好像在西乃聖山一樣。";
  Sentence[3144] = "你已經升上高天，";
  Sentence[3145] = "擄掠仇敵；";
  Sentence[3146] = "你在人間，";
  Sentence[3147] = "就是在悖逆的人間，";
  Sentence[3148] = "受了供獻，";
  Sentence[3149] = "叫耶和華神可以與他們同住。";
  Sentence[3150] = "天天背負我們重擔的主，";
  Sentence[3151] = "就是拯救我們的神，";
  Sentence[3152] = "是應當稱頌的！";
  Sentence[3153] = "神是為我們施行諸般救恩的神；";
  Sentence[3154] = "人能脫離死亡是在乎主耶和華。";
  Sentence[3155] = "但神要打破他仇敵的頭，";
  Sentence[3156] = "就是那常犯罪之人的髮頂。";
  Sentence[3157] = "主說：";
  Sentence[3158] = "我要使眾民從巴珊而歸，";
  Sentence[3159] = "使他們從深海而回，";
  Sentence[3160] = "使你打碎仇敵，";
  Sentence[3161] = "你的腳踹在血中，";
  Sentence[3162] = "使你狗的舌頭從其中得分。";
  Sentence[3163] = "神啊，";
  Sentence[3164] = "你是我的神，";
  Sentence[3165] = "我的王；";
  Sentence[3166] = "人已經看見你行走，";
  Sentence[3167] = "進入聖所。";
  Sentence[3168] = "歌唱的行在前，";
  Sentence[3169] = "作樂的隨在後，";
  Sentence[3170] = "都在擊鼓的童女中間。";
  Sentence[3171] = "從以色列源頭而來的，";
  Sentence[3172] = "當在各會中稱頌主神！";
  Sentence[3173] = "在那裡，";
  Sentence[3174] = "有統管他們的小便雅憫，";
  Sentence[3175] = "有猶大的首領和他們的群眾，";
  Sentence[3176] = "有西布倫的首領，";
  Sentence[3177] = "有拿弗他利的首領。";
  Sentence[3178] = "以色列的能力是神所賜的；";
  Sentence[3179] = "神啊，";
  Sentence[3180] = "求你堅固你為我們所成全的事！";
  Sentence[3181] = "因你耶路撒冷的殿，";
  Sentence[3182] = "列王必帶貢物獻給你。";
  Sentence[3183] = "求你叱喝蘆葦中的野獸和群公牛，";
  Sentence[3184] = "並列邦中的牛犢。";
  Sentence[3185] = "把銀塊踹在腳下；";
  Sentence[3186] = "神已經趕散好爭戰的列邦。";
  Sentence[3187] = "埃及的公侯要出來朝見神；";
  Sentence[3188] = "古實人要急忙舉手禱告。";
  Sentence[3189] = "世上的列國啊，";
  Sentence[3190] = "你們要向神歌唱；";
  Sentence[3191] = "願你們歌頌主！";
  Sentence[3192] = "歌頌那自古駕行在諸天以上的主！";
  Sentence[3193] = "他發出聲音，";
  Sentence[3194] = "是極大的聲音。";
  Sentence[3195] = "你們要將能力歸給神。";
  Sentence[3196] = "他的威榮在以色列之上；";
  Sentence[3197] = "他的能力是在穹蒼。";
  Sentence[3198] = "神啊，";
  Sentence[3199] = "你從聖所顯為可畏；";
  Sentence[3200] = "以色列的神是那將力量權能賜給他百姓的。";
  Sentence[3201] = "神是應當稱頌的！";
  Sentence[3202] = "詩篇六十九篇";
  Sentence[3203] = "神啊，";
  Sentence[3204] = "求你救我！";
  Sentence[3205] = "因為眾水要淹沒我。";
  Sentence[3206] = "我陷在深淤泥中，";
  Sentence[3207] = "沒有立腳之地；";
  Sentence[3208] = "我到了深水中，";
  Sentence[3209] = "大水漫過我身。";
  Sentence[3210] = "我因呼求困乏，";
  Sentence[3211] = "喉嚨發乾；";
  Sentence[3212] = "我因等候神，";
  Sentence[3213] = "眼睛失明。";
  Sentence[3214] = "無故恨我的，";
  Sentence[3215] = "比我頭髮還多；";
  Sentence[3216] = "無理與我為仇、";
  Sentence[3217] = "要把我剪除的，";
  Sentence[3218] = "甚為強盛。";
  Sentence[3219] = "我沒有搶奪的，";
  Sentence[3220] = "要叫我償還。";
  Sentence[3221] = "神啊，";
  Sentence[3222] = "我的愚昧，";
  Sentence[3223] = "你原知道；";
  Sentence[3224] = "我的罪愆不能隱瞞。";
  Sentence[3225] = "萬軍的主－";
  Sentence[3226] = "耶和華啊，";
  Sentence[3227] = "求你叫那等候你的，";
  Sentence[3228] = "不要因我蒙羞！";
  Sentence[3229] = "以色列的神啊，";
  Sentence[3230] = "求你叫那尋求你的，";
  Sentence[3231] = "不要因我受辱！";
  Sentence[3232] = "因我為你的緣故受了辱罵，";
  Sentence[3233] = "滿面羞愧。";
  Sentence[3234] = "我的弟兄看我為外路人；";
  Sentence[3235] = "我的同胞看我為外邦人。";
  Sentence[3236] = "因我為你的殿心裡焦急，";
  Sentence[3237] = "如同火燒，";
  Sentence[3238] = "並且辱罵你人的辱罵都落在我身上。";
  Sentence[3239] = "我哭泣，";
  Sentence[3240] = "以禁食刻苦我心；";
  Sentence[3241] = "這倒算為我的羞辱。";
  Sentence[3242] = "我拿麻布當衣裳，";
  Sentence[3243] = "就成了他們的笑談。";
  Sentence[3244] = "坐在城門口的談論我；";
  Sentence[3245] = "酒徒也以我為歌曲。";
  Sentence[3246] = "但我在悅納的時候向你－";
  Sentence[3247] = "耶和華祈禱。";
  Sentence[3248] = "神啊，";
  Sentence[3249] = "求你按你豐盛的慈愛，";
  Sentence[3250] = "憑你拯救的誠實應允我！";
  Sentence[3251] = "求你搭救我出離淤泥，";
  Sentence[3252] = "不叫我陷在其中；";
  Sentence[3253] = "求你使我脫離那些恨我的人，";
  Sentence[3254] = "使我出離深水。";
  Sentence[3255] = "求你不容大水漫過我，";
  Sentence[3256] = "不容深淵吞滅我，";
  Sentence[3257] = "不容坑坎在我以上合口。";
  Sentence[3258] = "耶和華啊，";
  Sentence[3259] = "求你應允我！";
  Sentence[3260] = "因為你的慈愛本為美好；";
  Sentence[3261] = "求你按你豐盛的慈悲回轉眷顧我！";
  Sentence[3262] = "不要掩面不顧你的僕人；";
  Sentence[3263] = "我是在急難之中，";
  Sentence[3264] = "求你速速地應允我！";
  Sentence[3265] = "求你親近我，";
  Sentence[3266] = "救贖我！";
  Sentence[3267] = "求你因我的仇敵把我贖回！";
  Sentence[3268] = "你知道我受的辱罵、";
  Sentence[3269] = "欺凌、";
  Sentence[3270] = "羞辱；";
  Sentence[3271] = "我的敵人都在你面前。";
  Sentence[3272] = "辱罵傷破了我的心，";
  Sentence[3273] = "我又滿了憂愁。";
  Sentence[3274] = "我指望有人體恤，";
  Sentence[3275] = "卻沒有一個；";
  Sentence[3276] = "我指望有人安慰，";
  Sentence[3277] = "卻找不著一個。";
  Sentence[3278] = "他們拿苦膽給我當食物；";
  Sentence[3279] = "我渴了，";
  Sentence[3280] = "他們拿醋給我喝。";
  Sentence[3281] = "願他們的筵席在他們面前變為網羅，";
  Sentence[3282] = "在他們平安的時候變為機檻。";
  Sentence[3283] = "願他們的眼睛昏矇，";
  Sentence[3284] = "不得看見；";
  Sentence[3285] = "願你使他們的腰常常戰抖。";
  Sentence[3286] = "求你將你的惱恨倒在他們身上，";
  Sentence[3287] = "叫你的烈怒追上他們。";
  Sentence[3288] = "願他們的住處變為荒場；";
  Sentence[3289] = "願他們的帳棚無人居住。";
  Sentence[3290] = "因為，";
  Sentence[3291] = "你所擊打的，";
  Sentence[3292] = "他們就逼迫；";
  Sentence[3293] = "你所擊傷的，";
  Sentence[3294] = "他們戲說他的愁苦。";
  Sentence[3295] = "願你在他們的罪上加罪，";
  Sentence[3296] = "不容他們在你面前稱義。";
  Sentence[3297] = "願他們從生命冊上被塗抹，";
  Sentence[3298] = "不得記錄在義人之中。";
  Sentence[3299] = "但我是困苦憂傷的；";
  Sentence[3300] = "神啊，";
  Sentence[3301] = "願你的救恩將我安置在高處。";
  Sentence[3302] = "我要以詩歌讚美神的名，";
  Sentence[3303] = "以感謝稱他為大！";
  Sentence[3304] = "這便叫耶和華喜悅，";
  Sentence[3305] = "勝似獻牛，";
  Sentence[3306] = "或是獻有角有蹄的公牛。";
  Sentence[3307] = "謙卑的人看見了就喜樂；";
  Sentence[3308] = "尋求神的人，";
  Sentence[3309] = "願你們的心甦醒。";
  Sentence[3310] = "因為耶和華聽了窮乏人，";
  Sentence[3311] = "不藐視被囚的人。";
  Sentence[3312] = "願天和地、";
  Sentence[3313] = "洋海和其中一切的動物都讚美他！";
  Sentence[3314] = "因為神要拯救錫安，";
  Sentence[3315] = "建造猶大的城邑；";
  Sentence[3316] = "他的民要在那裡居住，";
  Sentence[3317] = "得以為業。";
  Sentence[3318] = "他僕人的後裔要承受為業；";
  Sentence[3319] = "愛他名的人也要住在其中。";
  Sentence[3320] = "詩篇七十篇";
  Sentence[3321] = "神啊，";
  Sentence[3322] = "求你快快搭救我！";
  Sentence[3323] = "耶和華啊，";
  Sentence[3324] = "求你速速幫助我！";
  Sentence[3325] = "願那些尋索我命的，";
  Sentence[3326] = "抱愧蒙羞；";
  Sentence[3327] = "願那些喜悅我遭害的，";
  Sentence[3328] = "退後受辱。";
  Sentence[3329] = "願那些對我說阿哈、";
  Sentence[3330] = "阿哈的，";
  Sentence[3331] = "因羞愧退後。";
  Sentence[3332] = "願一切尋求你的，";
  Sentence[3333] = "因你高興歡喜；";
  Sentence[3334] = "願那些喜愛你救恩的，";
  Sentence[3335] = "常說：";
  Sentence[3336] = "當尊神為大！";
  Sentence[3337] = "但我是困苦窮乏的；";
  Sentence[3338] = "神啊，";
  Sentence[3339] = "求你速速到我這裡來！";
  Sentence[3340] = "你是幫助我的，";
  Sentence[3341] = "搭救我的。";
  Sentence[3342] = "耶和華啊，";
  Sentence[3343] = "求你不要耽延！";
  Sentence[3344] = "詩篇七十一篇";
  Sentence[3345] = "耶和華啊，";
  Sentence[3346] = "我投靠你；";
  Sentence[3347] = "求你叫我永不羞愧！";
  Sentence[3348] = "求你憑你的公義搭救我，";
  Sentence[3349] = "救拔我；";
  Sentence[3350] = "側耳聽我，";
  Sentence[3351] = "拯救我！";
  Sentence[3352] = "求你作我常住的磐石；";
  Sentence[3353] = "你已經命定要救我，";
  Sentence[3354] = "因為你是我的巖石，";
  Sentence[3355] = "我的山寨。";
  Sentence[3356] = "我的神啊，";
  Sentence[3357] = "求你救我脫離惡人的手，";
  Sentence[3358] = "脫離不義和殘暴之人的手。";
  Sentence[3359] = "主－";
  Sentence[3360] = "耶和華啊，";
  Sentence[3361] = "你是我所盼望的；";
  Sentence[3362] = "從我年幼，";
  Sentence[3363] = "你是我所倚靠的。";
  Sentence[3364] = "我從出母胎被你扶持；";
  Sentence[3365] = "使我出母腹的是你。";
  Sentence[3366] = "我必常常讚美你！";
  Sentence[3367] = "許多人以我為怪，";
  Sentence[3368] = "但你是我堅固的避難所。";
  Sentence[3369] = "你的讚美，";
  Sentence[3370] = "你的榮耀終日必滿了我的口。";
  Sentence[3371] = "我年老的時候，";
  Sentence[3372] = "求你不要丟棄我！";
  Sentence[3373] = "我力氣衰弱的時候，";
  Sentence[3374] = "求你不要離棄我！";
  Sentence[3375] = "我的仇敵議論我；";
  Sentence[3376] = "那些窺探要害我命的彼此商議，";
  Sentence[3377] = "說：";
  Sentence[3378] = "神已經離棄他；";
  Sentence[3379] = "我們追趕他，";
  Sentence[3380] = "捉拿他吧！";
  Sentence[3381] = "因為沒有人搭救。";
  Sentence[3382] = "神啊，";
  Sentence[3383] = "求你不要遠離我！";
  Sentence[3384] = "我的神啊，";
  Sentence[3385] = "求你速速幫助我！";
  Sentence[3386] = "願那與我性命為敵的，";
  Sentence[3387] = "羞愧被滅；";
  Sentence[3388] = "願那謀害我的，";
  Sentence[3389] = "受辱蒙羞。";
  Sentence[3390] = "我卻要常常盼望，";
  Sentence[3391] = "並要越發讚美你。";
  Sentence[3392] = "我的口終日要述說你的公義和你的救恩，";
  Sentence[3393] = "因我不計其數。";
  Sentence[3394] = "我要來說主－";
  Sentence[3395] = "耶和華大能的事；";
  Sentence[3396] = "我單要提說你的公義。";
  Sentence[3397] = "神啊，";
  Sentence[3398] = "自我年幼時，";
  Sentence[3399] = "你就教訓我；";
  Sentence[3400] = "直到如今，";
  Sentence[3401] = "我傳揚你奇妙的作為。";
  Sentence[3402] = "神啊，";
  Sentence[3403] = "我到年老髮白的時候，";
  Sentence[3404] = "求你不要離棄我！";
  Sentence[3405] = "等我將你的能力指示下代，";
  Sentence[3406] = "將你的大能指示後世的人。";
  Sentence[3407] = "神啊，";
  Sentence[3408] = "你的公義甚高；";
  Sentence[3409] = "行過大事的神啊，";
  Sentence[3410] = "誰能像你！";
  Sentence[3411] = "你是叫我們多經歷重大急難的，";
  Sentence[3412] = "必使我們復活，";
  Sentence[3413] = "從地的深處救上來。";
  Sentence[3414] = "求你使我越發昌大，";
  Sentence[3415] = "又轉來安慰我。";
  Sentence[3416] = "我的神啊，";
  Sentence[3417] = "我要鼓瑟稱讚你，";
  Sentence[3418] = "稱讚你的誠實！";
  Sentence[3419] = "以色列的聖者啊，";
  Sentence[3420] = "我要彈琴歌頌你！";
  Sentence[3421] = "我歌頌你的時候，";
  Sentence[3422] = "我的嘴唇和你所贖我的靈魂都必歡呼；";
  Sentence[3423] = "並且我的舌頭必終日講論你的公義，";
  Sentence[3424] = "因為那些謀害我的人已經蒙羞受辱了。";
  Sentence[3425] = "詩篇七十二篇";
  Sentence[3426] = "神啊，";
  Sentence[3427] = "求你將判斷的權柄賜給王，";
  Sentence[3428] = "將公義賜給王的兒子。";
  Sentence[3429] = "他要按公義審判你的民，";
  Sentence[3430] = "按公平審判你的困苦人。";
  Sentence[3431] = "大山小山都要因公義使民得享平安。";
  Sentence[3432] = "他必為民中的困苦人伸冤，";
  Sentence[3433] = "拯救窮乏之輩，";
  Sentence[3434] = "壓碎那欺壓人的。";
  Sentence[3435] = "太陽還存，";
  Sentence[3436] = "月亮還在，";
  Sentence[3437] = "人要敬畏你，";
  Sentence[3438] = "直到萬代！";
  Sentence[3439] = "他必降臨，";
  Sentence[3440] = "像雨降在已割的草地上，";
  Sentence[3441] = "如甘霖滋潤田地。";
  Sentence[3442] = "在他的日子，";
  Sentence[3443] = "義人要發旺，";
  Sentence[3444] = "大有平安，";
  Sentence[3445] = "好像月亮長存。";
  Sentence[3446] = "他要執掌權柄，";
  Sentence[3447] = "從這海直到那海，";
  Sentence[3448] = "從大河直到地極。";
  Sentence[3449] = "住在曠野的，";
  Sentence[3450] = "必在他面前下拜；";
  Sentence[3451] = "他的仇敵必要舔土。";
  Sentence[3452] = "他施和海島的王要進貢；";
  Sentence[3453] = "示巴和西巴的王要獻禮物。";
  Sentence[3454] = "諸王都要叩拜他；";
  Sentence[3455] = "萬國都要事奉他。";
  Sentence[3456] = "因為，";
  Sentence[3457] = "窮乏人呼求的時候，";
  Sentence[3458] = "他要搭救；";
  Sentence[3459] = "沒有人幫助的困苦人，";
  Sentence[3460] = "他也要搭救。";
  Sentence[3461] = "他要憐恤貧寒和窮乏的人，";
  Sentence[3462] = "拯救窮苦人的性命。";
  Sentence[3463] = "他要救贖他們脫離欺壓和強暴；";
  Sentence[3464] = "他們的血在他眼中看為寶貴。";
  Sentence[3465] = "他們要存活。";
  Sentence[3466] = "示巴的金子要奉給他；";
  Sentence[3467] = "人要常常為他禱告，";
  Sentence[3468] = "終日稱頌他。";
  Sentence[3469] = "在地的山頂上，";
  Sentence[3470] = "五穀必然茂盛；";
  Sentence[3471] = "所結的穀實要響動，";
  Sentence[3472] = "如利巴嫩的樹林；";
  Sentence[3473] = "城裡的人要發旺，";
  Sentence[3474] = "如地上的草。";
  Sentence[3475] = "他的名要存到永遠，";
  Sentence[3476] = "要留傳如日之久。";
  Sentence[3477] = "人要因他蒙福；";
  Sentence[3478] = "萬國要稱他有福。";
  Sentence[3479] = "獨行奇事的耶和華－";
  Sentence[3480] = "以色列的神是應當稱頌的！";
  Sentence[3481] = "他榮耀的名也當稱頌，";
  Sentence[3482] = "直到永遠。";
  Sentence[3483] = "願他的榮耀充滿全地！";
  Sentence[3484] = "阿們！";
  Sentence[3485] = "阿們！";
  Sentence[3486] = "耶西的兒子－";
  Sentence[3487] = "大衛的祈禱完畢。";
  Sentence[3488] = "詩篇七十三篇";
  Sentence[3489] = "神實在恩待以色列那些清心的人！";
  Sentence[3490] = "至於我，";
  Sentence[3491] = "我的腳幾乎失閃；";
  Sentence[3492] = "我的腳險些滑跌。";
  Sentence[3493] = "我見惡人和狂傲人享平安就心懷不平。";
  Sentence[3494] = "他們死的時候沒有疼痛；";
  Sentence[3495] = "他們的力氣卻也壯實。";
  Sentence[3496] = "他們不像別人受苦，";
  Sentence[3497] = "也不像別人遭災。";
  Sentence[3498] = "所以，";
  Sentence[3499] = "驕傲如鏈子戴在他們的項上；";
  Sentence[3500] = "強暴像衣裳遮住他們的身體。";
  Sentence[3501] = "他們的眼睛因體胖而凸出；";
  Sentence[3502] = "他們所得的，";
  Sentence[3503] = "過於心裡所想的。";
  Sentence[3504] = "他們譏笑人，";
  Sentence[3505] = "憑惡意說欺壓人的話；";
  Sentence[3506] = "他們說話自高。";
  Sentence[3507] = "他們的口褻瀆上天；";
  Sentence[3508] = "他們的舌毀謗全地。";
  Sentence[3509] = "所以神的民歸到這裡，";
  Sentence[3510] = "喝盡了滿杯的苦水。";
  Sentence[3511] = "他們說：";
  Sentence[3512] = "神怎能曉得？";
  Sentence[3513] = "至高者豈有知識呢？";
  Sentence[3514] = "看哪，";
  Sentence[3515] = "這就是惡人；";
  Sentence[3516] = "他們既是常享安逸，";
  Sentence[3517] = "財寶便加增。";
  Sentence[3518] = "我實在徒然潔淨了我的心，";
  Sentence[3519] = "徒然洗手表明無辜。";
  Sentence[3520] = "因為，";
  Sentence[3521] = "我終日遭災難；";
  Sentence[3522] = "每早晨受懲治。";
  Sentence[3523] = "我若說，";
  Sentence[3524] = "我要這樣講，";
  Sentence[3525] = "這就是以奸詐待你的眾子。";
  Sentence[3526] = "我思索怎能明白這事，";
  Sentence[3527] = "眼看實係為難，";
  Sentence[3528] = "等我進了神的聖所，";
  Sentence[3529] = "思想他們的結局。";
  Sentence[3530] = "你實在把他們安在滑地，";
  Sentence[3531] = "使他們掉在沉淪之中。";
  Sentence[3532] = "他們轉眼之間成了何等的荒涼！";
  Sentence[3533] = "他們被驚恐滅盡了。";
  Sentence[3534] = "人睡醒了，";
  Sentence[3535] = "怎樣看夢；";
  Sentence[3536] = "主啊，";
  Sentence[3537] = "你醒了也必照樣輕看他們的影像。";
  Sentence[3538] = "因而，";
  Sentence[3539] = "我心裡發酸，";
  Sentence[3540] = "肺腑被刺。";
  Sentence[3541] = "我這樣愚昧無知，";
  Sentence[3542] = "在你面前如畜類一般。";
  Sentence[3543] = "然而，";
  Sentence[3544] = "我常與你同在；";
  Sentence[3545] = "你攙著我的右手。";
  Sentence[3546] = "你要以你的訓言引導我，";
  Sentence[3547] = "以後必接我到榮耀裡。";
  Sentence[3548] = "除你以外，";
  Sentence[3549] = "在天上我有誰呢？";
  Sentence[3550] = "除你以外，";
  Sentence[3551] = "在地上我也沒有所愛慕的。";
  Sentence[3552] = "我的肉體和我的心腸衰殘；";
  Sentence[3553] = "但神是我心裡的力量，";
  Sentence[3554] = "又是我的福分，";
  Sentence[3555] = "直到永遠。";
  Sentence[3556] = "遠離你的，";
  Sentence[3557] = "必要死亡；";
  Sentence[3558] = "凡離棄你行邪淫的，";
  Sentence[3559] = "你都滅絕了。";
  Sentence[3560] = "但我親近神是於我有益；";
  Sentence[3561] = "我以主耶和華為我的避難所，";
  Sentence[3562] = "好叫我述說你一切的作為。";
  Sentence[3563] = "詩篇七十四篇";
  Sentence[3564] = "神啊，";
  Sentence[3565] = "你為何永遠丟棄我們呢？";
  Sentence[3566] = "你為何向你草場的羊發怒，";
  Sentence[3567] = "如煙冒出呢？";
  Sentence[3568] = "求你記念你古時所得來的會眾，";
  Sentence[3569] = "就是你所贖、";
  Sentence[3570] = "作你產業支派的，";
  Sentence[3571] = "並記念你向來所居住的錫安山。";
  Sentence[3572] = "求你舉步去看那日久荒涼之地，";
  Sentence[3573] = "仇敵在聖所中所行的一切惡事。";
  Sentence[3574] = "你的敵人在你會中吼叫；";
  Sentence[3575] = "他們豎了自己的旗為記號。";
  Sentence[3576] = "他們好像人揚起斧子，";
  Sentence[3577] = "砍伐林中的樹。";
  Sentence[3578] = "聖所中一切雕刻的，";
  Sentence[3579] = "他們現在用斧子錘子打壞了。";
  Sentence[3580] = "他們用火焚燒你的聖所，";
  Sentence[3581] = "褻瀆你名的居所，";
  Sentence[3582] = "拆毀到地。";
  Sentence[3583] = "他們心裡說：";
  Sentence[3584] = "我們要盡行毀滅；";
  Sentence[3585] = "他們就在遍地把神的會所都燒毀了。";
  Sentence[3586] = "我們不見我們的標幟，";
  Sentence[3587] = "不再有先知；";
  Sentence[3588] = "我們內中也沒有人知道這災禍要到幾時呢！";
  Sentence[3589] = "神啊，";
  Sentence[3590] = "敵人辱罵要到幾時呢？";
  Sentence[3591] = "仇敵褻瀆你的名要到永遠嗎？";
  Sentence[3592] = "你為什麼縮回你的右手？";
  Sentence[3593] = "求你從懷中伸出來，";
  Sentence[3594] = "毀滅他們。";
  Sentence[3595] = "神自古以來為我的王，";
  Sentence[3596] = "在地上施行拯救。";
  Sentence[3597] = "你曾用能力將海分開，";
  Sentence[3598] = "將水中大魚的頭打破。";
  Sentence[3599] = "你曾砸碎鱷魚的頭，";
  Sentence[3600] = "把他給曠野的禽獸為食物。";
  Sentence[3601] = "你曾分裂磐石，";
  Sentence[3602] = "水便成了溪河；";
  Sentence[3603] = "你使長流的江河乾了。";
  Sentence[3604] = "白晝屬你，";
  Sentence[3605] = "黑夜也屬你；";
  Sentence[3606] = "亮光和日頭是你所預備的。";
  Sentence[3607] = "地的一切疆界是你所立的；";
  Sentence[3608] = "夏天和冬天是你所定的。";
  Sentence[3609] = "耶和華啊，";
  Sentence[3610] = "仇敵辱罵，";
  Sentence[3611] = "愚頑民褻瀆了你的名，";
  Sentence[3612] = "求你記念這事。";
  Sentence[3613] = "不要將你斑鳩的性命交給野獸；";
  Sentence[3614] = "不要永遠忘記你困苦人的性命。";
  Sentence[3615] = "求你顧念所立的約，";
  Sentence[3616] = "因為地上黑暗之處都滿了強暴的居所。";
  Sentence[3617] = "不要叫受欺壓的人蒙羞回去；";
  Sentence[3618] = "要叫困苦窮乏的人讚美你的名。";
  Sentence[3619] = "神啊，";
  Sentence[3620] = "求你起來為自己伸訴！";
  Sentence[3621] = "要記念愚頑人怎樣終日辱罵你。";
  Sentence[3622] = "不要忘記你敵人的聲音；";
  Sentence[3623] = "那起來敵你之人的喧嘩時常上升。";
  Sentence[3624] = "詩篇七十五篇";
  Sentence[3625] = "神啊，";
  Sentence[3626] = "我們稱謝你，";
  Sentence[3627] = "我們稱謝你！";
  Sentence[3628] = "因為你的名相近，";
  Sentence[3629] = "人都述說你奇妙的作為。";
  Sentence[3630] = "我到了所定的日期，";
  Sentence[3631] = "必按正直施行審判。";
  Sentence[3632] = "地和其上的居民都消化了；";
  Sentence[3633] = "我曾立了地的柱子。";
  Sentence[3634] = "我對狂傲人說：";
  Sentence[3635] = "不要行事狂傲！";
  Sentence[3636] = "對凶惡人說：";
  Sentence[3637] = "不要舉角！";
  Sentence[3638] = "不要把你們的角高舉；";
  Sentence[3639] = "不要挺著頸項說話。";
  Sentence[3640] = "因為高舉非從東，";
  Sentence[3641] = "非從西，";
  Sentence[3642] = "也非從南而來。";
  Sentence[3643] = "惟有神斷定；";
  Sentence[3644] = "他使這人降卑，";
  Sentence[3645] = "使那人升高。";
  Sentence[3646] = "耶和華手裡有杯，";
  Sentence[3647] = "其中的酒起沫，";
  Sentence[3648] = "杯內滿了攙雜的酒；";
  Sentence[3649] = "他倒出來，";
  Sentence[3650] = "地上的惡人必都喝這酒的渣滓，";
  Sentence[3651] = "而且喝盡。";
  Sentence[3652] = "但我要宣揚，";
  Sentence[3653] = "直到永遠！";
  Sentence[3654] = "我要歌頌雅各的神！";
  Sentence[3655] = "惡人一切的角，";
  Sentence[3656] = "我要砍斷；";
  Sentence[3657] = "惟有義人的角必被高舉。";
  Sentence[3658] = "詩篇七十六篇";
  Sentence[3659] = "在猶大，";
  Sentence[3660] = "神為人所認識；";
  Sentence[3661] = "在以色列，";
  Sentence[3662] = "他的名為大。";
  Sentence[3663] = "在撒冷有他的帳幕；";
  Sentence[3664] = "在錫安有他的居所。";
  Sentence[3665] = "他在那裡折斷弓上的火箭，";
  Sentence[3666] = "並盾牌、";
  Sentence[3667] = "刀劍，";
  Sentence[3668] = "和爭戰的兵器。";
  Sentence[3669] = "你從有野食之山而來，";
  Sentence[3670] = "有光華和榮美。";
  Sentence[3671] = "心中勇敢的人都被搶奪；";
  Sentence[3672] = "他們睡了長覺，";
  Sentence[3673] = "沒有一個英雄能措手。";
  Sentence[3674] = "雅各的神啊，";
  Sentence[3675] = "你的斥責一發，";
  Sentence[3676] = "坐車的；";
  Sentence[3677] = "騎馬的都沉睡了。";
  Sentence[3678] = "惟獨你是可畏的！";
  Sentence[3679] = "你怒氣一發，";
  Sentence[3680] = "誰能在你面前站得住呢？";
  Sentence[3681] = "你從天上使人聽判斷。";
  Sentence[3682] = "神起來施行審判，";
  Sentence[3683] = "要救地上一切謙卑的人；";
  Sentence[3684] = "那時地就懼怕而靜默。";
  Sentence[3685] = "人的忿怒要成全你的榮美；";
  Sentence[3686] = "人的餘怒，";
  Sentence[3687] = "你要禁止。";
  Sentence[3688] = "你們許願，";
  Sentence[3689] = "當向耶和華－";
  Sentence[3690] = "你們的神還願；";
  Sentence[3691] = "在他四面的人都當拿貢物獻給那可畏的主。";
  Sentence[3692] = "他要挫折王子的驕氣；";
  Sentence[3693] = "他向地上的君王顯威可畏。";
  Sentence[3694] = "詩篇七十七篇";
  Sentence[3695] = "我要向神發聲呼求；";
  Sentence[3696] = "我向神發聲，";
  Sentence[3697] = "他必留心聽我。";
  Sentence[3698] = "我在患難之日尋求主；";
  Sentence[3699] = "我在夜間不住地舉手禱告；";
  Sentence[3700] = "我的心不肯受安慰。";
  Sentence[3701] = "我想念神，";
  Sentence[3702] = "就煩燥不安；";
  Sentence[3703] = "我沉吟悲傷，";
  Sentence[3704] = "心便發昏。";
  Sentence[3705] = "你叫我不能閉眼；";
  Sentence[3706] = "我煩亂不安，";
  Sentence[3707] = "甚至不能說話。";
  Sentence[3708] = "我追想古時之日，";
  Sentence[3709] = "上古之年。";
  Sentence[3710] = "我想起我夜間的歌曲，";
  Sentence[3711] = "捫心自問；";
  Sentence[3712] = "我心裡也仔細省察。";
  Sentence[3713] = "難道主要永遠丟棄我，";
  Sentence[3714] = "不再施恩嗎？";
  Sentence[3715] = "難道他的慈愛永遠窮盡，";
  Sentence[3716] = "他的應許世世廢棄嗎？";
  Sentence[3717] = "難道神忘記開恩，";
  Sentence[3718] = "因發怒就止住他的慈悲嗎？";
  Sentence[3719] = "我便說：";
  Sentence[3720] = "這是我的懦弱，";
  Sentence[3721] = "但我要追念至高者顯出右手之年代。";
  Sentence[3722] = "我要提說耶和華所行的；";
  Sentence[3723] = "我要記念你古時的奇事。";
  Sentence[3724] = "我也要思想你的經營，";
  Sentence[3725] = "默念你的作為。";
  Sentence[3726] = "神啊，";
  Sentence[3727] = "你的作為是潔淨的；";
  Sentence[3728] = "有何神大如神呢？";
  Sentence[3729] = "你是行奇事的神；";
  Sentence[3730] = "你曾在列邦中彰顯你的能力。";
  Sentence[3731] = "你曾用你的膀臂贖了你的民，";
  Sentence[3732] = "就是雅各和約瑟的子孫。";
  Sentence[3733] = "神啊，";
  Sentence[3734] = "諸水見你，";
  Sentence[3735] = "一見就都驚惶；";
  Sentence[3736] = "深淵也都戰抖。";
  Sentence[3737] = "雲中倒出水來；";
  Sentence[3738] = "天空發出響聲；";
  Sentence[3739] = "你的箭也飛行四方。";
  Sentence[3740] = "你的雷聲在旋風中；";
  Sentence[3741] = "電光照亮世界；";
  Sentence[3742] = "大地戰抖震動。";
  Sentence[3743] = "你的道在海中；";
  Sentence[3744] = "你的路在大水中；";
  Sentence[3745] = "你的腳蹤無人知道。";
  Sentence[3746] = "你曾藉摩西和亞倫的手引導你的百姓，";
  Sentence[3747] = "好像羊群一般。";
  Sentence[3748] = "詩篇七十八篇";
  Sentence[3749] = "我的民哪，";
  Sentence[3750] = "你們要留心聽我的訓誨，";
  Sentence[3751] = "側耳聽我口中的話。";
  Sentence[3752] = "我要開口說比喻；";
  Sentence[3753] = "我要說出古時的謎語，";
  Sentence[3754] = "是我們所聽見、";
  Sentence[3755] = "所知道的，";
  Sentence[3756] = "也是我們的祖宗告訴我們的。";
  Sentence[3757] = "我們不將這些事向他們的子孫隱瞞，";
  Sentence[3758] = "要將耶和華的美德和他的能力，";
  Sentence[3759] = "並他奇妙的作為，";
  Sentence[3760] = "述說給後代聽。";
  Sentence[3761] = "因為，";
  Sentence[3762] = "他在雅各中立法度，";
  Sentence[3763] = "在以色列中設律法；";
  Sentence[3764] = "是他吩咐我們祖宗要傳給子孫的，";
  Sentence[3765] = "使將要生的後代子孫可以曉得；";
  Sentence[3766] = "他們也要起來告訴他們的子孫，";
  Sentence[3767] = "好叫他們仰望神，";
  Sentence[3768] = "不忘記神的作為，";
  Sentence[3769] = "惟要守他的命令。";
  Sentence[3770] = "不要像他們的祖宗，";
  Sentence[3771] = "是頑梗悖逆、";
  Sentence[3772] = "居心不正之輩，";
  Sentence[3773] = "向著神，";
  Sentence[3774] = "心不誠實。";
  Sentence[3775] = "以法蓮的子孫帶著兵器，";
  Sentence[3776] = "拿著弓，";
  Sentence[3777] = "臨陣之日轉身退後。";
  Sentence[3778] = "他們不遵守神的約，";
  Sentence[3779] = "不肯照他的律法行；";
  Sentence[3780] = "又忘記他所行的和他顯給他們奇妙的作為。";
  Sentence[3781] = "他在埃及地，";
  Sentence[3782] = "在瑣安田，";
  Sentence[3783] = "在他們祖宗的眼前施行奇事。";
  Sentence[3784] = "他將海分裂，";
  Sentence[3785] = "使他們過去，";
  Sentence[3786] = "又叫水立起如壘。";
  Sentence[3787] = "他白日用雲彩，";
  Sentence[3788] = "終夜用火光引導他們。";
  Sentence[3789] = "他在曠野分裂磐石，";
  Sentence[3790] = "多多地給他們水喝，";
  Sentence[3791] = "如從深淵而出。";
  Sentence[3792] = "他使水從磐石湧出，";
  Sentence[3793] = "叫水如江河下流。";
  Sentence[3794] = "他們卻仍舊得罪他，";
  Sentence[3795] = "在乾燥之地悖逆至高者。";
  Sentence[3796] = "他們心中試探神，";
  Sentence[3797] = "隨自己所欲的求食物，";
  Sentence[3798] = "並且妄論神說：";
  Sentence[3799] = "神在曠野豈能擺設筵席嗎？";
  Sentence[3800] = "他曾擊打磐石，";
  Sentence[3801] = "使水湧出，";
  Sentence[3802] = "成了江河；";
  Sentence[3803] = "他還能賜糧食嗎？";
  Sentence[3804] = "還能為他的百姓預備肉嗎？";
  Sentence[3805] = "所以，";
  Sentence[3806] = "耶和華聽見就發怒；";
  Sentence[3807] = "有烈火向雅各燒起；";
  Sentence[3808] = "有怒氣向以色列上騰；";
  Sentence[3809] = "因為他們不信服神，";
  Sentence[3810] = "不倚賴他的救恩。";
  Sentence[3811] = "他卻吩咐天空，";
  Sentence[3812] = "又敞開天上的門，";
  Sentence[3813] = "降嗎哪，";
  Sentence[3814] = "像雨給他們吃，";
  Sentence[3815] = "將天上的糧食賜給他們。";
  Sentence[3816] = "各人吃大能者的食物；";
  Sentence[3817] = "他賜下糧食，";
  Sentence[3818] = "使他們飽足。";
  Sentence[3819] = "他領東風起在天空，";
  Sentence[3820] = "又用能力引了南風來。";
  Sentence[3821] = "他降肉，";
  Sentence[3822] = "像雨在他們當中，";
  Sentence[3823] = "多如塵土，";
  Sentence[3824] = "又降飛鳥，";
  Sentence[3825] = "多如海沙，";
  Sentence[3826] = "落在他們的營中，";
  Sentence[3827] = "在他們住處的四面。";
  Sentence[3828] = "他們吃了，";
  Sentence[3829] = "而且飽足；";
  Sentence[3830] = "這樣就隨了他們所欲的。";
  Sentence[3831] = "他們貪而無厭，";
  Sentence[3832] = "食物還在他們口中的時候，";
  Sentence[3833] = "神的怒氣就向他們上騰，";
  Sentence[3834] = "殺了他們內中的肥壯人，";
  Sentence[3835] = "打倒以色列的少年人。";
  Sentence[3836] = "雖是這樣，";
  Sentence[3837] = "他們仍舊犯罪，";
  Sentence[3838] = "不信他奇妙的作為。";
  Sentence[3839] = "因此，";
  Sentence[3840] = "他叫他們的日子全歸虛空，";
  Sentence[3841] = "叫他們的年歲盡屬驚恐。";
  Sentence[3842] = "他殺他們的時候，";
  Sentence[3843] = "他們才求問他，";
  Sentence[3844] = "回心轉意，";
  Sentence[3845] = "切切地尋求神。";
  Sentence[3846] = "他們也追念神是他們的磐石，";
  Sentence[3847] = "至高的神是他們的救贖主。";
  Sentence[3848] = "他們卻用口諂媚他，";
  Sentence[3849] = "用舌向他說謊。";
  Sentence[3850] = "因他們的心向他不正，";
  Sentence[3851] = "在他的約上也不忠心。";
  Sentence[3852] = "但他有憐憫，";
  Sentence[3853] = "赦免他們的罪孽，";
  Sentence[3854] = "不滅絕他們，";
  Sentence[3855] = "而且屢次消他的怒氣，";
  Sentence[3856] = "不發盡他的忿怒。";
  Sentence[3857] = "他想到他們不過是血氣，";
  Sentence[3858] = "是一陣去而不返的風。";
  Sentence[3859] = "他們在曠野悖逆他，";
  Sentence[3860] = "在荒地叫他擔憂，";
  Sentence[3861] = "何其多呢！";
  Sentence[3862] = "他們再三試探神，";
  Sentence[3863] = "惹動以色列的聖者。";
  Sentence[3864] = "他們不追念他的能力和贖他們脫離敵人的日子；";
  Sentence[3865] = "他怎樣在埃及地顯神蹟，";
  Sentence[3866] = "在瑣安田顯奇事，";
  Sentence[3867] = "把他們的江河並河汊的水都變為血，";
  Sentence[3868] = "使他們不能喝。";
  Sentence[3869] = "他叫蒼蠅成群落在他們當中，";
  Sentence[3870] = "嘬盡他們，";
  Sentence[3871] = "又叫青蛙滅了他們，";
  Sentence[3872] = "把他們的土產交給螞蚱，";
  Sentence[3873] = "把他們辛苦得來的交給蝗蟲。";
  Sentence[3874] = "他降冰雹打壞他們的葡萄樹，";
  Sentence[3875] = "下嚴霜打壞他們的桑樹，";
  Sentence[3876] = "又把他們的牲畜交給冰雹，";
  Sentence[3877] = "把他們的群畜交給閃電。";
  Sentence[3878] = "他使猛烈的怒氣和忿怒、";
  Sentence[3879] = "惱恨、";
  Sentence[3880] = "苦難成了一群降災的使者，";
  Sentence[3881] = "臨到他們。";
  Sentence[3882] = "他為自己的怒氣修平了路，";
  Sentence[3883] = "將他們交給瘟疫，";
  Sentence[3884] = "使他們死亡，";
  Sentence[3885] = "在埃及擊殺一切長子，";
  Sentence[3886] = "在含的帳棚中擊殺他們強壯時頭生的。";
  Sentence[3887] = "他卻領出自己的民如羊，";
  Sentence[3888] = "在曠野引他們如羊群。";
  Sentence[3889] = "他領他們穩穩妥妥地，";
  Sentence[3890] = "使他們不致害怕；";
  Sentence[3891] = "海卻淹沒他們的仇敵。";
  Sentence[3892] = "他帶他們到自己聖地的邊界，";
  Sentence[3893] = "到他右手所得的這山地。";
  Sentence[3894] = "他在他們面前趕出外邦人，";
  Sentence[3895] = "用繩子將外邦的地量給他們為業，";
  Sentence[3896] = "叫以色列支派的人住在他們的帳棚裡。";
  Sentence[3897] = "他們仍舊試探、";
  Sentence[3898] = "悖逆至高的神，";
  Sentence[3899] = "不守他的法度，";
  Sentence[3900] = "反倒退後，";
  Sentence[3901] = "行詭詐，";
  Sentence[3902] = "像他們的祖宗一樣；";
  Sentence[3903] = "他們改變，";
  Sentence[3904] = "如同翻背的弓。";
  Sentence[3905] = "因他們的邱壇惹了他的怒氣；";
  Sentence[3906] = "因他們雕刻的偶像觸動他的憤恨。";
  Sentence[3907] = "神聽見就發怒，";
  Sentence[3908] = "極其憎惡以色列人。";
  Sentence[3909] = "甚至他離棄示羅的帳幕，";
  Sentence[3910] = "就是他在人間所搭的帳棚；";
  Sentence[3911] = "又將他的約櫃交與人擄去，";
  Sentence[3912] = "將他的榮耀交在敵人手中；";
  Sentence[3913] = "並將他的百姓交與刀劍，";
  Sentence[3914] = "向他的產業發怒。";
  Sentence[3915] = "少年人被火燒滅；";
  Sentence[3916] = "處女也無喜歌。";
  Sentence[3917] = "祭司倒在刀下，";
  Sentence[3918] = "寡婦卻不哀哭。";
  Sentence[3919] = "那時，";
  Sentence[3920] = "主像世人睡醒，";
  Sentence[3921] = "像勇士飲酒呼喊。";
  Sentence[3922] = "他就打退了他的敵人，";
  Sentence[3923] = "叫他們永蒙羞辱；";
  Sentence[3924] = "並且他棄掉約瑟的帳棚，";
  Sentence[3925] = "不揀選以法蓮支派，";
  Sentence[3926] = "卻揀選猶大支派－";
  Sentence[3927] = "他所喜愛的錫安山；";
  Sentence[3928] = "蓋造他的聖所，";
  Sentence[3929] = "好像高峯，";
  Sentence[3930] = "又像他建立永存之地；";
  Sentence[3931] = "又揀選他的僕人大衛，";
  Sentence[3932] = "從羊圈中將他召來，";
  Sentence[3933] = "叫他不再跟從那些帶奶的母羊，";
  Sentence[3934] = "為要牧養自己的百姓雅各和自己的產業以色列。";
  Sentence[3935] = "於是，";
  Sentence[3936] = "他按心中的純正牧養他們，";
  Sentence[3937] = "用手中的巧妙引導他們。";
  Sentence[3938] = "詩篇七十九篇";
  Sentence[3939] = "神啊，";
  Sentence[3940] = "外邦人進入你的產業，";
  Sentence[3941] = "污穢你的聖殿，";
  Sentence[3942] = "使耶路撒冷變成荒堆，";
  Sentence[3943] = "把你僕人的屍首交與天空的飛鳥為食，";
  Sentence[3944] = "把你聖民的肉交與地上的野獸，";
  Sentence[3945] = "在耶路撒冷周圍流他們的血如水，";
  Sentence[3946] = "無人葬埋。";
  Sentence[3947] = "我們成為鄰國的羞辱，";
  Sentence[3948] = "成為我們四圍人的嗤笑譏刺。";
  Sentence[3949] = "耶和華啊，";
  Sentence[3950] = "這到幾時呢？";
  Sentence[3951] = "你要動怒到永遠嗎？";
  Sentence[3952] = "你的憤恨要如火焚燒嗎？";
  Sentence[3953] = "願你將你的忿怒倒在那不認識你的外邦和那不求告你名的國度。";
  Sentence[3954] = "因為他們吞了雅各，";
  Sentence[3955] = "把他的住處變為荒場。";
  Sentence[3956] = "求你不要記念我們先祖的罪孽，";
  Sentence[3957] = "向我們追討；";
  Sentence[3958] = "願你的慈悲快迎著我們，";
  Sentence[3959] = "因為我們落到極卑微的地步。";
  Sentence[3960] = "拯救我們的神啊，";
  Sentence[3961] = "求你因你名的榮耀幫助我們！";
  Sentence[3962] = "為你名的緣故搭救我們，";
  Sentence[3963] = "赦免我們的罪。";
  Sentence[3964] = "為何容外邦人說他們的神在哪裡呢？";
  Sentence[3965] = "願你使外邦人知道你在我們眼前伸你僕人流血的冤。";
  Sentence[3966] = "願被囚之人的歎息達到你面前；";
  Sentence[3967] = "願你按你的大能力存留那些將要死的人。";
  Sentence[3968] = "主啊，";
  Sentence[3969] = "願你將我們鄰邦所羞辱你的羞辱加七倍歸到他們身上。";
  Sentence[3970] = "這樣，";
  Sentence[3971] = "你的民，";
  Sentence[3972] = "你草場的羊，";
  Sentence[3973] = "要稱謝你，";
  Sentence[3974] = "直到永遠；";
  Sentence[3975] = "要述說讚美你的話，";
  Sentence[3976] = "直到萬代。";
  Sentence[3977] = "詩篇八十篇";
  Sentence[3978] = "領約瑟如領羊群之以色列的牧者啊，";
  Sentence[3979] = "求你留心聽！";
  Sentence[3980] = "坐在二基路伯上的啊，";
  Sentence[3981] = "求你發出光來！";
  Sentence[3982] = "在以法蓮、";
  Sentence[3983] = "便雅憫、";
  Sentence[3984] = "瑪拿西前面施展你的大能，";
  Sentence[3985] = "來救我們。";
  Sentence[3986] = "神啊，";
  Sentence[3987] = "求你使我們回轉，";
  Sentence[3988] = "使你的臉發光，";
  Sentence[3989] = "我們便要得救！";
  Sentence[3990] = "耶和華－";
  Sentence[3991] = "萬軍之神啊，";
  Sentence[3992] = "你向你百姓的禱告發怒，";
  Sentence[3993] = "要到幾時呢？";
  Sentence[3994] = "你以眼淚當食物給他們吃，";
  Sentence[3995] = "又多量出眼淚給他們喝。";
  Sentence[3996] = "你使鄰邦因我們紛爭；";
  Sentence[3997] = "我們的仇敵彼此戲笑。";
  Sentence[3998] = "萬軍之神啊，";
  Sentence[3999] = "求你使我們回轉，";
  Sentence[4000] = "使你的臉發光，";
  Sentence[4001] = "我們便要得救！";
  Sentence[4002] = "你從埃及挪出一棵葡萄樹，";
  Sentence[4003] = "趕出外邦人，";
  Sentence[4004] = "把這樹栽上。";
  Sentence[4005] = "你在這樹根前預備了地方，";
  Sentence[4006] = "他就深深扎根，";
  Sentence[4007] = "爬滿了地。";
  Sentence[4008] = "他的影子遮滿了山，";
  Sentence[4009] = "枝子好像佳美的香柏樹。";
  Sentence[4010] = "他發出枝子，";
  Sentence[4011] = "長到大海，";
  Sentence[4012] = "發出蔓子，";
  Sentence[4013] = "延到大河。";
  Sentence[4014] = "你為何拆毀這樹的籬笆，";
  Sentence[4015] = "任憑一切過路的人摘取？";
  Sentence[4016] = "林中出來的野豬把他糟踏；";
  Sentence[4017] = "野地的走獸拿他當食物。";
  Sentence[4018] = "萬軍之神啊，";
  Sentence[4019] = "求你回轉！";
  Sentence[4020] = "從天上垂看，";
  Sentence[4021] = "眷顧這葡萄樹，";
  Sentence[4022] = "保護你右手所栽的和你為自己所堅固的枝子。";
  Sentence[4023] = "這樹已經被火焚燒，";
  Sentence[4024] = "被刀砍伐；";
  Sentence[4025] = "他們因你臉上的怒容就滅亡了。";
  Sentence[4026] = "願你的手扶持你右邊的人，";
  Sentence[4027] = "就是你為自己所堅固的人子。";
  Sentence[4028] = "這樣，";
  Sentence[4029] = "我們便不退後離開你；";
  Sentence[4030] = "求你救活我們，";
  Sentence[4031] = "我們就要求告你的名。";
  Sentence[4032] = "耶和華－";
  Sentence[4033] = "萬軍之神啊，";
  Sentence[4034] = "求你使我們回轉，";
  Sentence[4035] = "使你的臉發光，";
  Sentence[4036] = "我們便要得救！";
  Sentence[4037] = "詩篇八十一篇";
  Sentence[4038] = "你們當向神－";
  Sentence[4039] = "我們的力量大聲歡呼，";
  Sentence[4040] = "向雅各的神發聲歡樂！";
  Sentence[4041] = "唱起詩歌，";
  Sentence[4042] = "打手鼓，";
  Sentence[4043] = "彈美琴與瑟。";
  Sentence[4044] = "當在月朔並月望－";
  Sentence[4045] = "我們過節的日期吹角，";
  Sentence[4046] = "因這是為以色列定的律例，";
  Sentence[4047] = "是雅各神的典章。";
  Sentence[4048] = "他去攻擊埃及地的時候，";
  Sentence[4049] = "在約瑟中間立此為證。";
  Sentence[4050] = "我在那裡聽見我所不明白的言語：";
  Sentence[4051] = "神說：";
  Sentence[4052] = "我使你的肩得脫重擔，";
  Sentence[4053] = "你的手放下筐子。";
  Sentence[4054] = "你在急難中呼求，";
  Sentence[4055] = "我就搭救你；";
  Sentence[4056] = "我在雷的隱密處應允你，";
  Sentence[4057] = "在米利巴水那裡試驗你。";
  Sentence[4058] = "我的民哪，";
  Sentence[4059] = "你當聽，";
  Sentence[4060] = "我要勸戒你；";
  Sentence[4061] = "以色列啊，";
  Sentence[4062] = "甚願你肯聽從我。";
  Sentence[4063] = "在你當中，";
  Sentence[4064] = "不可有別的神；";
  Sentence[4065] = "外邦的神，";
  Sentence[4066] = "你也不可下拜。";
  Sentence[4067] = "我是耶和華－";
  Sentence[4068] = "你的神，";
  Sentence[4069] = "曾把你從埃及地領上來；";
  Sentence[4070] = "你要大大張口，";
  Sentence[4071] = "我就給你充滿。";
  Sentence[4072] = "無奈，";
  Sentence[4073] = "我的民不聽我的聲音；";
  Sentence[4074] = "以色列全不理我。";
  Sentence[4075] = "我便任憑他們心裡剛硬，";
  Sentence[4076] = "隨自己的計謀而行。";
  Sentence[4077] = "甚願我的民肯聽從我，";
  Sentence[4078] = "以色列肯行我的道，";
  Sentence[4079] = "我便速速治服他們的仇敵，";
  Sentence[4080] = "反手攻擊他們的敵人。";
  Sentence[4081] = "恨耶和華的人必來投降，";
  Sentence[4082] = "但他的百姓必永久長存。";
  Sentence[4083] = "他也必拿上好的麥子給他們吃，";
  Sentence[4084] = "又拿從磐石出的蜂蜜叫他們飽足。";
  Sentence[4085] = "詩篇八十二篇";
  Sentence[4086] = "神站在有權力者的會中，";
  Sentence[4087] = "在諸神中行審判，";
  Sentence[4088] = "說：";
  Sentence[4089] = "你們審判不秉公義，";
  Sentence[4090] = "徇惡人的情面，";
  Sentence[4091] = "要到幾時呢？";
  Sentence[4092] = "你們當為貧寒的人和孤兒伸冤；";
  Sentence[4093] = "當為困苦和窮乏的人施行公義。";
  Sentence[4094] = "當保護貧寒和窮乏的人，";
  Sentence[4095] = "救他們脫離惡人的手。";
  Sentence[4096] = "你們仍不知道，";
  Sentence[4097] = "也不明白，";
  Sentence[4098] = "在黑暗中走來走去；";
  Sentence[4099] = "地的根基都搖動了。";
  Sentence[4100] = "我曾說：";
  Sentence[4101] = "你們是神，";
  Sentence[4102] = "都是至高者的兒子。";
  Sentence[4103] = "然而，";
  Sentence[4104] = "你們要死，";
  Sentence[4105] = "與世人一樣，";
  Sentence[4106] = "要仆倒，";
  Sentence[4107] = "像王子中的一位。";
  Sentence[4108] = "神啊，";
  Sentence[4109] = "求你起來審判世界，";
  Sentence[4110] = "因為你要得萬邦為業。";
  Sentence[4111] = "詩篇八十三篇";
  Sentence[4112] = "神啊，";
  Sentence[4113] = "求你不要靜默！";
  Sentence[4114] = "神啊，";
  Sentence[4115] = "求你不要閉口，";
  Sentence[4116] = "也不要不作聲！";
  Sentence[4117] = "因為你的仇敵喧嚷，";
  Sentence[4118] = "恨你的擡起頭來。";
  Sentence[4119] = "他們同謀奸詐要害你的百姓，";
  Sentence[4120] = "彼此商議要害你所隱藏的人。";
  Sentence[4121] = "他們說：";
  Sentence[4122] = "來吧，";
  Sentence[4123] = "我們將他們剪滅，";
  Sentence[4124] = "使他們不再成國！";
  Sentence[4125] = "使以色列的名不再被人記念！";
  Sentence[4126] = "他們同心商議，";
  Sentence[4127] = "彼此結盟，";
  Sentence[4128] = "要抵擋你，";
  Sentence[4129] = "就是住帳棚的以東人和以實瑪利人，";
  Sentence[4130] = "摩押和夏甲人，";
  Sentence[4131] = "迦巴勒、";
  Sentence[4132] = "亞捫，";
  Sentence[4133] = "和亞瑪力、";
  Sentence[4134] = "非利士並推羅的居民。";
  Sentence[4135] = "亞述也與他們連合；";
  Sentence[4136] = "他們作羅得子孫的幫手。";
  Sentence[4137] = "求你待他們，";
  Sentence[4138] = "如待米甸，";
  Sentence[4139] = "如在基順河待西西拉和耶賓一樣。";
  Sentence[4140] = "他們在隱多珥滅亡，";
  Sentence[4141] = "成了地上的糞土。";
  Sentence[4142] = "求你叫他們的首領像俄立和西伊伯，";
  Sentence[4143] = "叫他們的王子都像西巴和撒慕拿。";
  Sentence[4144] = "他們說：";
  Sentence[4145] = "我們要得神的住處，";
  Sentence[4146] = "作為自己的產業。";
  Sentence[4147] = "我的神啊，";
  Sentence[4148] = "求你叫他們像旋風的塵土，";
  Sentence[4149] = "像風前的碎稭。";
  Sentence[4150] = "火怎樣焚燒樹林，";
  Sentence[4151] = "火焰怎樣燒著山嶺，";
  Sentence[4152] = "求你也照樣用狂風追趕他們，";
  Sentence[4153] = "用暴雨恐嚇他們。";
  Sentence[4154] = "願你使他們滿面羞恥，";
  Sentence[4155] = "好叫他們尋求你－";
  Sentence[4156] = "耶和華的名！";
  Sentence[4157] = "願他們永遠羞愧驚惶！";
  Sentence[4158] = "願他們慚愧滅亡！";
  Sentence[4159] = "使他們知道：";
  Sentence[4160] = "惟獨你－";
  Sentence[4161] = "名為耶和華的－";
  Sentence[4162] = "是全地以上的至高者！";
  Sentence[4163] = "詩篇八十四篇";
  Sentence[4164] = "萬軍之耶和華啊，";
  Sentence[4165] = "你的居所何等可愛！";
  Sentence[4166] = "我羨慕渴想耶和華的院宇；";
  Sentence[4167] = "我的心腸，";
  Sentence[4168] = "我的肉體向永生神呼籲。";
  Sentence[4169] = "萬軍之耶和華－";
  Sentence[4170] = "我的王，";
  Sentence[4171] = "我的神啊，";
  Sentence[4172] = "在你祭壇那裡，";
  Sentence[4173] = "麻雀為自己找著房屋，";
  Sentence[4174] = "燕子為自己找著菢雛之窩。";
  Sentence[4175] = "如此住在你殿中的便為有福！";
  Sentence[4176] = "他們仍要讚美你。";
  Sentence[4177] = "靠你有力量、";
  Sentence[4178] = "心中想往錫安大道的，";
  Sentence[4179] = "這人便為有福！";
  Sentence[4180] = "他們經過流淚谷，";
  Sentence[4181] = "叫這谷變為泉源之地；";
  Sentence[4182] = "並有秋雨之福蓋滿了全谷。";
  Sentence[4183] = "他們行走，";
  Sentence[4184] = "力上加力，";
  Sentence[4185] = "各人到錫安朝見神。";
  Sentence[4186] = "耶和華－";
  Sentence[4187] = "萬軍之神啊，";
  Sentence[4188] = "求你聽我的禱告！";
  Sentence[4189] = "雅各的神啊，";
  Sentence[4190] = "求你留心聽！";
  Sentence[4191] = "神啊，";
  Sentence[4192] = "你是我們的盾牌；";
  Sentence[4193] = "求你垂顧觀看你受膏者的面！";
  Sentence[4194] = "在你的院宇住一日，";
  Sentence[4195] = "勝似在別處住千日；";
  Sentence[4196] = "寧可在我神殿中看門，";
  Sentence[4197] = "不願住在惡人的帳棚裡。";
  Sentence[4198] = "因為耶和華－";
  Sentence[4199] = "神是日頭，";
  Sentence[4200] = "是盾牌，";
  Sentence[4201] = "要賜下恩惠和榮耀。";
  Sentence[4202] = "他未嘗留下一樣好處不給那些行動正直的人。";
  Sentence[4203] = "萬軍之耶和華啊，";
  Sentence[4204] = "倚靠你的人便為有福！";
  Sentence[4205] = "詩篇八十五篇";
  Sentence[4206] = "耶和華啊，";
  Sentence[4207] = "你已經向你的地施恩，";
  Sentence[4208] = "救回被擄的雅各。";
  Sentence[4209] = "你赦免了你百姓的罪孽，";
  Sentence[4210] = "遮蓋了他們一切的過犯。";
  Sentence[4211] = "你收轉了所發的忿怒和你猛烈的怒氣。";
  Sentence[4212] = "拯救我們的神啊，";
  Sentence[4213] = "求你使我們回轉，";
  Sentence[4214] = "叫你的惱恨向我們止息。";
  Sentence[4215] = "你要向我們發怒到永遠嗎？";
  Sentence[4216] = "你要將你的怒氣延留到萬代嗎？";
  Sentence[4217] = "你不再將我們救活，";
  Sentence[4218] = "使你的百姓靠你歡喜嗎？";
  Sentence[4219] = "耶和華啊，";
  Sentence[4220] = "求你使我們得見你的慈愛，";
  Sentence[4221] = "又將你的救恩賜給我們。";
  Sentence[4222] = "我要聽神－";
  Sentence[4223] = "耶和華所說的話；";
  Sentence[4224] = "因為他必應許將平安賜給他的百姓－";
  Sentence[4225] = "他的聖民；";
  Sentence[4226] = "他們卻不可再轉去妄行。";
  Sentence[4227] = "他的救恩誠然與敬畏他的人相近，";
  Sentence[4228] = "叫榮耀住在我們的地上。";
  Sentence[4229] = "慈愛和誠實彼此相遇；";
  Sentence[4230] = "公義和平安彼此相親。";
  Sentence[4231] = "誠實從地而生；";
  Sentence[4232] = "公義從天而現。";
  Sentence[4233] = "耶和華必將好處賜給我們；";
  Sentence[4234] = "我們的地也要多出土產。";
  Sentence[4235] = "公義要行在他面前，";
  Sentence[4236] = "叫他的腳蹤成為可走的路。";
  Sentence[4237] = "詩篇八十六篇";
  Sentence[4238] = "耶和華啊，";
  Sentence[4239] = "求你側耳應允我，";
  Sentence[4240] = "因我是困苦窮乏的。";
  Sentence[4241] = "求你保存我的性命，";
  Sentence[4242] = "因我是虔誠人。";
  Sentence[4243] = "我的神啊，";
  Sentence[4244] = "求你拯救這倚靠你的僕人！";
  Sentence[4245] = "主啊，";
  Sentence[4246] = "求你憐憫我，";
  Sentence[4247] = "因我終日求告你。";
  Sentence[4248] = "主啊，";
  Sentence[4249] = "求你使僕人心裡歡喜，";
  Sentence[4250] = "因為我的心仰望你。";
  Sentence[4251] = "主啊，";
  Sentence[4252] = "你本為良善，";
  Sentence[4253] = "樂意饒恕人，";
  Sentence[4254] = "有豐盛的慈愛賜給凡求告你的人。";
  Sentence[4255] = "耶和華啊，";
  Sentence[4256] = "求你留心聽我的禱告，";
  Sentence[4257] = "垂聽我懇求的聲音。";
  Sentence[4258] = "我在患難之日要求告你，";
  Sentence[4259] = "因為你必應允我。";
  Sentence[4260] = "主啊，";
  Sentence[4261] = "諸神之中沒有可比你的；";
  Sentence[4262] = "你的作為也無可比。";
  Sentence[4263] = "主啊，";
  Sentence[4264] = "你所造的萬民都要來敬拜你；";
  Sentence[4265] = "他們也要榮耀你的名。";
  Sentence[4266] = "因你為大，";
  Sentence[4267] = "且行奇妙的事；";
  Sentence[4268] = "惟獨你是神。";
  Sentence[4269] = "耶和華啊，";
  Sentence[4270] = "求你將你的道指教我；";
  Sentence[4271] = "我要照你的真理行；";
  Sentence[4272] = "求你使我專心敬畏你的名！";
  Sentence[4273] = "主－";
  Sentence[4274] = "我的神啊，";
  Sentence[4275] = "我要一心稱讚你；";
  Sentence[4276] = "我要榮耀你的名，";
  Sentence[4277] = "直到永遠。";
  Sentence[4278] = "因為，";
  Sentence[4279] = "你向我發的慈愛是大的；";
  Sentence[4280] = "你救了我的靈魂免入極深的陰間。";
  Sentence[4281] = "神啊，";
  Sentence[4282] = "驕傲的人起來攻擊我，";
  Sentence[4283] = "又有一黨強橫的人尋索我的命；";
  Sentence[4284] = "他們沒有將你放在眼中。";
  Sentence[4285] = "主啊，";
  Sentence[4286] = "你是有憐憫有恩典的神，";
  Sentence[4287] = "不輕易發怒，";
  Sentence[4288] = "並有豐盛的慈愛和誠實。";
  Sentence[4289] = "求你向我轉臉，";
  Sentence[4290] = "憐恤我，";
  Sentence[4291] = "將你的力量賜給僕人，";
  Sentence[4292] = "救你婢女的兒子。";
  Sentence[4293] = "求你向我顯出恩待我的憑據，";
  Sentence[4294] = "叫恨我的人看見便羞愧，";
  Sentence[4295] = "因為你－";
  Sentence[4296] = "耶和華幫助我，";
  Sentence[4297] = "安慰我。";
  Sentence[4298] = "詩篇八十七篇";
  Sentence[4299] = "耶和華所立的根基在聖山上。";
  Sentence[4300] = "他愛錫安的門，";
  Sentence[4301] = "勝於愛雅各一切的住處。";
  Sentence[4302] = "神的城啊，";
  Sentence[4303] = "有榮耀的事乃指著你說的。";
  Sentence[4304] = "我要提起拉哈伯和巴比倫人，";
  Sentence[4305] = "是在認識我之中的；";
  Sentence[4306] = "看哪，";
  Sentence[4307] = "非利士和推羅並古實人，";
  Sentence[4308] = "個個生在那裡。";
  Sentence[4309] = "論到錫安，";
  Sentence[4310] = "必說：";
  Sentence[4311] = "這一個、";
  Sentence[4312] = "那一個都生在其中，";
  Sentence[4313] = "而且至高者必親自堅立這城。";
  Sentence[4314] = "當耶和華記錄萬民的時候，";
  Sentence[4315] = "他要點出這一個生在那裡。";
  Sentence[4316] = "歌唱的，";
  Sentence[4317] = "跳舞的，";
  Sentence[4318] = "都要說：";
  Sentence[4319] = "我的泉源都在你裡面。";
  Sentence[4320] = "詩篇八十八篇";
  Sentence[4321] = "耶和華－";
  Sentence[4322] = "拯救我的神啊，";
  Sentence[4323] = "我晝夜在你面前呼籲。";
  Sentence[4324] = "願我的禱告達到你面前；";
  Sentence[4325] = "求你側耳聽我的呼求！";
  Sentence[4326] = "因為我心裡滿了患難；";
  Sentence[4327] = "我的性命臨近陰間。";
  Sentence[4328] = "我算和下坑的人同列，";
  Sentence[4329] = "如同無力的人一樣。";
  Sentence[4330] = "我被丟在死人中，";
  Sentence[4331] = "好像被殺的人躺在墳墓裡。";
  Sentence[4332] = "他們是你不再記念的，";
  Sentence[4333] = "與你隔絕了。";
  Sentence[4334] = "你把我放在極深的坑裡，";
  Sentence[4335] = "在黑暗地方，";
  Sentence[4336] = "在深處。";
  Sentence[4337] = "你的忿怒重壓我身；";
  Sentence[4338] = "你用一切的波浪困住我。";
  Sentence[4339] = "你把我所認識的隔在遠處，";
  Sentence[4340] = "使我為他們所憎惡；";
  Sentence[4341] = "我被拘困，";
  Sentence[4342] = "不得出來。";
  Sentence[4343] = "我的眼睛因困苦而乾癟。";
  Sentence[4344] = "耶和華啊，";
  Sentence[4345] = "我天天求告你，";
  Sentence[4346] = "向你舉手。";
  Sentence[4347] = "你豈要行奇事給死人看嗎？";
  Sentence[4348] = "難道陰魂還能起來稱讚你嗎？";
  Sentence[4349] = "豈能在墳墓裡述說你的慈愛嗎？";
  Sentence[4350] = "豈能在滅亡中述說你的信實嗎？";
  Sentence[4351] = "你的奇事豈能在幽暗裡被知道嗎？";
  Sentence[4352] = "你的公義豈能在忘記之地被知道嗎？";
  Sentence[4353] = "耶和華啊，";
  Sentence[4354] = "我呼求你；";
  Sentence[4355] = "我早晨的禱告要達到你面前。";
  Sentence[4356] = "耶和華啊，";
  Sentence[4357] = "你為何丟棄我？";
  Sentence[4358] = "為何掩面不顧我？";
  Sentence[4359] = "我自幼受苦，";
  Sentence[4360] = "幾乎死亡；";
  Sentence[4361] = "我受你的驚恐，";
  Sentence[4362] = "甚至慌張。";
  Sentence[4363] = "你的烈怒漫過我身；";
  Sentence[4364] = "你的驚嚇把我剪除。";
  Sentence[4365] = "這些終日如水環繞我，";
  Sentence[4366] = "一齊都來圍困我。";
  Sentence[4367] = "你把我的良朋密友隔在遠處，";
  Sentence[4368] = "使我所認識的人進入黑暗裡。";
  Sentence[4369] = "詩篇八十九篇";
  Sentence[4370] = "我要歌唱耶和華的慈愛，";
  Sentence[4371] = "直到永遠；";
  Sentence[4372] = "我要用口將你的信實傳與萬代。";
  Sentence[4373] = "因我曾說：";
  Sentence[4374] = "你的慈悲必建立到永遠；";
  Sentence[4375] = "你的信實必堅立在天上。";
  Sentence[4376] = "我與我所揀選的人立了約，";
  Sentence[4377] = "向我的僕人大衛起了誓：";
  Sentence[4378] = "我要建立你的後裔，";
  Sentence[4379] = "直到永遠；";
  Sentence[4380] = "要建立你的寶座，";
  Sentence[4381] = "直到萬代。";
  Sentence[4382] = "耶和華啊，";
  Sentence[4383] = "諸天要稱讚你的奇事；";
  Sentence[4384] = "在聖者的會中，";
  Sentence[4385] = "要稱讚你的信實。";
  Sentence[4386] = "在天空誰能比耶和華呢？";
  Sentence[4387] = "神的眾子中，";
  Sentence[4388] = "誰能像耶和華呢？";
  Sentence[4389] = "他在聖者的會中，";
  Sentence[4390] = "是大有威嚴的神，";
  Sentence[4391] = "比一切在他四圍的更可畏懼。";
  Sentence[4392] = "耶和華－";
  Sentence[4393] = "萬軍之神啊，";
  Sentence[4394] = "哪一個大能者像你耶和華？";
  Sentence[4395] = "你的信實是在你的四圍。";
  Sentence[4396] = "你管轄海的狂傲；";
  Sentence[4397] = "波浪翻騰，";
  Sentence[4398] = "你就使他平靜了。";
  Sentence[4399] = "你打碎了拉哈伯，";
  Sentence[4400] = "似乎是已殺的人；";
  Sentence[4401] = "你用有能的膀臂打散了你的仇敵。";
  Sentence[4402] = "天屬你，";
  Sentence[4403] = "地也屬你；";
  Sentence[4404] = "世界和其中所充滿的都為你所建立。";
  Sentence[4405] = "南北為你所創造；";
  Sentence[4406] = "他泊和黑門都因你的名歡呼。";
  Sentence[4407] = "你有大能的膀臂；";
  Sentence[4408] = "你的手有力，";
  Sentence[4409] = "你的右手也高舉。";
  Sentence[4410] = "公義和公平是你寶座的根基；";
  Sentence[4411] = "慈愛和誠實行在你前面。";
  Sentence[4412] = "知道向你歡呼的，";
  Sentence[4413] = "那民是有福的！";
  Sentence[4414] = "耶和華啊，";
  Sentence[4415] = "他們在你臉上的光裡行走。";
  Sentence[4416] = "他們因你的名終日歡樂，";
  Sentence[4417] = "因你的公義得以高舉。";
  Sentence[4418] = "你是他們力量的榮耀；";
  Sentence[4419] = "因為你喜悅我們，";
  Sentence[4420] = "我們的角必被高舉。";
  Sentence[4421] = "我們的盾牌屬耶和華；";
  Sentence[4422] = "我們的王屬以色列的聖者。";
  Sentence[4423] = "當時，";
  Sentence[4424] = "你在異象中曉諭你的聖民，";
  Sentence[4425] = "說：";
  Sentence[4426] = "我已把救助之力加在那有能者的身上；";
  Sentence[4427] = "我高舉那從民中所揀選的。";
  Sentence[4428] = "我尋得我的僕人大衛，";
  Sentence[4429] = "用我的聖膏膏他。";
  Sentence[4430] = "我的手必使他堅立；";
  Sentence[4431] = "我的膀臂也必堅固他。";
  Sentence[4432] = "仇敵必不勒索他；";
  Sentence[4433] = "凶惡之子也不苦害他。";
  Sentence[4434] = "我要在他面前打碎他的敵人，";
  Sentence[4435] = "擊殺那恨他的人。";
  Sentence[4436] = "只是我的信實和我的慈愛要與他同在；";
  Sentence[4437] = "因我的名，";
  Sentence[4438] = "他的角必被高舉。";
  Sentence[4439] = "我要使他的左手伸到海上，";
  Sentence[4440] = "右手伸到河上。";
  Sentence[4441] = "他要稱呼我說：";
  Sentence[4442] = "你是我的父，";
  Sentence[4443] = "是我的神，";
  Sentence[4444] = "是拯救我的磐石。";
  Sentence[4445] = "我也要立他為長子，";
  Sentence[4446] = "為世上最高的君王。";
  Sentence[4447] = "我要為他存留我的慈愛，";
  Sentence[4448] = "直到永遠；";
  Sentence[4449] = "我與他立的約必要堅定。";
  Sentence[4450] = "我也要使他的後裔存到永遠，";
  Sentence[4451] = "使他的寶座如天之久。";
  Sentence[4452] = "倘若他的子孫離棄我的律法，";
  Sentence[4453] = "不照我的典章行，";
  Sentence[4454] = "背棄我的律例，";
  Sentence[4455] = "不遵守我的誡命，";
  Sentence[4456] = "我就要用杖責罰他們的過犯，";
  Sentence[4457] = "用鞭責罰他們的罪孽。";
  Sentence[4458] = "只是我必不將我的慈愛全然收回，";
  Sentence[4459] = "也必不叫我的信實廢棄。";
  Sentence[4460] = "我必不背棄我的約，";
  Sentence[4461] = "也不改變我口中所出的。";
  Sentence[4462] = "我一次指著自己的聖潔起誓：";
  Sentence[4463] = "我決不向大衛說謊！";
  Sentence[4464] = "他的後裔要存到永遠；";
  Sentence[4465] = "他的寶座在我面前如日之恆一般，";
  Sentence[4466] = "又如月亮永遠堅立，";
  Sentence[4467] = "如天上確實的見證。";
  Sentence[4468] = "但你惱怒你的受膏者，";
  Sentence[4469] = "就丟掉棄絕他。";
  Sentence[4470] = "你厭惡了與僕人所立的約，";
  Sentence[4471] = "將他的冠冕踐踏於地。";
  Sentence[4472] = "你拆毀了他一切的籬笆，";
  Sentence[4473] = "使他的保障變為荒場。";
  Sentence[4474] = "凡過路的人都搶奪他；";
  Sentence[4475] = "他成為鄰邦的羞辱。";
  Sentence[4476] = "你高舉了他敵人的右手；";
  Sentence[4477] = "你叫他一切的仇敵歡喜。";
  Sentence[4478] = "你叫他的刀劍捲刃，";
  Sentence[4479] = "叫他在爭戰之中站立不住。";
  Sentence[4480] = "你使他的光輝止息，";
  Sentence[4481] = "將他的寶座推倒於地。";
  Sentence[4482] = "你減少他青年的日子，";
  Sentence[4483] = "又使他蒙羞。";
  Sentence[4484] = "耶和華啊，";
  Sentence[4485] = "這要到幾時呢？";
  Sentence[4486] = "你要將自己隱藏到永遠嗎？";
  Sentence[4487] = "你的忿怒如火焚燒要到幾時呢？";
  Sentence[4488] = "求你想念我的時候是何等的短少；";
  Sentence[4489] = "你創造世人，";
  Sentence[4490] = "要使他們歸何等的虛空呢？";
  Sentence[4491] = "誰能常活免死、";
  Sentence[4492] = "救他的靈魂脫離陰間的權柄呢？";
  Sentence[4493] = "主啊，";
  Sentence[4494] = "你從前憑你的信實向大衛立誓要施行的慈愛在哪裡呢？";
  Sentence[4495] = "主啊，";
  Sentence[4496] = "求你記念僕人們所受的羞辱，";
  Sentence[4497] = "記念我怎樣將一切強盛民的羞辱存在我懷裡。";
  Sentence[4498] = "耶和華啊，";
  Sentence[4499] = "你的仇敵用這羞辱羞辱了你的僕人，";
  Sentence[4500] = "羞辱了你受膏者的腳蹤。";
  Sentence[4501] = "耶和華是應當稱頌的，";
  Sentence[4502] = "直到永遠。";
  Sentence[4503] = "阿們！";
  Sentence[4504] = "阿們！";
  Sentence[4505] = "詩篇九十篇";
  Sentence[4506] = "主啊，";
  Sentence[4507] = "你世世代代作我們的居所。";
  Sentence[4508] = "諸山未曾生出，";
  Sentence[4509] = "地與世界你未曾造成，";
  Sentence[4510] = "從亙古到永遠，";
  Sentence[4511] = "你是神。";
  Sentence[4512] = "你使人歸於塵土，";
  Sentence[4513] = "說：";
  Sentence[4514] = "你們世人要歸回。";
  Sentence[4515] = "在你看來，";
  Sentence[4516] = "千年如已過的昨日，";
  Sentence[4517] = "又如夜間的一更。";
  Sentence[4518] = "你叫他們如水沖去；";
  Sentence[4519] = "他們如睡一覺。";
  Sentence[4520] = "早晨，";
  Sentence[4521] = "他們如生長的草，";
  Sentence[4522] = "早晨發芽生長，";
  Sentence[4523] = "晚上割下枯乾。";
  Sentence[4524] = "我們因你的怒氣而消滅，";
  Sentence[4525] = "因你的忿怒而驚惶。";
  Sentence[4526] = "你將我們的罪孽擺在你面前，";
  Sentence[4527] = "將我們的隱惡擺在你面光之中。";
  Sentence[4528] = "我們經過的日子都在你震怒之下；";
  Sentence[4529] = "我們度盡的年歲好像一聲歎息。";
  Sentence[4530] = "我們一生的年日是七十歲，";
  Sentence[4531] = "若是強壯可到八十歲；";
  Sentence[4532] = "但其中所矜誇的不過是勞苦愁煩，";
  Sentence[4533] = "轉眼成空，";
  Sentence[4534] = "我們便如飛而去。";
  Sentence[4535] = "誰曉得你怒氣的權勢？";
  Sentence[4536] = "誰按著你該受的敬畏曉得你的忿怒呢？";
  Sentence[4537] = "求你指教我們怎樣數算自己的日子，";
  Sentence[4538] = "好叫我們得著智慧的心。";
  Sentence[4539] = "耶和華啊，";
  Sentence[4540] = "我們要等到幾時呢？";
  Sentence[4541] = "求你轉回，";
  Sentence[4542] = "為你的僕人後悔。";
  Sentence[4543] = "求你使我們早早飽得你的慈愛，";
  Sentence[4544] = "好叫我們一生一世歡呼喜樂。";
  Sentence[4545] = "求你照著你使我們受苦的日子，";
  Sentence[4546] = "和我們遭難的年歲，";
  Sentence[4547] = "叫我們喜樂。";
  Sentence[4548] = "願你的作為向你僕人顯現；";
  Sentence[4549] = "願你的榮耀向他們子孫顯明。";
  Sentence[4550] = "願主－";
  Sentence[4551] = "我們神的榮美歸於我們身上。";
  Sentence[4552] = "願你堅立我們手所做的工；";
  Sentence[4553] = "我們手所做的工，";
  Sentence[4554] = "願你堅立。";
  Sentence[4555] = "詩篇九十一篇";
  Sentence[4556] = "住在至高者隱密處的，";
  Sentence[4557] = "必住在全能者的蔭下。";
  Sentence[4558] = "我要論到耶和華說：";
  Sentence[4559] = "他是我的避難所，";
  Sentence[4560] = "是我的山寨，";
  Sentence[4561] = "是我的神，";
  Sentence[4562] = "是我所倚靠的。";
  Sentence[4563] = "他必救你脫離捕鳥人的網羅和毒害的瘟疫。";
  Sentence[4564] = "他必用自己的翎毛遮蔽你；";
  Sentence[4565] = "你要投靠在他的翅膀底下；";
  Sentence[4566] = "他的誠實是大小的盾牌。";
  Sentence[4567] = "你必不怕黑夜的驚駭，";
  Sentence[4568] = "或是白日飛的箭，";
  Sentence[4569] = "也不怕黑夜行的瘟疫，";
  Sentence[4570] = "或是午間滅人的毒病。";
  Sentence[4571] = "雖有千人仆倒在你旁邊，";
  Sentence[4572] = "萬人仆倒在你右邊，";
  Sentence[4573] = "這災卻不得臨近你。";
  Sentence[4574] = "你惟親眼觀看，";
  Sentence[4575] = "見惡人遭報。";
  Sentence[4576] = "耶和華是我的避難所；";
  Sentence[4577] = "你已將至高者當你的居所，";
  Sentence[4578] = "禍患必不臨到你，";
  Sentence[4579] = "災害也不挨近你的帳棚。";
  Sentence[4580] = "因他要為你吩咐他的使者，";
  Sentence[4581] = "在你行的一切道路上保護你。";
  Sentence[4582] = "他們要用手托著你，";
  Sentence[4583] = "免得你的腳碰在石頭上。";
  Sentence[4584] = "你要踹在獅子和虺蛇的身上，";
  Sentence[4585] = "踐踏少壯獅子和大蛇。";
  Sentence[4586] = "神說：";
  Sentence[4587] = "因為他專心愛我，";
  Sentence[4588] = "我就要搭救他；";
  Sentence[4589] = "因為他知道我的名，";
  Sentence[4590] = "我要把他安置在高處。";
  Sentence[4591] = "他若求告我，";
  Sentence[4592] = "我就應允他；";
  Sentence[4593] = "他在急難中，";
  Sentence[4594] = "我要與他同在；";
  Sentence[4595] = "我要搭救他，";
  Sentence[4596] = "使他尊貴。";
  Sentence[4597] = "我要使他足享長壽，";
  Sentence[4598] = "將我的救恩顯明給他。";
  Sentence[4599] = "詩篇九十二篇";
  Sentence[4600] = "稱謝耶和華！";
  Sentence[4601] = "歌頌你至高者的名！";
  Sentence[4602] = "用十弦的樂器和瑟，";
  Sentence[4603] = "用琴彈幽雅的聲音，";
  Sentence[4604] = "早晨傳揚你的慈愛；";
  Sentence[4605] = "每夜傳揚你的信實。";
  Sentence[4606] = "這本為美事。";
  Sentence[4607] = "因你－";
  Sentence[4608] = "耶和華藉著你的作為叫我高興，";
  Sentence[4609] = "我要因你手的工作歡呼。";
  Sentence[4610] = "耶和華啊，";
  Sentence[4611] = "你的工作何其大！";
  Sentence[4612] = "你的心思極其深！";
  Sentence[4613] = "畜類人不曉得；";
  Sentence[4614] = "愚頑人也不明白。";
  Sentence[4615] = "惡人茂盛如草，";
  Sentence[4616] = "一切作孽之人發旺的時候，";
  Sentence[4617] = "正是他們要滅亡，";
  Sentence[4618] = "直到永遠。";
  Sentence[4619] = "惟你－";
  Sentence[4620] = "耶和華是至高，";
  Sentence[4621] = "直到永遠。";
  Sentence[4622] = "耶和華啊，";
  Sentence[4623] = "你的仇敵都要滅亡；";
  Sentence[4624] = "一切作孽的也要離散。";
  Sentence[4625] = "你卻高舉了我的角，";
  Sentence[4626] = "如野牛的角；";
  Sentence[4627] = "我是被新油膏了的。";
  Sentence[4628] = "我眼睛看見仇敵遭報；";
  Sentence[4629] = "我耳朵聽見那些起來攻擊我的惡人受罰。";
  Sentence[4630] = "義人要發旺如棕樹，";
  Sentence[4631] = "生長如利巴嫩的香柏樹。";
  Sentence[4632] = "他們栽於耶和華的殿中，";
  Sentence[4633] = "發旺在我們神的院裡。";
  Sentence[4634] = "他們年老的時候仍要結果子，";
  Sentence[4635] = "要滿了汁漿而常發青，";
  Sentence[4636] = "好顯明耶和華是正直的。";
  Sentence[4637] = "他是我的磐石，";
  Sentence[4638] = "在他毫無不義。";
  Sentence[4639] = "詩篇九十三篇";
  Sentence[4640] = "耶和華作王！";
  Sentence[4641] = "他以威嚴為衣穿上；";
  Sentence[4642] = "耶和華以能力為衣，";
  Sentence[4643] = "以能力束腰，";
  Sentence[4644] = "世界就堅定，";
  Sentence[4645] = "不得動搖。";
  Sentence[4646] = "你的寶座從太初立定；";
  Sentence[4647] = "你從亙古就有。";
  Sentence[4648] = "耶和華啊，";
  Sentence[4649] = "大水揚起，";
  Sentence[4650] = "大水發聲，";
  Sentence[4651] = "波浪澎湃。";
  Sentence[4652] = "耶和華在高處大有能力，";
  Sentence[4653] = "勝過諸水的響聲，";
  Sentence[4654] = "洋海的大浪。";
  Sentence[4655] = "耶和華啊，";
  Sentence[4656] = "你的法度最的確；";
  Sentence[4657] = "你的殿永稱為聖，";
  Sentence[4658] = "是合宜的。";
  Sentence[4659] = "詩篇九十四篇";
  Sentence[4660] = "耶和華啊，";
  Sentence[4661] = "你是伸冤的神；";
  Sentence[4662] = "伸冤的神啊，";
  Sentence[4663] = "求你發出光來！";
  Sentence[4664] = "審判世界的主啊，";
  Sentence[4665] = "求你挺身而立，";
  Sentence[4666] = "使驕傲人受應得的報應！";
  Sentence[4667] = "耶和華啊，";
  Sentence[4668] = "惡人誇勝要到幾時呢？";
  Sentence[4669] = "要到幾時呢？";
  Sentence[4670] = "他們絮絮叨叨說傲慢的話；";
  Sentence[4671] = "一切作孽的人都自己誇張。";
  Sentence[4672] = "耶和華啊，";
  Sentence[4673] = "他們強壓你的百姓，";
  Sentence[4674] = "苦害你的產業。";
  Sentence[4675] = "他們殺死寡婦和寄居的，";
  Sentence[4676] = "又殺害孤兒。";
  Sentence[4677] = "他們說：";
  Sentence[4678] = "耶和華必不看見；";
  Sentence[4679] = "雅各的神必不思念。";
  Sentence[4680] = "你們民間的畜類人當思想；";
  Sentence[4681] = "你們愚頑人到幾時才有智慧呢？";
  Sentence[4682] = "造耳朵的，";
  Sentence[4683] = "難道自己不聽見嗎？";
  Sentence[4684] = "造眼睛的，";
  Sentence[4685] = "難道自己不看見嗎？";
  Sentence[4686] = "管教列邦的，";
  Sentence[4687] = "就是叫人得知識的，";
  Sentence[4688] = "難道自己不懲治人嗎？";
  Sentence[4689] = "耶和華知道人的意念是虛妄的。";
  Sentence[4690] = "耶和華啊，";
  Sentence[4691] = "你所管教、";
  Sentence[4692] = "用律法所教訓的人是有福的！";
  Sentence[4693] = "你使他在遭難的日子得享平安；";
  Sentence[4694] = "惟有惡人陷在所挖的坑中。";
  Sentence[4695] = "因為耶和華必不丟棄他的百姓，";
  Sentence[4696] = "也不離棄他的產業。";
  Sentence[4697] = "審判要轉向公義；";
  Sentence[4698] = "心裡正直的，";
  Sentence[4699] = "必都隨從。";
  Sentence[4700] = "誰肯為我起來攻擊作惡的？";
  Sentence[4701] = "誰肯為我站起抵擋作孽的？";
  Sentence[4702] = "若不是耶和華幫助我，";
  Sentence[4703] = "我就住在寂靜之中了。";
  Sentence[4704] = "我正說我失了腳，";
  Sentence[4705] = "耶和華啊，";
  Sentence[4706] = "那時你的慈愛扶助我。";
  Sentence[4707] = "我心裡多憂多疑，";
  Sentence[4708] = "你安慰我，";
  Sentence[4709] = "就使我歡樂。";
  Sentence[4710] = "那藉著律例架弄殘害、";
  Sentence[4711] = "在位上行奸惡的，";
  Sentence[4712] = "豈能與你相交嗎？";
  Sentence[4713] = "他們大家聚集攻擊義人，";
  Sentence[4714] = "將無辜的人定為死罪。";
  Sentence[4715] = "但耶和華向來作了我的高臺；";
  Sentence[4716] = "我的神作了我投靠的磐石。";
  Sentence[4717] = "他叫他們的罪孽歸到他們身上。";
  Sentence[4718] = "他們正在行惡之中，";
  Sentence[4719] = "他要剪除他們；";
  Sentence[4720] = "耶和華－";
  Sentence[4721] = "我們的神要把他們剪除。";
  Sentence[4722] = "詩篇九十五篇";
  Sentence[4723] = "來啊，";
  Sentence[4724] = "我們要向耶和華歌唱，";
  Sentence[4725] = "向拯救我們的磐石歡呼！";
  Sentence[4726] = "我們要來感謝他，";
  Sentence[4727] = "用詩歌向他歡呼！";
  Sentence[4728] = "因耶和華為大神，";
  Sentence[4729] = "為大王，";
  Sentence[4730] = "超乎萬神之上。";
  Sentence[4731] = "地的深處在他手中；";
  Sentence[4732] = "山的高峯也屬他。";
  Sentence[4733] = "海洋屬他，";
  Sentence[4734] = "是他造的；";
  Sentence[4735] = "旱地也是他手造成的。";
  Sentence[4736] = "來啊，";
  Sentence[4737] = "我們要屈身敬拜，";
  Sentence[4738] = "在造我們的耶和華面前跪下。";
  Sentence[4739] = "因為他是我們的神；";
  Sentence[4740] = "我們是他草場的羊，";
  Sentence[4741] = "是他手下的民。";
  Sentence[4742] = "惟願你們今天聽他的話：";
  Sentence[4743] = "你們不可硬著心，";
  Sentence[4744] = "像當日在米利巴，";
  Sentence[4745] = "就是在曠野的瑪撒。";
  Sentence[4746] = "那時，";
  Sentence[4747] = "你們的祖宗試我探我，";
  Sentence[4748] = "並且觀看我的作為。";
  Sentence[4749] = "四十年之久，";
  Sentence[4750] = "我厭煩那世代，";
  Sentence[4751] = "說：";
  Sentence[4752] = "這是心裡迷糊的百姓，";
  Sentence[4753] = "竟不曉得我的作為！";
  Sentence[4754] = "所以，";
  Sentence[4755] = "我在怒中起誓，";
  Sentence[4756] = "說：";
  Sentence[4757] = "他們斷不可進入我的安息！";
  Sentence[4758] = "詩篇九十六篇";
  Sentence[4759] = "你們要向耶和華唱新歌！";
  Sentence[4760] = "全地都要向耶和華歌唱！";
  Sentence[4761] = "要向耶和華歌唱，";
  Sentence[4762] = "稱頌他的名！";
  Sentence[4763] = "天天傳揚他的救恩！";
  Sentence[4764] = "在列邦中述說他的榮耀！";
  Sentence[4765] = "在萬民中述說他的奇事！";
  Sentence[4766] = "因耶和華為大，";
  Sentence[4767] = "當受極大的讚美；";
  Sentence[4768] = "他在萬神之上，";
  Sentence[4769] = "當受敬畏。";
  Sentence[4770] = "外邦的神都屬虛無；";
  Sentence[4771] = "惟獨耶和華創造諸天。";
  Sentence[4772] = "有尊榮和威嚴在他面前；";
  Sentence[4773] = "有能力與華美在他聖所。";
  Sentence[4774] = "民中的萬族啊，";
  Sentence[4775] = "你們要將榮耀、";
  Sentence[4776] = "能力歸給耶和華，";
  Sentence[4777] = "都歸給耶和華！";
  Sentence[4778] = "要將耶和華的名所當得的榮耀歸給他，";
  Sentence[4779] = "拿供物來進入他的院宇。";
  Sentence[4780] = "當以聖潔的妝飾敬拜耶和華；";
  Sentence[4781] = "全地要在他面前戰抖！";
  Sentence[4782] = "人在列邦中要說：";
  Sentence[4783] = "耶和華作王！";
  Sentence[4784] = "世界就堅定，";
  Sentence[4785] = "不得動搖；";
  Sentence[4786] = "他要按公正審判眾民。";
  Sentence[4787] = "願天歡喜，";
  Sentence[4788] = "願地快樂！";
  Sentence[4789] = "願海和其中所充滿的澎湃！";
  Sentence[4790] = "願田和其中所有的都歡樂！";
  Sentence[4791] = "那時，";
  Sentence[4792] = "林中的樹木都要在耶和華面前歡呼。";
  Sentence[4793] = "因為他來了，";
  Sentence[4794] = "他來要審判全地。";
  Sentence[4795] = "他要按公義審判世界，";
  Sentence[4796] = "按他的信實審判萬民。";
  Sentence[4797] = "詩篇九十七篇";
  Sentence[4798] = "耶和華作王！";
  Sentence[4799] = "願地快樂！";
  Sentence[4800] = "願眾海島歡喜！";
  Sentence[4801] = "密雲和幽暗在他的四圍；";
  Sentence[4802] = "公義和公平是他寶座的根基。";
  Sentence[4803] = "有烈火在他前頭行，";
  Sentence[4804] = "燒滅他四圍的敵人。";
  Sentence[4805] = "他的閃電光照世界，";
  Sentence[4806] = "大地看見便震動。";
  Sentence[4807] = "諸山見耶和華的面，";
  Sentence[4808] = "就是全地之主的面，";
  Sentence[4809] = "便消化如蠟。";
  Sentence[4810] = "諸天表明他的公義；";
  Sentence[4811] = "萬民看見他的榮耀。";
  Sentence[4812] = "願一切事奉雕刻的偶像、";
  Sentence[4813] = "靠虛無之神自誇的，";
  Sentence[4814] = "都蒙羞愧。";
  Sentence[4815] = "萬神哪，";
  Sentence[4816] = "你們都當拜他。";
  Sentence[4817] = "耶和華啊，";
  Sentence[4818] = "錫安聽見你的判斷就歡喜；";
  Sentence[4819] = "猶大的城邑也都快樂。";
  Sentence[4820] = "因為你－";
  Sentence[4821] = "耶和華至高，";
  Sentence[4822] = "超乎全地；";
  Sentence[4823] = "你被尊崇，";
  Sentence[4824] = "遠超萬神之上。";
  Sentence[4825] = "你們愛耶和華的，";
  Sentence[4826] = "都當恨惡罪惡；";
  Sentence[4827] = "他保護聖民的性命，";
  Sentence[4828] = "搭救他們脫離惡人的手。";
  Sentence[4829] = "散布亮光是為義人；";
  Sentence[4830] = "預備喜樂是為正直人。";
  Sentence[4831] = "你們義人當靠耶和華歡喜，";
  Sentence[4832] = "稱謝他可記念的聖名。";
  Sentence[4833] = "詩篇九十八篇";
  Sentence[4834] = "你們要向耶和華唱新歌！";
  Sentence[4835] = "因為他行過奇妙的事；";
  Sentence[4836] = "他的右手和聖臂施行救恩。";
  Sentence[4837] = "耶和華發明了他的救恩，";
  Sentence[4838] = "在列邦人眼前顯出公義；";
  Sentence[4839] = "記念他向以色列家所發的慈愛，";
  Sentence[4840] = "所憑的信實。";
  Sentence[4841] = "地的四極都看見我們神的救恩。";
  Sentence[4842] = "全地都要向耶和華歡樂；";
  Sentence[4843] = "要發起大聲，";
  Sentence[4844] = "歡呼歌頌！";
  Sentence[4845] = "要用琴歌頌耶和華，";
  Sentence[4846] = "用琴和詩歌的聲音歌頌他！";
  Sentence[4847] = "用號和角聲，";
  Sentence[4848] = "在大君王耶和華面前歡呼！";
  Sentence[4849] = "願海和其中所充滿的澎湃；";
  Sentence[4850] = "世界和住在其間的也要發聲。";
  Sentence[4851] = "願大水拍手；";
  Sentence[4852] = "願諸山在耶和華面前一同歡呼；";
  Sentence[4853] = "因為他來要審判遍地。";
  Sentence[4854] = "他要按公義審判世界，";
  Sentence[4855] = "按公正審判萬民。";
  Sentence[4856] = "詩篇九十九篇";
  Sentence[4857] = "耶和華作王；";
  Sentence[4858] = "萬民當戰抖！";
  Sentence[4859] = "他坐在二基路伯上，";
  Sentence[4860] = "地當動搖。";
  Sentence[4861] = "耶和華在錫安為大；";
  Sentence[4862] = "他超乎萬民之上。";
  Sentence[4863] = "他們當稱讚他大而可畏的名；";
  Sentence[4864] = "他本為聖！";
  Sentence[4865] = "王有能力，";
  Sentence[4866] = "喜愛公平，";
  Sentence[4867] = "堅立公正，";
  Sentence[4868] = "在雅各中施行公平和公義。";
  Sentence[4869] = "你們當尊崇耶和華－";
  Sentence[4870] = "我們的神，";
  Sentence[4871] = "在他腳凳前下拜。";
  Sentence[4872] = "他本為聖！";
  Sentence[4873] = "在他的祭司中有摩西和亞倫；";
  Sentence[4874] = "在求告他名的人中有撒母耳。";
  Sentence[4875] = "他們求告耶和華，";
  Sentence[4876] = "他就應允他們。";
  Sentence[4877] = "他在雲柱中對他們說話；";
  Sentence[4878] = "他們遵守他的法度和他所賜給他們的律例。";
  Sentence[4879] = "耶和華－";
  Sentence[4880] = "我們的神啊，";
  Sentence[4881] = "你應允他們；";
  Sentence[4882] = "你是赦免他們的神，";
  Sentence[4883] = "卻按他們所行的報應他們。";
  Sentence[4884] = "你們要尊崇耶和華－";
  Sentence[4885] = "我們的神，";
  Sentence[4886] = "在他的聖山下拜，";
  Sentence[4887] = "因為耶和華－";
  Sentence[4888] = "我們的神本為聖！";
  Sentence[4889] = "詩篇一百篇";
  Sentence[4890] = "普天下當向耶和華歡呼！";
  Sentence[4891] = "你們當樂意事奉耶和華，";
  Sentence[4892] = "當來向他歌唱！";
  Sentence[4893] = "你們當曉得耶和華是神！";
  Sentence[4894] = "我們是他造的，";
  Sentence[4895] = "也是屬他的；";
  Sentence[4896] = "我們是他的民，";
  Sentence[4897] = "也是他草場的羊。";
  Sentence[4898] = "當稱謝進入他的門；";
  Sentence[4899] = "當讚美進入他的院。";
  Sentence[4900] = "當感謝他，";
  Sentence[4901] = "稱頌他的名！";
  Sentence[4902] = "因為耶和華本為善。";
  Sentence[4903] = "他的慈愛存到永遠；";
  Sentence[4904] = "他的信實直到萬代。";
  Sentence[4905] = "詩篇一〇一篇";
  Sentence[4906] = "我要歌唱慈愛和公平；";
  Sentence[4907] = "耶和華啊，";
  Sentence[4908] = "我要向你歌頌！";
  Sentence[4909] = "我要用智慧行完全的道。";
  Sentence[4910] = "你幾時到我這裡來呢？";
  Sentence[4911] = "我要存完全的心行在我家中。";
  Sentence[4912] = "邪僻的事，";
  Sentence[4913] = "我都不擺在我眼前；";
  Sentence[4914] = "悖逆人所做的事，";
  Sentence[4915] = "我甚恨惡，";
  Sentence[4916] = "不容沾在我身上。";
  Sentence[4917] = "彎曲的心思，";
  Sentence[4918] = "我必遠離；";
  Sentence[4919] = "一切的惡人，";
  Sentence[4920] = "我不認識。";
  Sentence[4921] = "在暗中讒謗他鄰居的，";
  Sentence[4922] = "我必將他滅絕；";
  Sentence[4923] = "眼目高傲、";
  Sentence[4924] = "心裡驕縱的，";
  Sentence[4925] = "我必不容他。";
  Sentence[4926] = "我眼要看國中的誠實人，";
  Sentence[4927] = "叫他們與我同住；";
  Sentence[4928] = "行為完全的，";
  Sentence[4929] = "他要伺候我。";
  Sentence[4930] = "行詭詐的，";
  Sentence[4931] = "必不得住在我家裡；";
  Sentence[4932] = "說謊話的，";
  Sentence[4933] = "必不得立在我眼前。";
  Sentence[4934] = "我每日早晨要滅絕國中所有的惡人，";
  Sentence[4935] = "好把一切作孽的從耶和華的城裡剪除。";
  Sentence[4936] = "詩篇一〇二篇";
  Sentence[4937] = "耶和華啊，";
  Sentence[4938] = "求你聽我的禱告，";
  Sentence[4939] = "容我的呼求達到你面前！";
  Sentence[4940] = "我在急難的日子，";
  Sentence[4941] = "求你向我側耳；";
  Sentence[4942] = "不要向我掩面！";
  Sentence[4943] = "我呼求的日子，";
  Sentence[4944] = "求你快快應允我！";
  Sentence[4945] = "因為，";
  Sentence[4946] = "我的年日如煙雲消滅；";
  Sentence[4947] = "我的骨頭如火把燒著。";
  Sentence[4948] = "我的心被傷，";
  Sentence[4949] = "如草枯乾，";
  Sentence[4950] = "甚至我忘記吃飯。";
  Sentence[4951] = "因我唉哼的聲音，";
  Sentence[4952] = "我的肉緊貼骨頭。";
  Sentence[4953] = "我如同曠野的鵜鶘；";
  Sentence[4954] = "我好像荒場的鴞鳥。";
  Sentence[4955] = "我警醒不睡；";
  Sentence[4956] = "我像房頂上孤單的麻雀。";
  Sentence[4957] = "我的仇敵終日辱罵我；";
  Sentence[4958] = "向我猖狂的人指著我賭咒。";
  Sentence[4959] = "我吃過爐灰，";
  Sentence[4960] = "如同吃飯；";
  Sentence[4961] = "我所喝的與眼淚攙雜。";
  Sentence[4962] = "這都因你的惱恨和忿怒；";
  Sentence[4963] = "你把我拾起來，";
  Sentence[4964] = "又把我摔下去。";
  Sentence[4965] = "我的年日如日影偏斜；";
  Sentence[4966] = "我也如草枯乾。";
  Sentence[4967] = "惟你－";
  Sentence[4968] = "耶和華必存到永遠；";
  Sentence[4969] = "你可記念的名也存到萬代。";
  Sentence[4970] = "你必起來憐恤錫安，";
  Sentence[4971] = "因現在是可憐他的時候，";
  Sentence[4972] = "日期已經到了。";
  Sentence[4973] = "你的僕人原來喜悅他的石頭，";
  Sentence[4974] = "可憐他的塵土。";
  Sentence[4975] = "列國要敬畏耶和華的名；";
  Sentence[4976] = "世上諸王都敬畏你的榮耀。";
  Sentence[4977] = "因為耶和華建造了錫安，";
  Sentence[4978] = "在他榮耀裡顯現。";
  Sentence[4979] = "他垂聽窮人的禱告，";
  Sentence[4980] = "並不藐視他們的祈求。";
  Sentence[4981] = "這必為後代的人記下，";
  Sentence[4982] = "將來受造的民要讚美耶和華。";
  Sentence[4983] = "因為，";
  Sentence[4984] = "他從至高的聖所垂看；";
  Sentence[4985] = "耶和華從天向地觀察，";
  Sentence[4986] = "要垂聽被囚之人的歎息，";
  Sentence[4987] = "要釋放將要死的人，";
  Sentence[4988] = "使人在錫安傳揚耶和華的名，";
  Sentence[4989] = "在耶路撒冷傳揚讚美他的話，";
  Sentence[4990] = "就是在萬民和列國聚會事奉耶和華的時候。";
  Sentence[4991] = "他使我的力量中道衰弱，";
  Sentence[4992] = "使我的年日短少。";
  Sentence[4993] = "我說：";
  Sentence[4994] = "我的神啊，";
  Sentence[4995] = "不要使我中年去世。";
  Sentence[4996] = "你的年數世世無窮！";
  Sentence[4997] = "你起初立了地的根基；";
  Sentence[4998] = "天也是你手所造的。";
  Sentence[4999] = "天地都要滅沒，";
  Sentence[5000] = "你卻要長存；";
  Sentence[5001] = "天地都要如外衣漸漸舊了。";
  Sentence[5002] = "你要將天地如裡衣更換，";
  Sentence[5003] = "天地就改變了。";
  Sentence[5004] = "惟有你永不改變；";
  Sentence[5005] = "你的年數沒有窮盡。";
  Sentence[5006] = "你僕人的子孫要長存；";
  Sentence[5007] = "他們的後裔要堅立在你面前。";
  Sentence[5008] = "詩篇一〇三篇";
  Sentence[5009] = "我的心哪，";
  Sentence[5010] = "你要稱頌耶和華！";
  Sentence[5011] = "凡在我裡面的，";
  Sentence[5012] = "也要稱頌他的聖名！";
  Sentence[5013] = "我的心哪，";
  Sentence[5014] = "你要稱頌耶和華！";
  Sentence[5015] = "不可忘記他的一切恩惠！";
  Sentence[5016] = "他赦免你的一切罪孽，";
  Sentence[5017] = "醫治你的一切疾病。";
  Sentence[5018] = "他救贖你的命脫離死亡，";
  Sentence[5019] = "以仁愛和慈悲為你的冠冕。";
  Sentence[5020] = "他用美物使你所願的得以知足，";
  Sentence[5021] = "以致你如鷹返老還童。";
  Sentence[5022] = "耶和華施行公義，";
  Sentence[5023] = "為一切受屈的人伸冤。";
  Sentence[5024] = "他使摩西知道他的法則，";
  Sentence[5025] = "叫以色列人曉得他的作為。";
  Sentence[5026] = "耶和華有憐憫，";
  Sentence[5027] = "有恩典，";
  Sentence[5028] = "不輕易發怒，";
  Sentence[5029] = "且有豐盛的慈愛。";
  Sentence[5030] = "他不長久責備，";
  Sentence[5031] = "也不永遠懷怒。";
  Sentence[5032] = "他沒有按我們的罪過待我們，";
  Sentence[5033] = "也沒有照我們的罪孽報應我們。";
  Sentence[5034] = "天離地何等的高，";
  Sentence[5035] = "他的慈愛向敬畏他的人也是何等的大！";
  Sentence[5036] = "東離西有多遠，";
  Sentence[5037] = "他叫我們的過犯離我們也有多遠！";
  Sentence[5038] = "父親怎樣憐恤他的兒女，";
  Sentence[5039] = "耶和華也怎樣憐恤敬畏他的人！";
  Sentence[5040] = "因為他知道我們的本體，";
  Sentence[5041] = "思念我們不過是塵土。";
  Sentence[5042] = "至於世人，";
  Sentence[5043] = "他的年日如草一樣。";
  Sentence[5044] = "他發旺如野地的花，";
  Sentence[5045] = "經風一吹，";
  Sentence[5046] = "便歸無有；";
  Sentence[5047] = "他的原處也不再認識他。";
  Sentence[5048] = "但耶和華的慈愛歸於敬畏他的人，";
  Sentence[5049] = "從亙古到永遠；";
  Sentence[5050] = "他的公義也歸於子子孫孫";
  Sentence[5051] = "就是那些遵守他的約、";
  Sentence[5052] = "記念他的訓詞而遵行的人。";
  Sentence[5053] = "耶和華在天上立定寶座；";
  Sentence[5054] = "他的權柄統管萬有。";
  Sentence[5055] = "聽從他命令、";
  Sentence[5056] = "成全他旨意、";
  Sentence[5057] = "有大能的天使，";
  Sentence[5058] = "都要稱頌耶和華！";
  Sentence[5059] = "你們作他的諸軍，";
  Sentence[5060] = "作他的僕役，";
  Sentence[5061] = "行他所喜悅的，";
  Sentence[5062] = "都要稱頌耶和華！";
  Sentence[5063] = "你們一切被他造的，";
  Sentence[5064] = "在他所治理的各處，";
  Sentence[5065] = "都要稱頌耶和華！";
  Sentence[5066] = "我的心哪，";
  Sentence[5067] = "你要稱頌耶和華！";
  Sentence[5068] = "詩篇一〇四篇";
  Sentence[5069] = "我的心哪，";
  Sentence[5070] = "你要稱頌耶和華！";
  Sentence[5071] = "耶和華－";
  Sentence[5072] = "我的神啊，";
  Sentence[5073] = "你為至大！";
  Sentence[5074] = "你以尊榮威嚴為衣服，";
  Sentence[5075] = "披上亮光，";
  Sentence[5076] = "如披外袍，";
  Sentence[5077] = "鋪張穹蒼，";
  Sentence[5078] = "如鋪幔子，";
  Sentence[5079] = "在水中立樓閣的棟梁，";
  Sentence[5080] = "用雲彩為車輦，";
  Sentence[5081] = "藉著風的翅膀而行，";
  Sentence[5082] = "以風為使者，";
  Sentence[5083] = "以火焰為僕役，";
  Sentence[5084] = "將地立在根基上，";
  Sentence[5085] = "使地永不動搖。";
  Sentence[5086] = "你用深水遮蓋地面，";
  Sentence[5087] = "猶如衣裳；";
  Sentence[5088] = "諸水高過山嶺。";
  Sentence[5089] = "你的斥責一發，";
  Sentence[5090] = "水便奔逃；";
  Sentence[5091] = "你的雷聲一發，";
  Sentence[5092] = "水便奔流。";
  Sentence[5093] = "諸山升上，";
  Sentence[5094] = "諸谷沉下，";
  Sentence[5095] = "歸你為他所安定之地。";
  Sentence[5096] = "你定了界限，";
  Sentence[5097] = "使水不能過去，";
  Sentence[5098] = "不再轉回遮蓋地面。";
  Sentence[5099] = "耶和華使泉源湧在山谷，";
  Sentence[5100] = "流在山間，";
  Sentence[5101] = "使野地的走獸有水喝，";
  Sentence[5102] = "野驢得解其渴。";
  Sentence[5103] = "天上的飛鳥在水旁住宿，";
  Sentence[5104] = "在樹枝上啼叫。";
  Sentence[5105] = "他從樓閣中澆灌山嶺；";
  Sentence[5106] = "因他作為的功效，";
  Sentence[5107] = "地就豐足。";
  Sentence[5108] = "他使草生長，";
  Sentence[5109] = "給六畜吃，";
  Sentence[5110] = "使菜蔬發長，";
  Sentence[5111] = "供給人用，";
  Sentence[5112] = "使人從地裡能得食物，";
  Sentence[5113] = "又得酒能悅人心，";
  Sentence[5114] = "得油能潤人面，";
  Sentence[5115] = "得糧能養人心。";
  Sentence[5116] = "佳美的樹木，";
  Sentence[5117] = "就是利巴嫩的香柏樹，";
  Sentence[5118] = "是耶和華所栽種的，";
  Sentence[5119] = "都滿了汁漿。";
  Sentence[5120] = "雀鳥在其上搭窩；";
  Sentence[5121] = "至於鶴，";
  Sentence[5122] = "松樹是他的房屋。";
  Sentence[5123] = "高山為野山羊的住所；";
  Sentence[5124] = "巖石為沙番的藏處。";
  Sentence[5125] = "你安置月亮為定節令；";
  Sentence[5126] = "日頭自知沉落。";
  Sentence[5127] = "你造黑暗為夜，";
  Sentence[5128] = "林中的百獸就都爬出來。";
  Sentence[5129] = "少壯獅子吼叫，";
  Sentence[5130] = "要抓食，";
  Sentence[5131] = "向神尋求食物。";
  Sentence[5132] = "日頭一出，";
  Sentence[5133] = "獸便躲避，";
  Sentence[5134] = "臥在洞裡。";
  Sentence[5135] = "人出去做工，";
  Sentence[5136] = "勞碌直到晚上。";
  Sentence[5137] = "耶和華啊，";
  Sentence[5138] = "你所造的何其多！";
  Sentence[5139] = "都是你用智慧造成的；";
  Sentence[5140] = "遍地滿了你的豐富。";
  Sentence[5141] = "那裡有海，";
  Sentence[5142] = "又大又廣；";
  Sentence[5143] = "其中有無數的動物，";
  Sentence[5144] = "大小活物都有。";
  Sentence[5145] = "那裡有船行走，";
  Sentence[5146] = "有你所造的鱷魚游泳在其中。";
  Sentence[5147] = "這都仰望你按時給他食物。";
  Sentence[5148] = "你給他們，";
  Sentence[5149] = "他們便拾起來；";
  Sentence[5150] = "你張手，";
  Sentence[5151] = "他們飽得美食。";
  Sentence[5152] = "你掩面，";
  Sentence[5153] = "他們便驚惶；";
  Sentence[5154] = "你收回他們的氣，";
  Sentence[5155] = "他們就死亡，";
  Sentence[5156] = "歸於塵土。";
  Sentence[5157] = "你發出你的靈，";
  Sentence[5158] = "他們便受造；";
  Sentence[5159] = "你使地面更換為新。";
  Sentence[5160] = "願耶和華的榮耀存到永遠！";
  Sentence[5161] = "願耶和華喜悅自己所造的！";
  Sentence[5162] = "他看地，";
  Sentence[5163] = "地便震動；";
  Sentence[5164] = "他摸山，";
  Sentence[5165] = "山就冒煙。";
  Sentence[5166] = "我要一生向耶和華唱詩！";
  Sentence[5167] = "我還活的時候，";
  Sentence[5168] = "要向我神歌頌！";
  Sentence[5169] = "願他以我的默念為甘甜！";
  Sentence[5170] = "我要因耶和華歡喜！";
  Sentence[5171] = "願罪人從世上消滅！";
  Sentence[5172] = "願惡人歸於無有！";
  Sentence[5173] = "我的心哪，";
  Sentence[5174] = "要稱頌耶和華！";
  Sentence[5175] = "你們要讚美耶和華！";
  Sentence[5176] = "詩篇一〇五篇";
  Sentence[5177] = "你們要稱謝耶和華，";
  Sentence[5178] = "求告他的名，";
  Sentence[5179] = "在萬民中傳揚他的作為！";
  Sentence[5180] = "要向他唱詩歌頌，";
  Sentence[5181] = "談論他一切奇妙的作為！";
  Sentence[5182] = "要以他的聖名誇耀！";
  Sentence[5183] = "尋求耶和華的人，";
  Sentence[5184] = "心中應當歡喜！";
  Sentence[5185] = "要尋求耶和華與他的能力，";
  Sentence[5186] = "時常尋求他的面。";
  Sentence[5187] = "他僕人亞伯拉罕的後裔，";
  Sentence[5188] = "他所揀選雅各的子孫哪，";
  Sentence[5189] = "你們要記念他奇妙的作為和他的奇事，";
  Sentence[5190] = "並他口中的判語。";
  Sentence[5191] = "他是耶和華－";
  Sentence[5192] = "我們的神；";
  Sentence[5193] = "全地都有他的判斷。";
  Sentence[5194] = "他記念他的約，";
  Sentence[5195] = "直到永遠；";
  Sentence[5196] = "他所吩咐的話，";
  Sentence[5197] = "直到千代－";
  Sentence[5198] = "就是與亞伯拉罕所立的約，";
  Sentence[5199] = "向以撒所起的誓。";
  Sentence[5200] = "他又將這約向雅各定為律例，";
  Sentence[5201] = "向以色列定為永遠的約，";
  Sentence[5202] = "說：";
  Sentence[5203] = "我必將迦南地賜給你，";
  Sentence[5204] = "作你產業的分。";
  Sentence[5205] = "當時，";
  Sentence[5206] = "他們人丁有限，";
  Sentence[5207] = "數目稀少，";
  Sentence[5208] = "並且在那地為寄居的。";
  Sentence[5209] = "他們從這邦遊到那邦，";
  Sentence[5210] = "從這國行到那國。";
  Sentence[5211] = "他不容什麼人欺負他們，";
  Sentence[5212] = "為他們的緣故責備君王，";
  Sentence[5213] = "說：";
  Sentence[5214] = "不可難為我受膏的人，";
  Sentence[5215] = "也不可惡待我的先知。";
  Sentence[5216] = "他命饑荒降在那地上，";
  Sentence[5217] = "將所倚靠的糧食全行斷絕，";
  Sentence[5218] = "在他們以先打發一個人去－";
  Sentence[5219] = "約瑟被賣為奴僕。";
  Sentence[5220] = "人用腳鐐傷他的腳；";
  Sentence[5221] = "他被鐵鍊捆拘。";
  Sentence[5222] = "耶和華的話試煉他，";
  Sentence[5223] = "直等到他所說的應驗了。";
  Sentence[5224] = "王打發人把他解開，";
  Sentence[5225] = "就是治理眾民的，";
  Sentence[5226] = "把他釋放，";
  Sentence[5227] = "立他作王家之主，";
  Sentence[5228] = "掌管他一切所有的，";
  Sentence[5229] = "使他隨意捆綁他的臣宰，";
  Sentence[5230] = "將智慧教導他的長老。";
  Sentence[5231] = "以色列也到了埃及；";
  Sentence[5232] = "雅各在含地寄居。";
  Sentence[5233] = "耶和華使他的百姓生養眾多，";
  Sentence[5234] = "使他們比敵人強盛，";
  Sentence[5235] = "使敵人的心轉去恨他的百姓，";
  Sentence[5236] = "並用詭計待他的僕人。";
  Sentence[5237] = "他打發他的僕人摩西和他所揀選的亞倫，";
  Sentence[5238] = "在敵人中間顯他的神蹟，";
  Sentence[5239] = "在含地顯他的奇事。";
  Sentence[5240] = "他命黑暗，";
  Sentence[5241] = "就有黑暗；";
  Sentence[5242] = "沒有違背他話的。";
  Sentence[5243] = "他叫埃及的水變為血，";
  Sentence[5244] = "叫他們的魚死了。";
  Sentence[5245] = "在他們的地上以及王宮的內室，";
  Sentence[5246] = "青蛙多多滋生。";
  Sentence[5247] = "他說一聲，";
  Sentence[5248] = "蒼蠅就成群而來，";
  Sentence[5249] = "並有虱子進入他們四境。";
  Sentence[5250] = "他給他們降下冰雹為雨，";
  Sentence[5251] = "在他們的地上降下火焰。";
  Sentence[5252] = "他也擊打他們的葡萄樹和無花果樹，";
  Sentence[5253] = "毀壞他們境內的樹木。";
  Sentence[5254] = "他說一聲，";
  Sentence[5255] = "就有蝗蟲螞蚱上來，";
  Sentence[5256] = "不計其數，";
  Sentence[5257] = "吃盡了他們地上各樣的菜蔬和田地的出產。";
  Sentence[5258] = "他又擊殺他們國內一切的長子，";
  Sentence[5259] = "就是他們強壯時頭生的。";
  Sentence[5260] = "他領自己的百姓帶銀子金子出來；";
  Sentence[5261] = "他支派中沒有一個軟弱的。";
  Sentence[5262] = "他們出來的時候，";
  Sentence[5263] = "埃及人便歡喜；";
  Sentence[5264] = "原來埃及人懼怕他們。";
  Sentence[5265] = "他鋪張雲彩當遮蓋，";
  Sentence[5266] = "夜間使火光照。";
  Sentence[5267] = "他們一求，";
  Sentence[5268] = "他就使鵪鶉飛來，";
  Sentence[5269] = "並用天上的糧食叫他們飽足。";
  Sentence[5270] = "他打開磐石，";
  Sentence[5271] = "水就湧出；";
  Sentence[5272] = "在乾旱之處，";
  Sentence[5273] = "水流成河。";
  Sentence[5274] = "這都因他記念他的聖言和他的僕人亞伯拉罕。";
  Sentence[5275] = "他帶領百姓歡樂而出，";
  Sentence[5276] = "帶領選民歡呼前往。";
  Sentence[5277] = "他將列國的地賜給他們，";
  Sentence[5278] = "他們便承受眾民勞碌得來的，";
  Sentence[5279] = "好使他們遵他的律例，";
  Sentence[5280] = "守他的律法。";
  Sentence[5281] = "你們要讚美耶和華！";
  Sentence[5282] = "詩篇一〇六篇";
  Sentence[5283] = "你們要讚美耶和華！";
  Sentence[5284] = "要稱謝耶和華，";
  Sentence[5285] = "因他本為善；";
  Sentence[5286] = "他的慈愛永遠長存！";
  Sentence[5287] = "誰能傳說耶和華的大能？";
  Sentence[5288] = "誰能表明他一切的美德？";
  Sentence[5289] = "凡遵守公平；";
  Sentence[5290] = "常行公義的，";
  Sentence[5291] = "這人便為有福！";
  Sentence[5292] = "耶和華啊，";
  Sentence[5293] = "你用恩惠待你的百姓；";
  Sentence[5294] = "求你也用這恩惠記念我，";
  Sentence[5295] = "開你的救恩眷顧我，";
  Sentence[5296] = "使我見你選民的福，";
  Sentence[5297] = "樂你國民的樂，";
  Sentence[5298] = "與你的產業一同誇耀。";
  Sentence[5299] = "我們與我們的祖宗一同犯罪；";
  Sentence[5300] = "我們作了孽，";
  Sentence[5301] = "行了惡。";
  Sentence[5302] = "我們的祖宗在埃及不明白你的奇事，";
  Sentence[5303] = "不記念你豐盛的慈愛，";
  Sentence[5304] = "反倒在紅海行了悖逆。";
  Sentence[5305] = "然而，";
  Sentence[5306] = "他因自己的名拯救他們，";
  Sentence[5307] = "為要彰顯他的大能，";
  Sentence[5308] = "並且斥責紅海，";
  Sentence[5309] = "海便乾了；";
  Sentence[5310] = "他帶領他們經過深處，";
  Sentence[5311] = "如同經過曠野。";
  Sentence[5312] = "他拯救他們脫離恨他們人的手，";
  Sentence[5313] = "從仇敵手中救贖他們。";
  Sentence[5314] = "水淹沒他們的敵人，";
  Sentence[5315] = "沒有一個存留。";
  Sentence[5316] = "那時，";
  Sentence[5317] = "他們才信了他的話，";
  Sentence[5318] = "歌唱讚美他。";
  Sentence[5319] = "等不多時，";
  Sentence[5320] = "他們就忘了他的作為，";
  Sentence[5321] = "不仰望他的指教，";
  Sentence[5322] = "反倒在曠野大起慾心，";
  Sentence[5323] = "在荒地試探神。";
  Sentence[5324] = "他將他們所求的賜給他們，";
  Sentence[5325] = "卻使他們的心靈軟弱。";
  Sentence[5326] = "他們又在營中嫉妒摩西和耶和華的聖者亞倫。";
  Sentence[5327] = "地裂開，";
  Sentence[5328] = "吞下大坍，";
  Sentence[5329] = "掩蓋亞比蘭一黨的人。";
  Sentence[5330] = "有火在他們的黨中發起；";
  Sentence[5331] = "有火焰燒毀了惡人。";
  Sentence[5332] = "他們在何烈山造了牛犢，";
  Sentence[5333] = "叩拜鑄成的像。";
  Sentence[5334] = "如此將他們榮耀的主換為吃草之牛的像，";
  Sentence[5335] = "忘了神－";
  Sentence[5336] = "他們的救主；";
  Sentence[5337] = "他曾在埃及行大事，";
  Sentence[5338] = "在含地行奇事，";
  Sentence[5339] = "在紅海行可畏的事。";
  Sentence[5340] = "所以，";
  Sentence[5341] = "他說要滅絕他們；";
  Sentence[5342] = "若非有他所揀選的摩西站在當中，";
  Sentence[5343] = "使他的忿怒轉消，";
  Sentence[5344] = "恐怕他就滅絕他們。";
  Sentence[5345] = "他們又藐視那美地，";
  Sentence[5346] = "不信他的話，";
  Sentence[5347] = "在自己帳棚內發怨言，";
  Sentence[5348] = "不聽耶和華的聲音。";
  Sentence[5349] = "所以，";
  Sentence[5350] = "他對他們起誓：";
  Sentence[5351] = "必叫他們倒在曠野，";
  Sentence[5352] = "叫他們的後裔倒在列國之中，";
  Sentence[5353] = "分散在各地。";
  Sentence[5354] = "他們又與巴力‧毘珥連合，";
  Sentence[5355] = "且吃了祭死神的物。";
  Sentence[5356] = "他們這樣行，";
  Sentence[5357] = "惹耶和華發怒，";
  Sentence[5358] = "便有瘟疫流行在他們中間。";
  Sentence[5359] = "那時，";
  Sentence[5360] = "非尼哈站起，";
  Sentence[5361] = "刑罰惡人，";
  Sentence[5362] = "瘟疫這才止息。";
  Sentence[5363] = "那就算為他的義，";
  Sentence[5364] = "世世代代，";
  Sentence[5365] = "直到永遠。";
  Sentence[5366] = "他們在米利巴水又叫耶和華發怒，";
  Sentence[5367] = "甚至摩西也受了虧損，";
  Sentence[5368] = "是因他們惹動他的靈，";
  Sentence[5369] = "摩西用嘴說了急躁的話。";
  Sentence[5370] = "他們不照耶和華所吩咐的滅絕外邦人，";
  Sentence[5371] = "反與他們混雜相合，";
  Sentence[5372] = "學習他們的行為，";
  Sentence[5373] = "事奉他們的偶像，";
  Sentence[5374] = "這就成了自己的網羅，";
  Sentence[5375] = "把自己的兒女祭祀鬼魔，";
  Sentence[5376] = "流無辜人的血，";
  Sentence[5377] = "就是自己兒女的血，";
  Sentence[5378] = "把他們祭祀迦南的偶像，";
  Sentence[5379] = "那地就被血污穢了。";
  Sentence[5380] = "這樣，";
  Sentence[5381] = "他們被自己所做的污穢了，";
  Sentence[5382] = "在行為上犯了邪淫。";
  Sentence[5383] = "所以，";
  Sentence[5384] = "耶和華的怒氣向他的百姓發作，";
  Sentence[5385] = "憎惡他的產業，";
  Sentence[5386] = "將他們交在外邦人的手裡；";
  Sentence[5387] = "恨他們的人就轄制他們。";
  Sentence[5388] = "他們的仇敵也欺壓他們，";
  Sentence[5389] = "他們就伏在敵人手下。";
  Sentence[5390] = "他屢次搭救他們，";
  Sentence[5391] = "他們卻設謀背逆，";
  Sentence[5392] = "因自己的罪孽降為卑下。";
  Sentence[5393] = "然而，";
  Sentence[5394] = "他聽見他們哀告的時候，";
  Sentence[5395] = "就眷顧他們的急難，";
  Sentence[5396] = "為他們記念他的約，";
  Sentence[5397] = "照他豐盛的慈愛後悔。";
  Sentence[5398] = "他也使他們在凡擄掠他們的人面前蒙憐恤。";
  Sentence[5399] = "耶和華－";
  Sentence[5400] = "我們的神啊，";
  Sentence[5401] = "求你拯救我們，";
  Sentence[5402] = "從外邦中招聚我們，";
  Sentence[5403] = "我們好稱讚你的聖名，";
  Sentence[5404] = "以讚美你為誇勝。";
  Sentence[5405] = "耶和華－";
  Sentence[5406] = "以色列的神是應當稱頌的，";
  Sentence[5407] = "從亙古直到永遠。";
  Sentence[5408] = "願眾民都說：";
  Sentence[5409] = "阿們！";
  Sentence[5410] = "你們要讚美耶和華！";
  Sentence[5411] = "詩篇一〇七篇";
  Sentence[5412] = "你們要稱謝耶和華，";
  Sentence[5413] = "因他本為善；";
  Sentence[5414] = "他的慈愛永遠長存！";
  Sentence[5415] = "願耶和華的贖民說這話，";
  Sentence[5416] = "就是他從敵人手中所救贖的，";
  Sentence[5417] = "從各地，";
  Sentence[5418] = "從東從西，";
  Sentence[5419] = "從南從北，";
  Sentence[5420] = "所招聚來的。";
  Sentence[5421] = "他們在曠野荒地漂流，";
  Sentence[5422] = "尋不見可住的城邑，";
  Sentence[5423] = "又飢又渴，";
  Sentence[5424] = "心裡發昏。";
  Sentence[5425] = "於是，";
  Sentence[5426] = "他們在苦難中哀求耶和華；";
  Sentence[5427] = "他從他們的禍患中搭救他們，";
  Sentence[5428] = "又領他們行走直路，";
  Sentence[5429] = "使他們往可居住的城邑。";
  Sentence[5430] = "但願人因耶和華的慈愛和他向人所行的奇事都稱讚他；";
  Sentence[5431] = "因他使心裡渴慕的人得以知足，";
  Sentence[5432] = "使心裡飢餓的人得飽美物。";
  Sentence[5433] = "那些坐在黑暗中、";
  Sentence[5434] = "死蔭裡的人被困苦和鐵鍊捆鎖，";
  Sentence[5435] = "是因他們違背神的話語，";
  Sentence[5436] = "藐視至高者的旨意。";
  Sentence[5437] = "所以，";
  Sentence[5438] = "他用勞苦治服他們的心；";
  Sentence[5439] = "他們仆倒，";
  Sentence[5440] = "無人扶助。";
  Sentence[5441] = "於是，";
  Sentence[5442] = "他們在苦難中哀求耶和華；";
  Sentence[5443] = "他從他們的禍患中拯救他們。";
  Sentence[5444] = "他從黑暗中和死蔭裡領他們出來，";
  Sentence[5445] = "折斷他們的綁索。";
  Sentence[5446] = "但願人因耶和華的慈愛和他向人所行的奇事都稱讚他；";
  Sentence[5447] = "因為他打破了銅門，";
  Sentence[5448] = "砍斷了鐵閂。";
  Sentence[5449] = "愚妄人因自己的過犯和自己的罪孽便受苦楚。";
  Sentence[5450] = "他們心裡厭惡各樣的食物，";
  Sentence[5451] = "就臨近死門。";
  Sentence[5452] = "於是，";
  Sentence[5453] = "他們在苦難中哀求耶和華；";
  Sentence[5454] = "他從他們的禍患中拯救他們。";
  Sentence[5455] = "他發命醫治他們，";
  Sentence[5456] = "救他們脫離死亡。";
  Sentence[5457] = "但願人因耶和華的慈愛和他向人所行的奇事都稱讚他。";
  Sentence[5458] = "願他們以感謝為祭獻給他，";
  Sentence[5459] = "歡呼述說他的作為！";
  Sentence[5460] = "在海上坐船，";
  Sentence[5461] = "在大水中經理事務的，";
  Sentence[5462] = "他們看見耶和華的作為，";
  Sentence[5463] = "並他在深水中的奇事。";
  Sentence[5464] = "因他一吩咐，";
  Sentence[5465] = "狂風就起來，";
  Sentence[5466] = "海中的波浪也揚起。";
  Sentence[5467] = "他們上到天空，";
  Sentence[5468] = "下到海底；";
  Sentence[5469] = "他們的心因患難便消化。";
  Sentence[5470] = "他們搖搖幌幌，";
  Sentence[5471] = "東倒西歪，";
  Sentence[5472] = "好像醉酒的人；";
  Sentence[5473] = "他們的智慧無法可施。";
  Sentence[5474] = "於是，";
  Sentence[5475] = "他們在苦難中哀求耶和華，";
  Sentence[5476] = "他從他們的禍患中領出他們來。";
  Sentence[5477] = "他使狂風止息，";
  Sentence[5478] = "波浪就平靜。";
  Sentence[5479] = "風息浪靜，";
  Sentence[5480] = "他們便歡喜；";
  Sentence[5481] = "他就引他們到所願去的海口。";
  Sentence[5482] = "但願人因耶和華的慈愛和他向人所行的奇事都稱讚他。";
  Sentence[5483] = "願他們在民的會中尊崇他，";
  Sentence[5484] = "在長老的位上讚美他！";
  Sentence[5485] = "他使江河變為曠野，";
  Sentence[5486] = "叫水泉變為乾渴之地，";
  Sentence[5487] = "使肥地變為鹼地；";
  Sentence[5488] = "這都因其間居民的罪惡。";
  Sentence[5489] = "他使曠野變為水潭，";
  Sentence[5490] = "叫旱地變為水泉。";
  Sentence[5491] = "他使飢餓的人住在那裡，";
  Sentence[5492] = "好建造可住的城邑，";
  Sentence[5493] = "又種田地，";
  Sentence[5494] = "栽葡萄園，";
  Sentence[5495] = "得享所出的土產。";
  Sentence[5496] = "他又賜福給他們，";
  Sentence[5497] = "叫他們生養眾多，";
  Sentence[5498] = "也不叫他們的牲畜減少。";
  Sentence[5499] = "他們又因暴虐、";
  Sentence[5500] = "患難、";
  Sentence[5501] = "愁苦，";
  Sentence[5502] = "就減少且卑下。";
  Sentence[5503] = "他使君王蒙羞被辱，";
  Sentence[5504] = "使他們在荒廢無路之地漂流。";
  Sentence[5505] = "他卻將窮乏人安置在高處，";
  Sentence[5506] = "脫離苦難，";
  Sentence[5507] = "使他的家屬多如羊群。";
  Sentence[5508] = "正直人看見就歡喜；";
  Sentence[5509] = "罪孽之輩必塞口無言。";
  Sentence[5510] = "凡有智慧的，";
  Sentence[5511] = "必在這些事上留心，";
  Sentence[5512] = "也必思想耶和華的慈愛。";
  Sentence[5513] = "詩篇一〇八篇";
  Sentence[5514] = "神啊，";
  Sentence[5515] = "我心堅定；";
  Sentence[5516] = "我口要唱詩歌頌！";
  Sentence[5517] = "琴瑟啊，";
  Sentence[5518] = "你們當醒起！";
  Sentence[5519] = "我自己要極早醒起！";
  Sentence[5520] = "耶和華啊，";
  Sentence[5521] = "我要在萬民中稱謝你，";
  Sentence[5522] = "在列邦中歌頌你！";
  Sentence[5523] = "因為，";
  Sentence[5524] = "你的慈愛大過諸天；";
  Sentence[5525] = "你的誠實達到穹蒼。";
  Sentence[5526] = "神啊，";
  Sentence[5527] = "願你崇高過於諸天！";
  Sentence[5528] = "願你的榮耀高過全地！";
  Sentence[5529] = "求你應允我們，";
  Sentence[5530] = "用右手拯救我們，";
  Sentence[5531] = "好叫你所親愛的人得救。";
  Sentence[5532] = "神已經指著他的聖潔說：";
  Sentence[5533] = "我要歡樂；";
  Sentence[5534] = "我要分開示劍，";
  Sentence[5535] = "丈量疏割谷。";
  Sentence[5536] = "基列是我的；";
  Sentence[5537] = "瑪拿西是我的；";
  Sentence[5538] = "以法蓮是護衛我頭的；";
  Sentence[5539] = "猶大是我的杖；";
  Sentence[5540] = "摩押是我的沐浴盆；";
  Sentence[5541] = "我要向以東拋鞋；";
  Sentence[5542] = "我必因勝非利士呼喊。";
  Sentence[5543] = "誰能領我進堅固城？";
  Sentence[5544] = "誰能引我到以東地？";
  Sentence[5545] = "神啊，";
  Sentence[5546] = "你不是丟棄了我們嗎？";
  Sentence[5547] = "神啊，";
  Sentence[5548] = "你不和我們的軍兵同去嗎？";
  Sentence[5549] = "求你幫助我們攻擊敵人，";
  Sentence[5550] = "因為人的幫助是枉然的。";
  Sentence[5551] = "我們倚靠神才得施展大能，";
  Sentence[5552] = "因為踐踏我們敵人的就是他。";
  Sentence[5553] = "詩篇一〇九篇";
  Sentence[5554] = "我所讚美的神啊，";
  Sentence[5555] = "求你不要閉口不言。";
  Sentence[5556] = "因為惡人的嘴和詭詐人的口已經張開攻擊我；";
  Sentence[5557] = "他們用撒謊的舌頭對我說話。";
  Sentence[5558] = "他們圍繞我，";
  Sentence[5559] = "說怨恨的話，";
  Sentence[5560] = "又無故地攻打我。";
  Sentence[5561] = "他們與我為敵以報我愛，";
  Sentence[5562] = "但我專心祈禱。";
  Sentence[5563] = "他們向我以惡報善，";
  Sentence[5564] = "以恨報愛。";
  Sentence[5565] = "願你派一個惡人轄制他，";
  Sentence[5566] = "派一個對頭站在他右邊！";
  Sentence[5567] = "他受審判的時候，";
  Sentence[5568] = "願他出來擔當罪名！";
  Sentence[5569] = "願他的祈禱反成為罪！";
  Sentence[5570] = "願他的年日短少！";
  Sentence[5571] = "願別人得他的職分！";
  Sentence[5572] = "願他的兒女為孤兒，";
  Sentence[5573] = "他的妻子為寡婦！";
  Sentence[5574] = "願他的兒女漂流討飯，";
  Sentence[5575] = "從他們荒涼之處出來求食！";
  Sentence[5576] = "願強暴的債主牢籠他一切所有的！";
  Sentence[5577] = "願外人搶他勞碌得來的！";
  Sentence[5578] = "願無人向他延綿施恩！";
  Sentence[5579] = "願無人可憐他的孤兒！";
  Sentence[5580] = "願他的後人斷絕，";
  Sentence[5581] = "名字被塗抹，";
  Sentence[5582] = "不傳於下代！";
  Sentence[5583] = "願他祖宗的罪孽被耶和華記念！";
  Sentence[5584] = "願他母親的罪過不被塗抹！";
  Sentence[5585] = "願這些罪常在耶和華面前，";
  Sentence[5586] = "使他的名號斷絕於世！";
  Sentence[5587] = "因為他不想施恩，";
  Sentence[5588] = "卻逼迫困苦窮乏的和傷心的人，";
  Sentence[5589] = "要把他們治死。";
  Sentence[5590] = "他愛咒罵，";
  Sentence[5591] = "咒罵就臨到他；";
  Sentence[5592] = "他不喜愛福樂，";
  Sentence[5593] = "福樂就與他遠離！";
  Sentence[5594] = "他拿咒罵當衣服穿上；";
  Sentence[5595] = "這咒罵就如水進他裡面，";
  Sentence[5596] = "像油入他的骨頭。";
  Sentence[5597] = "願這咒罵當他遮身的衣服，";
  Sentence[5598] = "當他常束的腰帶！";
  Sentence[5599] = "這就是我對頭和用惡言議論我的人從耶和華那裡所受的報應。";
  Sentence[5600] = "主－";
  Sentence[5601] = "耶和華啊，";
  Sentence[5602] = "求你為你的名恩待我；";
  Sentence[5603] = "因你的慈愛美好，";
  Sentence[5604] = "求你搭救我！";
  Sentence[5605] = "因為我困苦窮乏，";
  Sentence[5606] = "內心受傷。";
  Sentence[5607] = "我如日影漸漸偏斜而去；";
  Sentence[5608] = "我如蝗蟲被抖出來。";
  Sentence[5609] = "我因禁食，";
  Sentence[5610] = "膝骨軟弱；";
  Sentence[5611] = "我身上的肉也漸漸瘦了。";
  Sentence[5612] = "我受他們的羞辱，";
  Sentence[5613] = "他們看見我便搖頭。";
  Sentence[5614] = "耶和華－";
  Sentence[5615] = "我的神啊，";
  Sentence[5616] = "求你幫助我，";
  Sentence[5617] = "照你的慈愛拯救我，";
  Sentence[5618] = "使他們知道這是你的手，";
  Sentence[5619] = "是你－";
  Sentence[5620] = "耶和華所行的事。";
  Sentence[5621] = "任憑他們咒罵，";
  Sentence[5622] = "惟願你賜福；";
  Sentence[5623] = "他們幾時起來就必蒙羞，";
  Sentence[5624] = "你的僕人卻要歡喜。";
  Sentence[5625] = "願我的對頭披戴羞辱！";
  Sentence[5626] = "願他們以自己的羞愧為外袍遮身！";
  Sentence[5627] = "我要用口極力稱謝耶和華；";
  Sentence[5628] = "我要在眾人中間讚美他；";
  Sentence[5629] = "因為他必站在窮乏人的右邊，";
  Sentence[5630] = "要救他脫離審判他靈魂的人。";
  Sentence[5631] = "詩篇一一〇篇";
  Sentence[5632] = "耶和華對我主說：";
  Sentence[5633] = "你坐在我的右邊，";
  Sentence[5634] = "等我使你仇敵作你的腳凳。";
  Sentence[5635] = "耶和華必使你從錫安伸出能力的杖來；";
  Sentence[5636] = "你要在你仇敵中掌權。";
  Sentence[5637] = "當你掌權的日子，";
  Sentence[5638] = "你的民要以聖潔的妝飾為衣，";
  Sentence[5639] = "甘心犧牲自己；";
  Sentence[5640] = "你的民多如清晨的甘露。";
  Sentence[5641] = "耶和華起了誓，";
  Sentence[5642] = "決不後悔，";
  Sentence[5643] = "說：";
  Sentence[5644] = "你是照著麥基洗德的等次永遠為祭司。";
  Sentence[5645] = "在你右邊的主，";
  Sentence[5646] = "當他發怒的日子，";
  Sentence[5647] = "必打傷列王。";
  Sentence[5648] = "他要在列邦中刑罰惡人，";
  Sentence[5649] = "屍首就遍滿各處；";
  Sentence[5650] = "他要在許多國中打破仇敵的頭。";
  Sentence[5651] = "他要喝路旁的河水，";
  Sentence[5652] = "因此必擡起頭來。";
  Sentence[5653] = "詩篇一一一篇";
  Sentence[5654] = "你們要讚美耶和華！";
  Sentence[5655] = "我要在正直人的大會中，";
  Sentence[5656] = "並公會中，";
  Sentence[5657] = "一心稱謝耶和華。";
  Sentence[5658] = "耶和華的作為本為大；";
  Sentence[5659] = "凡喜愛的都必考察。";
  Sentence[5660] = "他所行的是尊榮和威嚴；";
  Sentence[5661] = "他的公義存到永遠。";
  Sentence[5662] = "他行了奇事，";
  Sentence[5663] = "使人記念；";
  Sentence[5664] = "耶和華有恩惠，";
  Sentence[5665] = "有憐憫。";
  Sentence[5666] = "他賜糧食給敬畏他的人；";
  Sentence[5667] = "他必永遠記念他的約。";
  Sentence[5668] = "他向百姓顯出大能的作為，";
  Sentence[5669] = "把外邦的地賜給他們為業。";
  Sentence[5670] = "他手所行的是誠實公平；";
  Sentence[5671] = "他的訓詞都是確實的，";
  Sentence[5672] = "是永永遠遠堅定的，";
  Sentence[5673] = "是按誠實正直設立的。";
  Sentence[5674] = "他向百姓施行救贖，";
  Sentence[5675] = "命定他的約，";
  Sentence[5676] = "直到永遠；";
  Sentence[5677] = "他的名聖而可畏。";
  Sentence[5678] = "敬畏耶和華是智慧的開端；";
  Sentence[5679] = "凡遵行他命令的是聰明人。";
  Sentence[5680] = "耶和華是永遠當讚美的！";
  Sentence[5681] = "詩篇一一二篇";
  Sentence[5682] = "你們要讚美耶和華！";
  Sentence[5683] = "敬畏耶和華，";
  Sentence[5684] = "甚喜愛他命令的，";
  Sentence[5685] = "這人便為有福！";
  Sentence[5686] = "他的後裔在世必強盛；";
  Sentence[5687] = "正直人的後代必要蒙福。";
  Sentence[5688] = "他家中有貨物，";
  Sentence[5689] = "有錢財；";
  Sentence[5690] = "他的公義存到永遠。";
  Sentence[5691] = "正直人在黑暗中，";
  Sentence[5692] = "有光向他發現；";
  Sentence[5693] = "他有恩惠，";
  Sentence[5694] = "有憐憫，";
  Sentence[5695] = "有公義。";
  Sentence[5696] = "施恩與人、";
  Sentence[5697] = "借貸與人的，";
  Sentence[5698] = "這人事情順利；";
  Sentence[5699] = "他被審判的時候要訴明自己的冤。";
  Sentence[5700] = "他永不動搖；";
  Sentence[5701] = "義人被記念，";
  Sentence[5702] = "直到永遠。";
  Sentence[5703] = "他必不怕凶惡的信息；";
  Sentence[5704] = "他心堅定，";
  Sentence[5705] = "倚靠耶和華。";
  Sentence[5706] = "他心確定，";
  Sentence[5707] = "總不懼怕，";
  Sentence[5708] = "直到他看見敵人遭報。";
  Sentence[5709] = "他施捨錢財，";
  Sentence[5710] = "賙濟貧窮；";
  Sentence[5711] = "他的仁義存到永遠。";
  Sentence[5712] = "他的角必被高舉，";
  Sentence[5713] = "大有榮耀。";
  Sentence[5714] = "惡人看見便惱恨，";
  Sentence[5715] = "必咬牙而消化；";
  Sentence[5716] = "惡人的心願要歸滅絕。";
  Sentence[5717] = "詩篇一一三篇";
  Sentence[5718] = "你們要讚美耶和華！";
  Sentence[5719] = "耶和華的僕人哪，";
  Sentence[5720] = "你們要讚美，";
  Sentence[5721] = "讚美耶和華的名！";
  Sentence[5722] = "耶和華的名是應當稱頌的，";
  Sentence[5723] = "從今時直到永遠！";
  Sentence[5724] = "從日出之地到日落之處，";
  Sentence[5725] = "耶和華的名是應當讚美的！";
  Sentence[5726] = "耶和華超乎萬民之上；";
  Sentence[5727] = "他的榮耀高過諸天。";
  Sentence[5728] = "誰像耶和華－";
  Sentence[5729] = "我們的神呢？";
  Sentence[5730] = "他坐在至高之處，";
  Sentence[5731] = "自己謙卑，";
  Sentence[5732] = "觀看天上地下的事。";
  Sentence[5733] = "他從灰塵裡擡舉貧寒人，";
  Sentence[5734] = "從糞堆中提拔窮乏人，";
  Sentence[5735] = "使他們與王子同坐，";
  Sentence[5736] = "就是與本國的王子同坐。";
  Sentence[5737] = "他使不能生育的婦人安居家中，";
  Sentence[5738] = "為多子的樂母。";
  Sentence[5739] = "你們要讚美耶和華！";
  Sentence[5740] = "詩篇一一四篇";
  Sentence[5741] = "以色列出了埃及，";
  Sentence[5742] = "雅各家離開說異言之民；";
  Sentence[5743] = "那時，";
  Sentence[5744] = "猶大為主的聖所，";
  Sentence[5745] = "以色列為他所治理的國度。";
  Sentence[5746] = "滄海看見就奔逃；";
  Sentence[5747] = "約但河也倒流。";
  Sentence[5748] = "大山踴躍，";
  Sentence[5749] = "如公羊；";
  Sentence[5750] = "小山跳舞，";
  Sentence[5751] = "如羊羔。";
  Sentence[5752] = "滄海啊，";
  Sentence[5753] = "你為何奔逃？";
  Sentence[5754] = "約但哪，";
  Sentence[5755] = "你為何倒流？";
  Sentence[5756] = "大山哪，";
  Sentence[5757] = "你為何踴躍，";
  Sentence[5758] = "如公羊？";
  Sentence[5759] = "小山哪，";
  Sentence[5760] = "你為何跳舞，";
  Sentence[5761] = "如羊羔？";
  Sentence[5762] = "大地啊，";
  Sentence[5763] = "你因見主的面，";
  Sentence[5764] = "就是雅各神的面，";
  Sentence[5765] = "便要震動。";
  Sentence[5766] = "他叫磐石變為水池，";
  Sentence[5767] = "叫堅石變為泉源。";
  Sentence[5768] = "詩篇一一五篇";
  Sentence[5769] = "耶和華啊，";
  Sentence[5770] = "榮耀不要歸與我們，";
  Sentence[5771] = "不要歸與我們；";
  Sentence[5772] = "要因你的慈愛和誠實歸在你的名下！";
  Sentence[5773] = "為何容外邦人說：";
  Sentence[5774] = "他們的神在哪裡呢？";
  Sentence[5775] = "然而，";
  Sentence[5776] = "我們的神在天上，";
  Sentence[5777] = "都隨自己的意旨行事。";
  Sentence[5778] = "他們的偶像是金的，";
  Sentence[5779] = "銀的，";
  Sentence[5780] = "是人手所造的，";
  Sentence[5781] = "有口卻不能言，";
  Sentence[5782] = "有眼卻不能看，";
  Sentence[5783] = "有耳卻不能聽，";
  Sentence[5784] = "有鼻卻不能聞，";
  Sentence[5785] = "有手卻不能摸，";
  Sentence[5786] = "有腳卻不能走，";
  Sentence[5787] = "有喉嚨也不能出聲。";
  Sentence[5788] = "造他的要和他一樣；";
  Sentence[5789] = "凡靠他的也要如此。";
  Sentence[5790] = "以色列啊，";
  Sentence[5791] = "你要倚靠耶和華！";
  Sentence[5792] = "他是你的幫助和你的盾牌。";
  Sentence[5793] = "亞倫家啊，";
  Sentence[5794] = "你們要倚靠耶和華！";
  Sentence[5795] = "他是你們的幫助和你們的盾牌。";
  Sentence[5796] = "你們敬畏耶和華的，";
  Sentence[5797] = "要倚靠耶和華！";
  Sentence[5798] = "他是你們的幫助和你們的盾牌。";
  Sentence[5799] = "耶和華向來眷念我們；";
  Sentence[5800] = "他還要賜福給我們：";
  Sentence[5801] = "要賜福給以色列的家，";
  Sentence[5802] = "賜福給亞倫的家。";
  Sentence[5803] = "凡敬畏耶和華的，";
  Sentence[5804] = "無論大小，";
  Sentence[5805] = "主必賜福給他。";
  Sentence[5806] = "願耶和華叫你們和你們的子孫日見加增。";
  Sentence[5807] = "你們蒙了造天地之耶和華的福！";
  Sentence[5808] = "天，";
  Sentence[5809] = "是耶和華的天；";
  Sentence[5810] = "地，";
  Sentence[5811] = "他卻給了世人。";
  Sentence[5812] = "死人不能讚美耶和華；";
  Sentence[5813] = "下到寂靜中的也都不能。";
  Sentence[5814] = "但我們要稱頌耶和華，";
  Sentence[5815] = "從今時直到永遠。";
  Sentence[5816] = "你們要讚美耶和華！";
  Sentence[5817] = "詩篇一一六篇";
  Sentence[5818] = "我愛耶和華，";
  Sentence[5819] = "因為他聽了我的聲音和我的懇求。";
  Sentence[5820] = "他既向我側耳，";
  Sentence[5821] = "我一生要求告他。";
  Sentence[5822] = "死亡的繩索纏繞我；";
  Sentence[5823] = "陰間的痛苦抓住我；";
  Sentence[5824] = "我遭遇患難愁苦。";
  Sentence[5825] = "那時，";
  Sentence[5826] = "我便求告耶和華的名，";
  Sentence[5827] = "說：";
  Sentence[5828] = "耶和華啊，";
  Sentence[5829] = "求你救我的靈魂！";
  Sentence[5830] = "耶和華有恩惠，";
  Sentence[5831] = "有公義；";
  Sentence[5832] = "我們的神以憐憫為懷。";
  Sentence[5833] = "耶和華保護愚人；";
  Sentence[5834] = "我落到卑微的地步，";
  Sentence[5835] = "他救了我。";
  Sentence[5836] = "我的心哪！";
  Sentence[5837] = "你要仍歸安樂，";
  Sentence[5838] = "因為耶和華用厚恩待你。";
  Sentence[5839] = "主啊，";
  Sentence[5840] = "你救我的命免了死亡，";
  Sentence[5841] = "救我的眼免了流淚，";
  Sentence[5842] = "救我的腳免了跌倒。";
  Sentence[5843] = "我要在耶和華面前行活人之路。";
  Sentence[5844] = "我因信，";
  Sentence[5845] = "所以如此說話；";
  Sentence[5846] = "我受了極大的困苦。";
  Sentence[5847] = "我曾急促地說：";
  Sentence[5848] = "人都是說謊的！";
  Sentence[5849] = "我拿什麼報答耶和華向我所賜的一切厚恩？";
  Sentence[5850] = "我要舉起救恩的杯，";
  Sentence[5851] = "稱揚耶和華的名。";
  Sentence[5852] = "我要在他眾民面前向耶和華還我的願。";
  Sentence[5853] = "在耶和華眼中，";
  Sentence[5854] = "看聖民之死極為寶貴。";
  Sentence[5855] = "耶和華啊，";
  Sentence[5856] = "我真是你的僕人；";
  Sentence[5857] = "我是你的僕人，";
  Sentence[5858] = "是你婢女的兒子。";
  Sentence[5859] = "你已經解開我的綁索。";
  Sentence[5860] = "我要以感謝為祭獻給你，";
  Sentence[5861] = "又要求告耶和華的名。";
  Sentence[5862] = "我要在他眾民面前，";
  Sentence[5863] = "在耶和華殿的院內，";
  Sentence[5864] = "在耶路撒冷當中，";
  Sentence[5865] = "向耶和華還我的願。";
  Sentence[5866] = "你們要讚美耶和華！";
  Sentence[5867] = "詩篇一一七篇";
  Sentence[5868] = "萬國啊，";
  Sentence[5869] = "你們都當讚美耶和華！";
  Sentence[5870] = "萬民哪，";
  Sentence[5871] = "你們都當頌讚他！";
  Sentence[5872] = "因為他向我們大施慈愛；";
  Sentence[5873] = "耶和華的誠實存到永遠。";
  Sentence[5874] = "你們要讚美耶和華！";
  Sentence[5875] = "詩篇一一八篇";
  Sentence[5876] = "你們要稱謝耶和華，";
  Sentence[5877] = "因他本為善；";
  Sentence[5878] = "他的慈愛永遠長存！";
  Sentence[5879] = "願以色列說：";
  Sentence[5880] = "他的慈愛永遠長存！";
  Sentence[5881] = "願亞倫的家說：";
  Sentence[5882] = "他的慈愛永遠長存！";
  Sentence[5883] = "願敬畏耶和華的說：";
  Sentence[5884] = "他的慈愛永遠長存！";
  Sentence[5885] = "我在急難中求告耶和華，";
  Sentence[5886] = "他就應允我，";
  Sentence[5887] = "把我安置在寬闊之地。";
  Sentence[5888] = "有耶和華幫助我，";
  Sentence[5889] = "我必不懼怕，";
  Sentence[5890] = "人能把我怎麼樣呢？";
  Sentence[5891] = "在那幫助我的人中，";
  Sentence[5892] = "有耶和華幫助我，";
  Sentence[5893] = "所以我要看見那恨我的人遭報。";
  Sentence[5894] = "投靠耶和華，";
  Sentence[5895] = "強似倚賴人；";
  Sentence[5896] = "投靠耶和華，";
  Sentence[5897] = "強似倚賴王子。";
  Sentence[5898] = "萬民圍繞我，";
  Sentence[5899] = "我靠耶和華的名必剿滅他們。";
  Sentence[5900] = "他們環繞我，";
  Sentence[5901] = "圍困我，";
  Sentence[5902] = "我靠耶和華的名必剿滅他們。";
  Sentence[5903] = "他們如同蜂子圍繞我，";
  Sentence[5904] = "好像燒荊棘的火，";
  Sentence[5905] = "必被熄滅；";
  Sentence[5906] = "我靠耶和華的名，";
  Sentence[5907] = "必剿滅他們。";
  Sentence[5908] = "你推我，";
  Sentence[5909] = "要叫我跌倒，";
  Sentence[5910] = "但耶和華幫助了我。";
  Sentence[5911] = "耶和華是我的力量，";
  Sentence[5912] = "是我的詩歌；";
  Sentence[5913] = "他也成了我的拯救。";
  Sentence[5914] = "在義人的帳棚裡，";
  Sentence[5915] = "有歡呼拯救的聲音；";
  Sentence[5916] = "耶和華的右手施展大能。";
  Sentence[5917] = "耶和華的右手高舉；";
  Sentence[5918] = "耶和華的右手施展大能。";
  Sentence[5919] = "我必不致死，";
  Sentence[5920] = "仍要存活，";
  Sentence[5921] = "並要傳揚耶和華的作為。";
  Sentence[5922] = "耶和華雖嚴嚴地懲治我，";
  Sentence[5923] = "卻未曾將我交於死亡。";
  Sentence[5924] = "給我敞開義門；";
  Sentence[5925] = "我要進去稱謝耶和華！";
  Sentence[5926] = "這是耶和華的門；";
  Sentence[5927] = "義人要進去！";
  Sentence[5928] = "我要稱謝你，";
  Sentence[5929] = "因為你已經應允我，";
  Sentence[5930] = "又成了我的拯救！";
  Sentence[5931] = "匠人所棄的石頭已成了房角的頭塊石頭。";
  Sentence[5932] = "這是耶和華所做的，";
  Sentence[5933] = "在我們眼中看為希奇。";
  Sentence[5934] = "這是耶和華所定的日子，";
  Sentence[5935] = "我們在其中要高興歡喜！";
  Sentence[5936] = "耶和華啊，";
  Sentence[5937] = "求你拯救！";
  Sentence[5938] = "耶和華啊，";
  Sentence[5939] = "求你使我們亨通！";
  Sentence[5940] = "奉耶和華名來的是應當稱頌的！";
  Sentence[5941] = "我們從耶和華的殿中為你們祝福！";
  Sentence[5942] = "耶和華是神；";
  Sentence[5943] = "他光照了我們。";
  Sentence[5944] = "理當用繩索把祭牲拴住，";
  Sentence[5945] = "牽到壇角那裡。";
  Sentence[5946] = "你是我的神，";
  Sentence[5947] = "我要稱謝你！";
  Sentence[5948] = "你是我的神，";
  Sentence[5949] = "我要尊崇你！";
  Sentence[5950] = "你們要稱謝耶和華，";
  Sentence[5951] = "因他本為善；";
  Sentence[5952] = "他的慈愛永遠長存！";
  Sentence[5953] = "詩篇一一九篇";
  Sentence[5954] = "行為完全、";
  Sentence[5955] = "遵行耶和華律法的，";
  Sentence[5956] = "這人便為有福！";
  Sentence[5957] = "遵守他的法度、";
  Sentence[5958] = "一心尋求他的，";
  Sentence[5959] = "這人便為有福！";
  Sentence[5960] = "這人不做非義的事，";
  Sentence[5961] = "但遵行他的道。";
  Sentence[5962] = "耶和華啊，";
  Sentence[5963] = "你曾將你的訓詞吩咐我們，";
  Sentence[5964] = "為要我們殷勤遵守。";
  Sentence[5965] = "但願我行事堅定，";
  Sentence[5966] = "得以遵守你的律例。";
  Sentence[5967] = "我看重你的一切命令，";
  Sentence[5968] = "就不至於羞愧。";
  Sentence[5969] = "我學了你公義的判語，";
  Sentence[5970] = "就要以正直的心稱謝你。";
  Sentence[5971] = "我必守你的律例；";
  Sentence[5972] = "求你總不要丟棄我！";
  Sentence[5973] = "少年人用什麼潔淨他的行為呢？";
  Sentence[5974] = "是要遵行你的話！";
  Sentence[5975] = "我一心尋求了你；";
  Sentence[5976] = "求你不要叫我偏離你的命令。";
  Sentence[5977] = "我將你的話藏在心裡，";
  Sentence[5978] = "免得我得罪你。";
  Sentence[5979] = "耶和華啊，";
  Sentence[5980] = "你是應當稱頌的！";
  Sentence[5981] = "求你將你的律例教訓我！";
  Sentence[5982] = "我用嘴唇傳揚你口中的一切典章。";
  Sentence[5983] = "我喜悅你的法度，";
  Sentence[5984] = "如同喜悅一切的財物。";
  Sentence[5985] = "我要默想你的訓詞，";
  Sentence[5986] = "看重你的道路。";
  Sentence[5987] = "我要在你的律例中自樂；";
  Sentence[5988] = "我不忘記你的話。";
  Sentence[5989] = "求你用厚恩待你的僕人，";
  Sentence[5990] = "使我存活，";
  Sentence[5991] = "我就遵守你的話。";
  Sentence[5992] = "求你開我的眼睛，";
  Sentence[5993] = "使我看出你律法中的奇妙。";
  Sentence[5994] = "我是在地上作寄居的；";
  Sentence[5995] = "求你不要向我隱瞞你的命令！";
  Sentence[5996] = "我時常切慕你的典章，";
  Sentence[5997] = "甚至心碎。";
  Sentence[5998] = "受咒詛、";
  Sentence[5999] = "偏離你命令的驕傲人，";
  Sentence[6000] = "你已經責備他們。";
  Sentence[6001] = "求你除掉我所受的羞辱和藐視，";
  Sentence[6002] = "因我遵守你的法度。";
  Sentence[6003] = "雖有首領坐著妄論我，";
  Sentence[6004] = "你僕人卻思想你的律例。";
  Sentence[6005] = "你的法度是我所喜樂的，";
  Sentence[6006] = "是我的謀士。";
  Sentence[6007] = "我的性命幾乎歸於塵土；";
  Sentence[6008] = "求你照你的話將我救活！";
  Sentence[6009] = "我述說我所行的，";
  Sentence[6010] = "你應允了我；";
  Sentence[6011] = "求你將你的律例教訓我！";
  Sentence[6012] = "求你使我明白你的訓詞，";
  Sentence[6013] = "我就思想你的奇事。";
  Sentence[6014] = "我的心因愁苦而消化；";
  Sentence[6015] = "求你照你的話使我堅立！";
  Sentence[6016] = "求你使我離開奸詐的道，";
  Sentence[6017] = "開恩將你的律法賜給我！";
  Sentence[6018] = "我揀選了忠信的道，";
  Sentence[6019] = "將你的典章擺在我面前。";
  Sentence[6020] = "我持守你的法度；";
  Sentence[6021] = "耶和華啊，";
  Sentence[6022] = "求你不要叫我羞愧！";
  Sentence[6023] = "你開廣我心的時候，";
  Sentence[6024] = "我就往你命令的道上直奔。";
  Sentence[6025] = "耶和華啊，";
  Sentence[6026] = "求你將你的律例指教我，";
  Sentence[6027] = "我必遵守到底！";
  Sentence[6028] = "求你賜我悟性，";
  Sentence[6029] = "我便遵守你的律法，";
  Sentence[6030] = "且要一心遵守。";
  Sentence[6031] = "求你叫我遵行你的命令，";
  Sentence[6032] = "因為這是我所喜樂的。";
  Sentence[6033] = "求你使我的心趨向你的法度，";
  Sentence[6034] = "不趨向非義之財。";
  Sentence[6035] = "求你叫我轉眼不看虛假，";
  Sentence[6036] = "又叫我在你的道中生活。";
  Sentence[6037] = "你向敬畏你的人所應許的話，";
  Sentence[6038] = "求你向僕人堅定！";
  Sentence[6039] = "求你使我所怕的羞辱遠離我，";
  Sentence[6040] = "因你的典章本為美。";
  Sentence[6041] = "我羨慕你的訓詞；";
  Sentence[6042] = "求你使我在你的公義上生活！";
  Sentence[6043] = "耶和華啊，";
  Sentence[6044] = "願你照你的話，";
  Sentence[6045] = "使你的慈愛，";
  Sentence[6046] = "就是你的救恩，";
  Sentence[6047] = "臨到我身上，";
  Sentence[6048] = "我就有話回答那羞辱我的，";
  Sentence[6049] = "因我倚靠你的話。";
  Sentence[6050] = "求你叫真理的話總不離開我口，";
  Sentence[6051] = "因我仰望你的典章。";
  Sentence[6052] = "我要常守你的律法，";
  Sentence[6053] = "直到永永遠遠。";
  Sentence[6054] = "我要自由而行，";
  Sentence[6055] = "因我素來考究你的訓詞。";
  Sentence[6056] = "我也要在君王面前論說你的法度，";
  Sentence[6057] = "並不至於羞愧。";
  Sentence[6058] = "我要在你的命令中自樂；";
  Sentence[6059] = "這命令素來是我所愛的。";
  Sentence[6060] = "我又要遵行你的命令，";
  Sentence[6061] = "這命令素來是我所愛的；";
  Sentence[6062] = "我也要思想你的律例。";
  Sentence[6063] = "求你記念向你僕人所應許的話，";
  Sentence[6064] = "叫我有盼望。";
  Sentence[6065] = "這話將我救活了；";
  Sentence[6066] = "我在患難中，";
  Sentence[6067] = "因此得安慰。";
  Sentence[6068] = "驕傲的人甚侮慢我，";
  Sentence[6069] = "我卻未曾偏離你的律法。";
  Sentence[6070] = "耶和華啊，";
  Sentence[6071] = "我記念你從古以來的典章，";
  Sentence[6072] = "就得了安慰。";
  Sentence[6073] = "我見惡人離棄你的律法，";
  Sentence[6074] = "就怒氣發作，";
  Sentence[6075] = "猶如火燒。";
  Sentence[6076] = "我在世寄居，";
  Sentence[6077] = "素來以你的律例為詩歌。";
  Sentence[6078] = "耶和華啊，";
  Sentence[6079] = "我夜間記念你的名，";
  Sentence[6080] = "遵守你的律法。";
  Sentence[6081] = "我所以如此，";
  Sentence[6082] = "是因我守你的訓詞。";
  Sentence[6083] = "耶和華是我的福分；";
  Sentence[6084] = "我曾說，";
  Sentence[6085] = "我要遵守你的言語。";
  Sentence[6086] = "我一心求過你的恩；";
  Sentence[6087] = "願你照你的話憐憫我！";
  Sentence[6088] = "我思想我所行的道，";
  Sentence[6089] = "就轉步歸向你的法度。";
  Sentence[6090] = "我急忙遵守你的命令，";
  Sentence[6091] = "並不遲延。";
  Sentence[6092] = "惡人的繩索纏繞我，";
  Sentence[6093] = "我卻沒有忘記你的律法。";
  Sentence[6094] = "我因你公義的典章，";
  Sentence[6095] = "半夜必起來稱謝你。";
  Sentence[6096] = "凡敬畏你、";
  Sentence[6097] = "守你訓詞的人，";
  Sentence[6098] = "我都與他作伴。";
  Sentence[6099] = "耶和華啊，";
  Sentence[6100] = "你的慈愛遍滿大地；";
  Sentence[6101] = "求你將你的律例教訓我！";
  Sentence[6102] = "耶和華啊，";
  Sentence[6103] = "你向來是照你的話善待僕人。";
  Sentence[6104] = "求你將精明和知識賜給我，";
  Sentence[6105] = "因我信了你的命令。";
  Sentence[6106] = "我未受苦以先走迷了路，";
  Sentence[6107] = "現在卻遵守你的話。";
  Sentence[6108] = "你本為善，";
  Sentence[6109] = "所行的也善；";
  Sentence[6110] = "求你將你的律例教訓我！";
  Sentence[6111] = "驕傲人編造謊言攻擊我，";
  Sentence[6112] = "我卻要一心守你的訓詞。";
  Sentence[6113] = "他們心蒙脂油，";
  Sentence[6114] = "我卻喜愛你的律法。";
  Sentence[6115] = "我受苦是於我有益，";
  Sentence[6116] = "為要使我學習你的律例。";
  Sentence[6117] = "你口中的訓言於我有益，";
  Sentence[6118] = "勝於千萬的金銀。";
  Sentence[6119] = "你的手製造我，";
  Sentence[6120] = "建立我；";
  Sentence[6121] = "求你賜我悟性，";
  Sentence[6122] = "可以學習你的命令！";
  Sentence[6123] = "敬畏你的人見我就要歡喜，";
  Sentence[6124] = "因我仰望你的話。";
  Sentence[6125] = "耶和華啊，";
  Sentence[6126] = "我知道你的判語是公義的；";
  Sentence[6127] = "你使我受苦是以誠實待我。";
  Sentence[6128] = "求你照著應許僕人的話，";
  Sentence[6129] = "以慈愛安慰我。";
  Sentence[6130] = "願你的慈悲臨到我，";
  Sentence[6131] = "使我存活，";
  Sentence[6132] = "因你的律法是我所喜愛的。";
  Sentence[6133] = "願驕傲人蒙羞，";
  Sentence[6134] = "因為他們無理地傾覆我；";
  Sentence[6135] = "但我要思想你的訓詞。";
  Sentence[6136] = "願敬畏你的人歸向我，";
  Sentence[6137] = "他們就知道你的法度。";
  Sentence[6138] = "願我的心在你的律例上完全，";
  Sentence[6139] = "使我不致蒙羞。";
  Sentence[6140] = "我心渴想你的救恩，";
  Sentence[6141] = "仰望你的應許。";
  Sentence[6142] = "我因盼望你的應許眼睛失明，";
  Sentence[6143] = "說：";
  Sentence[6144] = "你何時安慰我？";
  Sentence[6145] = "我好像煙薰的皮袋，";
  Sentence[6146] = "卻不忘記你的律例。";
  Sentence[6147] = "你僕人的年日有多少呢？";
  Sentence[6148] = "你幾時向逼迫我的人施行審判呢？";
  Sentence[6149] = "不從你律法的驕傲人為我掘了坑。";
  Sentence[6150] = "你的命令盡都誠實；";
  Sentence[6151] = "他們無理地逼迫我，";
  Sentence[6152] = "求你幫助我！";
  Sentence[6153] = "他們幾乎把我從世上滅絕，";
  Sentence[6154] = "但我沒有離棄你的訓詞。";
  Sentence[6155] = "求你照你的慈愛將我救活，";
  Sentence[6156] = "我就遵守你口中的法度。";
  Sentence[6157] = "耶和華啊，";
  Sentence[6158] = "你的話安定在天，";
  Sentence[6159] = "直到永遠。";
  Sentence[6160] = "你的誠實存到萬代；";
  Sentence[6161] = "你堅定了地，";
  Sentence[6162] = "地就長存。";
  Sentence[6163] = "天地照你的安排存到今日；";
  Sentence[6164] = "萬物都是你的僕役。";
  Sentence[6165] = "我若不是喜愛你的律法，";
  Sentence[6166] = "早就在苦難中滅絕了！";
  Sentence[6167] = "我永不忘記你的訓詞，";
  Sentence[6168] = "因你用這訓詞將我救活了。";
  Sentence[6169] = "我是屬你的，";
  Sentence[6170] = "求你救我，";
