  Sentence[6172] = "惡人等待我，";
  Sentence[6173] = "要滅絕我，";
  Sentence[6174] = "我卻要揣摩你的法度。";
  Sentence[6175] = "我看萬事盡都有限，";
  Sentence[6176] = "惟有你的命令極其寬廣。";
  Sentence[6177] = "我何等愛慕你的律法，";
  Sentence[6178] = "終日不住地思想。";
  Sentence[6179] = "你的命令常存在我心裡，";
  Sentence[6180] = "使我比仇敵有智慧。";
  Sentence[6181] = "我比我的師傅更通達，";
  Sentence[6182] = "因我思想你的法度。";
  Sentence[6183] = "我比年老的更明白，";
  Sentence[6184] = "因我守了你的訓詞。";
  Sentence[6185] = "我禁止我腳走一切的邪路，";
