  Sentence[6191] = "我藉著你的訓詞得以明白，";
  Sentence[6192] = "所以我恨一切的假道。";
  Sentence[6193] = "你的話是我腳前的燈，";
  Sentence[6194] = "是我路上的光。";
  Sentence[6195] = "你公義的典章，";
  Sentence[6196] = "我曾起誓遵守，";
  Sentence[6197] = "我必按誓而行。";
  Sentence[6198] = "我甚是受苦；";
  Sentence[6199] = "耶和華啊，";
  Sentence[6200] = "求你照你的話將我救活！";
  Sentence[6201] = "耶和華啊，";
  Sentence[6202] = "求你悅納我口中的讚美為供物，";
  Sentence[6203] = "又將你的典章教訓我！";
