  Sentence[6259] = "使愚人通達。";
  Sentence[6260] = "我張口而氣喘，";
  Sentence[6261] = "因我切慕你的命令。";
  Sentence[6262] = "求你轉向我，";
  Sentence[6263] = "憐憫我，";
